window.__D("text/zohar-hebrew-translation/c011",{"p":[[9522011479,"<p>שִׁמְעוֹן וְלֵוִי אַחִים. אָמַר רַבִּי יִצְחָק, כָּאן אִחֵד אוֹתָם בְּצַד שְׂמֹאל שֶׁל הַשְּׁכִינָה, שֶׁרָאָה מַעֲשִׂים שֶׁל דִּין קָשֶׁה שֶׁלֹּא יָכוֹל הָעוֹלָם לִסְבֹּל. אָמַר רַבִּי יוֹסֵי, הַבְּרָכָה שֶׁלָּהֶם אֵיפֹה הִיא? אָמַר רַבִּי יִצְחָק, שִׁמְעוֹן לֹא רָאוּי לָזֶה, שֶׁרָאָה לוֹ כַּמָּה מַעֲשִׂים רָעִים, וְלֵוִי שֶׁבָּא מִצַּד הַדִּין הַקָּשֶׁה, וּבְרָכָה לֹא תְלוּיָה בּוֹ, וַאֲפִלּוּ כְּשֶׁבָּא מֹשֶׁה לֹא תָלָה בּוֹ בִּרְכָתוֹ, שֶׁכָּתוּב (דברים לג) בָּרֵךְ ה' חֵילוֹ וּפֹעַל יָדָיו תִּרְצֶה. תָּלוּי בַּקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>בֹּא רְאֵה, כָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. זֶה הַיָּם גָּדוֹל - זוֹ הַשְּׁכִינָה שֶׁעוֹמֶדֶת עַל יַעֲקֹב, כְּשֶׁרָצָה לְהִסְתַּלֵּק מֵהָעוֹלָם. וּרְחַב יָדַיִם - שֶׁהֲרֵי כָּל הָעוֹלָם מִתְמַלֵּא וְנִשְׁלָם וּמִצְטַמְצֵם שָׁם. שָׁם רֶמֶשׂ וְאֵין מִסְפָּר - שֶׁכַּמָּה מַלְאָכִים עֶלְיוֹנִים וּקְדוֹשִׁים נִמְצְאוּ שָׁם. חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת - אֵלּוּ הֵם שְׁנֵים עָשָׂר שְׁבָטִים, בְּנֵי יַעֲקֹב שֶׁנִּמְצְאוּ בָהֶם בִּשְׁלֵמוּת, אֶחָד אַיָּלָה, וְאֶחָד זְאֵב, וְאֶחָד אֲרִי, וְאֶחָד טָלֶה. אָמַר רַבִּי יִצְחָק, אַרְיֵה אֶחָד, וְטָלֶה אֶחָד, אֶחָד זְאֵב, וְאֶחָד גְּדִי, וְכֵן כֻּלָּם, לְהִמָּצֵא חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת.</p>\n<p>רַבִּי יְהוּדָה אָמַר, הַכֹּל יָפֶה, אֲבָל יְהוּדָה אַרְיֵה וְשִׁמְעוֹן שׁוֹר, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים שֶׁהָיוּ מַשְׁגִּיחִים זֶה כְּנֶגֶד זֶה, זֶה מִיָּמִין וְזֶה מִשְּׂמֹאל. לְשׁוֹר שֶׁמַּעֲשָׂיו רָעִים, אָמְרוּ נְצַיֵּר דְּמוּת שֶׁל אַרְיֵה בָּרֶפֶת שֶׁלּוֹ, וְיִסְתַּכֵּל בָּזֶה וְיִפְחַד מִמֶּנּוּ. כָּךְ שִׁמְעוֹן שׁוֹר, יְהוּדָה אַרְיֵה.</p>\n<p>שִׁמְעוֹן לֹא זָכָה לִבְרָכוֹת, אֶלָּא הִדְבִּיק אוֹתוֹ מֹשֶׁה לִיהוּדָה. כָּתוּב כָּאן (דברים לג) שְׁמַע ה' קוֹל יְהוּדָה, וְכָתוּב שָׁם (בראשית כט) כִּי שָׁמַע ה' כִּי שְׂנוּאָה אָנֹכִי. אָמַר רַבִּי יְהוּדָה, שִׁמְעוֹן וְלֵוִי, אֲבִיהֶם הֶעֱלָם לְמֹשֶׁה. אָמַר לוֹ רַבִּי יוֹסֵי, מָה הַטַּעַם אֲבִיהֶם הֶעֱלָם לְמֹשֶׁה? אָמַר לוֹ, אַף אָנוּ נַעֲלֵהוּ לַמְּנוֹרָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה.</p>\n<p>בָּאוּ וְשָׁאֲלוּ אֶת רַבִּי שִׁמְעוֹן. אָמַר, כַּמָּה חֲבִיבִים דְּבָרִים אֵלּוּ. טָפַח בְּיָדוֹ וּבָכָה. אָמַר, מִי יְגַלֶּה אוֹתְךְ נֶאֱמָן הַקָּדוֹשׁ? הִתְעַלֵּיתָ בְּחַיֶּיךְ עַל בְּנֵי אָדָם, הִתְעַלֵּית בִּפְטִירָתְךְ וְנִסְתְּרָה דְמוּתְךְ. מַפְתְּחוֹת רִבּוֹנְךְ נִמְסְרוּ בְיָדְךְ תָּמִיד.</p>\n<p>בֹּא רְאֵה, לְיַעֲקֹב הָיוּ אַרְבַּע נָשִׁים, וְהוֹלִיד בָּנִים מִכֻּלָּן, וְהִתְעַלֶּה (ונתקן) בִּנְשׁוֹתָיו. כְּשֶׁרָצָה יַעֲקֹב לְהִסְתַּלֵּק, עָמְדָה עָלָיו שְׁכִינָה. רָצָה לְבָרֵךְ אֶת אֵלֶּה וְלֹא יָכֹל, מִלִּפְנֵי הַשְּׁכִינָה שֶׁפָּחַד. אָמַר, אֵיךְ אֶעֱשֶׂה, שֶׁהֲרֵי שְׁנֵיהֶם בָּאוּ מִצַּד הַדִּין הַקָּשֶׁה? אִם אַחֲזִיק בַּשְּׁכִינָה - לֹא יָכֹלְתִּי, שֶׁהֲרֵי הָיוּ לִי אַרְבַּע נָשִׁים וְנִתְקַנְתִּי בָהֶן, אֶלָּא אַעֲלֶה אוֹתָן לְבַעַל הַבַּיִת, שֶׁהֲרֵי (בו) הַבַּיִת עוֹמֵד בִּרְשׁוּתוֹ, וּמַה שֶּׁיִּרְצֶה - יַעֲשֶׂה.</p>\n<p>כָּךָ יַעֲקֹב אָמַר, חֲלָקִים שֶׁל נָשִׁים וּבָנִים הֲרֵי לָקַחְתִּי בָּעוֹלָם הַזֶּה וְנִשְׁלַמְתִּי, וְאֵיךְ אֶתְחַזֵּק בַּגְּבִירָה יוֹתֵר? אֶלָּא אַעֲלֶה הַדְּבָרִים לְבַעַל הַגְּבִירָה, וְהוּא יַעֲשֶׂה מַה שֶּׁיִּרְצֶה, וְלֹא יִפְחַד.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, (דברים לג) וְזאת הַבְּרָכָה אֲשֶׁר בֵּרַךְ מֹשֶׁה אִישׁ הָאֱלֹהִים, בַּעַל הַבַּיִת, בַּעַל הַגְּבִירָה, כַּכָּתוּב (במדבר ל) אִישָׁהּ יְקִימֶנּוּ וְאִישָׁהּ יְפֵרֶנּוּ, שֶׁהֲרֵי (שם ז) כַּלּוֹת מֹשֶׁה כָּתוּב. וְעַל כֵּן מֹשֶׁה מְבָרֵךְ אֶת מִי שֶׁרוֹצֶה בְּלִי פַחַד, כְּמוֹ שֶׁבֵּאַרְנוּ. וְלָכֵן אָמַר יַעֲקֹב, הֲרֵי רָאִיתִי שֶׁבָּנַי אֵלֶּה הֵם בְּצַד הַדִּין הַקָּשֶׁה, (יביאו) יָבֹא בַּעַל הַבַּיִת וִיבָרֵךְ אוֹתָם.</p>\n<p>מֹשֶׁה וַדַּאי אִישׁ הָאֱלֹהִים הָיָה, וּרְצוֹנוֹ עוֹשֶׂה בְּבֵיתוֹ, כְּמוֹ שֶׁנֶּאֱמַר אִישָׁהּ יְקִימֶנּוּ, זֶהוּ שֶׁכָּתוּב (שם י) וַיֹּאמֶר מֹשֶׁה קוּמָה ה'. וְאִישָׁהּ יְפֵרֶנּוּ, זֶהוּ שֶׁכָּתוּב וּבְנֻחֹה יֹאמַר שׁוּבָה ה'. וַדַּאי שֶׁבַּעַל הַבַּיִת עוֹשֶׂה אֶת רְצוֹנוֹ וְאֵין מוֹחֶה בְיָדוֹ, כְּמוֹ לְאָדָם שֶׁגּוֹזֵר עַל אִשְׁתּוֹ, וְהִיא עוֹשָׂה רְצוֹנוֹ. וְעַל כָּךְ יַעֲקֹב, אַף עַל גַּב שֶׁהָיָה אָחוּז בְּעֵץ הַחַיִּים, לֹא הָיָה בַּעַל הַבַּיִת אֶלָּא לְמַטָּה. מֹשֶׁה הוּא לְמַעְלָה, וְלָכֵן הֶעֱלָה אוֹתָם לְבַעַל הַבַּיִת.</p>\n<p>בְּסוֹדָם אַל תָּבֹא נַפְשִׁי וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים כה) סוֹד ה' לִירֵאָיו וְגוֹ'. סוֹד ה' לִירֵאָיו - הַסּוֹד הָעֶלְיוֹן שֶׁל הַתּוֹרָה לֹא נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא לְאוֹתָם יִרְאֵי חֵטְא, וּמִי שֶׁהֵם יִרְאֵי חֵטְא, מִתְגַּלֶּה לָהֶם סוֹד עֶלְיוֹן שֶׁל תּוֹרָה. וּמִיהוּ סוֹד הָעֶלְיוֹן שֶׁל הַתּוֹרָה? הֱוֵי אוֹמֵר זוֹ אוֹת בְּרִית קֹדֶשׁ, שֶׁנִּקְרֵאת סוֹד ה' בְּרִית קֹדֶשׁ.</p>\n<p>שִׁמְעוֹן וְלֵוִי הִטְרִיחוּ עַצְמָם עַל סוֹד זֶה בְּאַנְשֵׁי שְׁכֶם שֶׁיִּמּוֹלוּ עַצְמָם וִיקַבְּלוּ עֲלֵיהֶם סוֹד זֶה, וְהַפָּסוּק מֵעִיד שֶׁבְּמִרְמָה. וְעוֹד, בְּמַעֲשֵׂה זִמְרִי בֶּן סָלוּא שֶׁפָּסַל אֶת הַסּוֹד הַזֶּה. וְיַעֲקֹב אָמַר, בְּסוֹדָם אַל תָּבֹא נַפְשִׁי. מִי זוֹ נַפְשִׁי? זוֹ נֶפֶשׁ שֶׁנִּכְנֶסֶת וְנֶאֱחֶזֶת בַּבְּרִית הָעֶלְיוֹנָה לְמַעְלָה, וִנִקְרֵאת נֶפֶשׁ צְרוֹר הַחַיִּים.</p>\n<p>בִּקְֹהָלָם אַל תֵּחַד כְּבוֹדִי, הֲרֵי פֵּרְשׁוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (במדבר טז) וַיַּקְהֵל עֲלֵיהֶם קֹרַח. אַל תֵּחַד כְּבוֹדִי - זֶה כְּבוֹד יִשְׂרָאֵל סְתָם. וְלָכֵן לֹא בֵרַךְ אוֹתָם אֲבִיהֶם, מִשּׁוּם שֶׁהֶעֱלָה אוֹתָם לְמֹשֶׁה. רַבִּי חִיָּיא אָמַר, מֵהַפְּסוּקִים הַלָּלוּ (ומשום כך) (משמע) שֶׁלֹּא נֶאֱחָז זֶה בָּזֶה, וְהִצְטָרֵךְ כָּךְ. וְלָכֵן יֵשׁ בּוֹ הַכֹּל, וְאֵין לְךְ דּוֹר בָּעוֹלָם שֶׁלֹּא יוֹרֵד דִּין שֶׁלָּהֶם לְקַטְרֵג בָּעוֹלָם, וּמִתְרַבִּים הַמְחַזְּרִים עַל הַפְּתָחִים שֶׁל בְּנֵי אָדָם. הִנֵּה לְךְ הַכֹּל (זה כנגד זה).</p>"],[9522011480,"<p>יְהוּדָה אַתָּה יוֹדוּךְ אַחֶיךְ יָדְךְ בְּעֹרֶף אֹיְבֶיךְ וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (תהלים קד) עָשָׂה יָרֵחַ לְמוֹעֲדִים וְגוֹ'. עָשָׂה יָרֵחַ, כְּדֵי לְקַדֵּשׁ בּוֹ רָאשֵׁי חֳדָשִׁים וְרָאשֵׁי שָׁנִים. וּלְעוֹלָמִים הַלְּבָנָה מְאִירָה רַק מִן הַשֶּׁמֶשׁ, וּכְשֶׁשּׁוֹלֶטֶת הַשֶּׁמֶשׁ - לֹא שׁוֹלֶטֶת הַלְּבָנָה, וּכְשֶׁמִּתְכַּנֶּסֶת הַשֶּׁמֶשׁ, אָז שׁוֹלֶטֶת הַלְּבָנָה, וְאֵין חֶשְׁבּוֹן לַלְּבָנָה אֶלָּא רַק כְּשֶׁמִּתְכַּנֶּסֶת הַשֶּׁמֶשׁ.</p>\n<p>וּשְׁנֵיהֶם עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָאִיר, זֶהוּ שֶׁכָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם לְהָאִיר עַל הָאָרֶץ וְגוֹ'. וְהָיוּ לְאֹתֹת - אֵלּוּ שַׁבָּתוֹת, שֶׁכָּתוּב (שמות לא) כִּי אוֹת הִיא. וּלְמוֹעֲדִים - אֵלּוּ יָמִים טוֹבִים. וּלְיָמִים - אֵלּוּ רָאשֵׁי חֳדָשִׁים. וּלְשָׁנִים - אֵלּוּ רָאשֵׁי שָׁנִים. שֶׁיִּהְיוּ אֻמּוֹת הָעוֹלָם עוֹשִׂים חֶשְׁבּוֹן לַשֶּׁמֶשׁ, וְיִשְׂרָאֵל לַלְּבָנָה.</p>\n<p>וְזְהִ הוֹלֵךְ כְּמוֹ שֶׁאָמַר רַבִּי אֶלְעָזָר, כָּתוּב (ישעיה ט) הִרְבִּיתָ הַגּוֹי לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה. הִרְבִּיתָ הַגּוֹי - אֵלּוּ יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם (דברים ד) כִּי מִי גוֹי גָּדוֹל, וְכָתוּב גּוֹי אֶחָד בָּאָרֶץ. לוֹ - בִּשְׁבִילוֹ. הִגְדַּלְתָּ הַשִּׂמְחָה (ממש) - זוֹ הַלְּבָנָה שֶׁמִּתְגַּדֶּלֶת בָּאוֹר בִּשְׁבִיל יִשְׂרָאֵל. אֻמּוֹת הָעוֹלָם לַשֶּׁמֶשׁ, וְיִשְׂרָאֵל לַלְּבָנָה, אֵיזֶה מֵהֶם עָדִיף? וַדַּאי הַלְּבָנָה לְמַעְלָה, וְהַשֶּׁמֶשׁ שֶׁל אֻמּוֹת הָעוֹלָם תַּחַת הַלְּבָנָה הוּא, וְאוֹתוֹ הַשֶּׁמֶשׁ מִזּוֹ (הצד) הַלְּבָנָה מֵאִיר. רְאֵה מַה בֵּינָם לְבֵין יִשְׂרָאֵל. יִשְׂרָאֵל אֲחוּזִים בַּלְּבָנָה, וְהִשְׁתַּלְשְׁלוּ בַּשֶּׁמֶשׁ הָעֶלְיוֹנָה, וְנֶאֶחְזוּ בְּמָקוֹם (בו) (שמאיר לשמש) שֶׁמְּאִירָה מֵהַשֶּׁמֶשׁ הָעֶלְיוֹן וְנִדְבָּקִים בּוֹ, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522011481,"<p>יְהוּדָה אַתָּה וְגוֹ'. רַבִּי שִׁמְעוֹן אָמַר, מַלְכוּת הִתְקַיְּמָה לִיהוּדָה, וְהַיְנוּ מַה שֶּׁאָמַרְנוּ, מַהוּ שֶּׁכָּתוּב (בראשית כט) הַפַּעַם אוֹדֶה אֶת ה', מִשּׁוּם שֶׁהוּא רְבִיעִי אוֹדֶה אֶת ה', מִשּׁוּם שֶׁהוּא רֶגֶל רְבִיעִי לַכִּסֵּא. יה\"ו זֶה רֹשֶׁם שֶׁל הַשֵּׁם הָעֶלְיוֹן, וּבַמֶּה נִשְׁלָם? בְּהֵ\"א (בדל\"ת), וְהַיְנוּ הֵ\"א אַחֲרוֹנָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ, הַשֵּׁם הַקָּדוֹשׁ נִשְׁלָם בְּאוֹתִיּוֹתָיו, וְקֶשֶׁר שֶׁאוֹחֵז אוֹתָן, עַל כָּךְ יוֹדוּךְ אַחֶיךְ, שֶׁהַמַּלְכוּת לְךְ רְאוּיָה לְהִתְקַיֵּם וַדַּאי. (הושע יד) וִיהוּדָה עֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן. מִי הַקְּדוֹשִׁים? אֵלּוּ קְדוֹשִׁים עֶלְיוֹנִים, שֶׁכֻּלָּם מוֹדִים לוֹ וְשָׂמוּ אוֹתוֹ נֶאֱמָן, לָכֵן הוּא רִאשׁוֹן בַּכֹּל, הוּא מֶלֶךְ עַל כֻּלָּם.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים מה) כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה. כָּל כְּבוּדָּה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. כְּבוּדָּה - מִשּׁוּם שֶׁהוּא כָּבוֹד, זֶה עַל זֶה. זֶה זָכָר וְזוֹ נְקֵבָה (זו נקבה), וְנִקְרֵאת כְּבוּדָּה. בַּת מֶלֶךְ - הַיְנוּ בַּת שֶׁבַע, בַּת קוֹל שֶׁהוּא קוֹל גָּדוֹל, וְזֶהוּ מֶלֶךְ הָעֶלְיוֹן. פְּנִימָה - מִשּׁוּם שֶׁיֵּשׁ מֶלֶךְ שֶׁאֵינוֹ לִפְנִים כְּמוֹתוֹ, וְזוֹ כְּבוּדָּה בַת מֶלֶךְ.</p>\n<p>מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ, מִשּׁוּם שֶׁהִתְלַבְּשָׁה וְנֶאֶחְזֶה בִּגְבוּרָה עֶלְיוֹנָה, וְגַם זֶה נִקְרָא מֶלֶךְ, וּבִשְׁבִילָהּ עוֹמֶדֶת הָאָרֶץ, מָתַי? בְּשָׁעָה שֶׁנֶּאֱחֶזֶת בְּמִשְׁפָּט, כְּמוֹ שֶׁנֶּאֱמַר (משלי כט) מֶלֶךְ בְּמִשְׁפָּט יַעֲמִיד אָרֶץ. וְלָזוֹ קוֹרְאִים מַלְכוּת הַשָּׁמַיִם, וִיהוּדָה נֶאֱחַז בָּהּ, וְיָרַשׁ הַמַּלְכוּת שֶׁבָּאָרֶץ.</p>\n<p>רַבִּי (אבא) יְהוּדָה וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יִצְחָק, נִפְתַּח בְּדִבְרֵי תוֹרָה וְנֵלֵךְ. פָּתַח רַבִּי יִצְחָק וְאָמַר, (בראשית ג) וַיְגָרֶשׁ אֶת הָאָדָם וַיַּשְׁכֵּן מִקֶּדֶם לְגַן עֵדֶן וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ הַחֲבֵרִים, אֲבָל וַיְגָרֶשׁ, כְּמוֹ בֶּן אָדָם שֶׁמְּגָרֵשׁ אֶת אִשְׁתּוֹ, אֶת הָאָדָם דַּוְקָא.</p>\n<p>בֹּא רְאֵה סוֹד הַדָּבָר, אָדָם נִתְפַּס בְּמַה שֶּׁחָטָא, וְגָרַם מָוֶת לוֹ וּלְכָל הָעוֹלָם, וְגָרַם לְאוֹתוֹ עֵץ שֶׁחָטָא בּוֹ גֵּרוּשִׁים, לְהִגָּרֵשׁ בּוֹ וּלְהִתְגָּרֵשׁ בְּבָנָיו לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב וַיְגָרֶשׁ אֶת הָאָדָם, אֶת דַּוְקָא, כַּכָּתוּב (ישעיה ו) וָאֶרְאֶה אֶת ה'. אַף כָּאן אֶת הָאָדָם.</p>\n<p>וַיַּשְׁכֵּן מִקֶּדֶם לְגַן עֵדֶן וְגוֹ' - זֶה לְמַטָּה. כְּמוֹ שֶׁכְּרוּבִים לְמַעְלָה, יֵשׁ כְּרוּבִים לְמַטָּה, וְהִשְׁרָה הָעֵץ הַזֶּה עֲלֵיהֶם. וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת אֵלּוּ דֻּגְמַת שַׁלְהֶבֶת שֶׁל אֵשׁ מֵאותָהּ הַחֶרֶב שֶׁמִּתְלַהֶטֶת. הַמִּתְהַפֶּכֶת - זוֹ הַחֶרֶב הַזּוֹ, שֶׁיּוֹנֶקֶת בִּשְׁנֵי צְדָדִים, וּמִתְהַפֶּכֶת מִצַּד זֶה לְצַד אַחֵר. דָּבָר אַחֵר, הַמִּתְהַפֶּכֶת - זוֹ לַהַט אוֹתָן צוּרוֹת הַשַּׁלְהֶבֶת (של המלכות) שֶׁאָמַרְנוּ, שֶׁמִּתְהַפְּכוֹת לִפְעָמִים גְּבָרִים וְלִפְעָמִים נָשִׁים, וּמִתְהַפְּכוֹת מִמְּקוֹמָם לַכֹּל, וְכָל זֶה כְּדֵי לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים. אֵיזוֹ דֶרֶךְ? כְּמוֹ שֶׁנֶּאֱמַר (שם מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, יָפֶה, וְכָךְ זֶה וַדַּאי שֶׁגָּרַם אָדָם לְאוֹתוֹ עֵץ שֶׁחָטָא בּוֹ לְהִתְגָּרֵשׁ, וְגַם לִשְׁאָר בְּנֵי הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (שם נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם, אֲבָל יָפֶה אָמַרְתָּ, שֶׁהֲרֵי מִמְּקוֹמוֹ מַשְׁמָע, שֶׁכָּתוּב וַיְגָרֶשׁ אֶת הָאָדָם, מִשּׁוּם שֶׁזּוֹהִי שְׁלֵמוּת הָאָדָם.</p>\n<p>וּמֵאוֹתוֹ יוֹם נִפְגְּמָה הַלְּבָנָה, עַד שֶׁבָּא נֹחַ וְנִכְנַס בִּתְשׁוּבָה (לתבה). בָּאוּ הָרְשָׁעִים וְנִפְגַּם. עַד שֶׁבָּא אַבְרָהָם (ועמדו) וְעָמַד בַּשְּׁלֵמוּת שֶׁל יַעֲקֹב וּבָנָיו. וּבָא יְהוּדָה וְאָחַז בָּהּ, וְהִתְחַזֵּק בַּמַּלְכוּת, וְיָרַשׁ אוֹתָהּ יְרֻשַּׁת עוֹלָמִים הוּא וְכָל בָּנָיו אַחֲרָיו. זֶהוּ שֶׁכָּתוּב יְהוּדָה אַתָּה יוֹדוּךְ אַחֶיךְ. (משום שהמלכות שלו עליהם, כמו שנאמר (דברי הימים א ה) כי יהודה גבר באחיו, יודוך אחיך) וַדַּאי בְּשָׁעָה שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַיָּם, שֶׁכֻּלָּם הוֹדוּ לוֹ וְיָרְדוּ אַחֲרָיו לַיָּם.</p>\n<p>יָדְךָ בְּעֹרֶף אֹיְבֶיךְ, כְּמוֹ שֶׁנֶּאֱמַר (שופטים א) יְהוּדָה יַעֲלֶה (בתחלה). יִשְׁתַּחֲווּ לְךְ בְּנֵי אָבִיךְ, כְּלָל שֶׁל כָּל אוֹתָם שְׁאָר הַשְּׁבָטִים, מִשּׁוּם זֶה בְּנֵי אָבִיךְ וְלֹא בְּנֵי אִמֶּךְ. בְּנֵי אָבִיךְ - הֲרֵי כָּל שְׁאָר הַשְּׁבָטִים. שֶׁאַף עַל גַּב (שהם נחלקו) שֶׁנֶּחְלְקוּ לִשְׁתֵּי מַלְכֻיּוֹת, כְּשֶׁהָיוּ עוֹלִים לִירוּשָׁלַיִם הָיוּ כוֹרְעִים וּמִשְׁתַּחֲוִים לַמֶּלֶךְ שֶׁבִּירוּשָׁלַיִם, מִשּׁוּם שֶׁמַּלְכוּת יְרוּשָׁלַיִם מִמַּלְכוּת הַקְּדוֹשָׁה. (שולטת) מִמֶּנּוּ הָיְתָה</p>\n<p>יִשְׁתַּחֲווּ לְךְ, וְלֹא כָתוּב וְיִשְׁתַּחֲווּ, שֶׁאִם כָּתוּב וְיִשְׁתַּחֲווּ - לְהוֹסִיף אֶת שְׁאָר הָעַמִּים. לֹא כָתוּב וְיִשְׁתַּחֲווּ אֶלָּא בִּזְמַן שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב (ישעיה מט) שָׂרִים וְיִשְׁתַּחֲווּ. עַכְשָׁו שֶׁאָמַר יִשְׁתַּחֲווּ, לְהַרְאוֹת שֶׁכָּל יִשְׂרָאֵל לְבַדָּם, כֻּלָּם יַעַבְדוּ לְרֹאשׁ הַגּוֹלָה, לָרֹאשׁ שֶׁל בָּבֶל, וְלֹא שְׁאָר הָעַמִּים.</p>\n<p>גּוּר אַרְיֵה יְהוּדָה, בַּתְּחִלָּה גּוּר וְאַחַר כָּךְ אַרְיֵה. וְסוֹד הַדָּבָר - בַּתְּחִלָּה נַעַר וְאַחַר כָּךְ אִישׁ, (שמות טו) ה' אִישׁ מִלְחָמָה. מִטֶּרֶף בְּנִי עָלִיתָ, מַה זֶּה מִטֶּרֶף? לְהַכְלִיל אֶת מַלְאַךְ הַמָּוֶת, שֶׁהוּא עוֹמֵד עַל טֶרֶף לְכַלּוֹת אֶת בְּנֵי הָעוֹלָם וְלֹא מַצִּיל, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ה) וְטָרַף וְאֵין מַצִּיל. (ומהו) וּמֵאוֹתוֹ טֶרֶף מִסְתַּלֶּקֶת הַשְּׁכִינָה.</p>\n<p>כָּרַע - בְּגָלוּת בָּבֶל. רָבַץ - בְּגָלוּת אֱדוֹם. כְּאַרְיֵה - שֶׁהוּא חָזָק. וּכְלָבִיא - שֶׁהוּא יוֹתֵר חָזָק, כָּךְ יִשְׂרָאֵל הֵם חֲזָקִים, שֶׁבְּנֵי הָעוֹלָם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת מְפַתִּים וְדוֹחֲקִים אוֹתָם, וְהֵם עוֹמְדִים בְּדָתָם וּבְמִנְהֲגֵיהֶם כְּאַרְיֵה וּכְלָבִיא.</p>\n<p>כָּךָ שְׁכִינָה, שֶׁאַף עַל גַּב שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל, הִיא חֲזָקָה כְּאַרְיֵה וּכְלָבִיא בַּנְּפִילָה הַזּוֹ. מָה אַרְיֵה וְלָבִיא לֹא נוֹפְלִים אֶלָּא כְּדֵי לִטְרֹף טֶרֶף וְלִשְׁלֹט, שֶׁהֲרֵי מֵרָחוֹק מֵרִיחַ אֶת טַרְפּוֹ, וּמִשָּׁעָה שֶׁמֵּרִיחַ נוֹפֵל, וְלֹא קָם עַד שֶׁקּוֹפֵץ עַל טַרְפּוֹ וְאוֹכְלוֹ, כָּךְ שְׁכִינָה לֹא נוֹפֶלֶת אֶלָּא כְּאַרְיֵה וּכְלָבִיא, כְּדֵי לִנְקֹם מֵעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְלִקְפֹּץ עֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סג) צֹעֶה בְּרֹב כֹּחוֹ.</p>\n<p>מִי יְקִימֶנּוּ - הוּא לֹא יָקוּם לִנְקֹם מֵהֶם נְקָמָה קְטַנָּה, אֶלָּא מִי יְקִימֶנּוּ. מִ\"י, כְּמוֹ שֶׁנֶּאֱמַר (איכה ב) מִי יִרְפָּא לָךְ, וְהוּא עוֹלָם הָעֶלְיוֹן שֶׁבּוֹ שִׁלְטוֹן לְחַזֵּק לַכֹּל, וְכָתוּב (איוב לח) מִבֶּטֶן מִי יָצָא הַקָּרַח, וּבֵאֲרוּהָ.</p>\n<p>לֹא יָסוּר שֵׁבֶט מִיהוּדָה וְגוֹ', בֵּאֲרוּ הַחֲבֵרִים, אֲבָל עַד כִּי יָבֹא שִׁילֹ\"ה, בְּהֵ\"א, מִשּׁוּם שֶׁבַּשְּׁאָר בְּו', לְהַרְאוֹת כָּאן אֶת סוֹד (כאן) הַשֵּׁם הַקָּדוֹשׁ י\"ה. בְּמָקוֹם אַחֵר שִׁילוֹ בְּלִי הֵ\"א, וּבְמָקוֹם אַחֵר שִׁלֹה בְּלִי יוֹ\"ד, וְכָאן שִׁילֹ\"ה בְּיוֹ\"ד הֵ\"א, סוֹד הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, שֶׁשְּׁכִינָה תָּקוּם בַּשֵּׁם (זה) שֶׁל י\"ה, וְהוּא סוֹד שֶׁל י' (מ\"י), כְּפִי שֶׁאָמַרְנוּ.</p>"],[9522011482,"<p>אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂרֵקָה בְּנִי אֲתֹנוֹ וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (תהלים קכא) ה' יִשְׁמָרְךְ מִכָּל רָע יִשְׁמֹר אֶת נַפְשֶׁךְ. כֵּיוָן שֶׁאָמַר ה' יִשְׁמָרְךְ מִכָּל רָע, לְשֵׁם מָה יִשְׁמֹר אֶת נַפְשֶׁךְ? אֶלָּא ה' יִשְׁמָרְךְ מִכָּל רָע - בָּעוֹלָם הַזֶּה, יִשְׁמֹר אֶת נַפְשֶׁךְ - בְּאוֹתוֹ עוֹלָם.</p>\n<p>שְׁמִירָה שֶׁל הָעוֹלָם הַזֶּה הוּא, לִהְיוֹת הָאָדָם שָׁמוּר מִכַּמָּה מִינִים רָעִים מְקַטְרְגִים שֶׁהוֹלְכִים לְקַטְרֵג בְּנֵי הָאָדָם בָּעוֹלָם וְלִדְבֹּק בָּהֶם. בְּאוֹתוֹ הָעוֹלָם מַה זֶּה? כְּמוֹ שֶׁאָמַרְנוּ, כְּשֶׁיּוֹצֵא אָדָם מִן הָעוֹלָם הַזֶּה, אִם הוּא זוֹכֶה - נִשְׁמָתוֹ עוֹלָה וּמִתְעַטֶּרֶת בִּמְקוֹמָהּ, וְאִם לֹא - כַּמָּה קְבוּצוֹת שֶׁל מְחַבְּלִים מְזֻמָּנִים לִמְשֹׁךְ אוֹתוֹ לַגֵּיהִנֹּם וְלִמְסֹר אוֹתוֹ בִּידֵי דוּמָה, שֶׁנִּמְסָר לַמְמֻנֶּה עַל הַגֵּיהִנֹּם, וּשְׁלֹשׁ עֶשְׂרֵה אֶלֶף רִבּוֹא מְמֻנִּים עִמּוֹ, וְכֻלָּם מְזֻמָּנִים עַל נַפְשׁוֹת הָרְשָׁעִים.</p>\n<p>בֹּא רְאֵה, שִׁבְעָה מְדוֹרִים יֵשׁ בַּגֵּיהִנֹּם, וְשִׁבְעָה פְתָחִים. וְנִשְׁמַת הָרָשָׁע נִכְנֶסֶת, וְכַמָּה מַלְאֲכֵי חַבָּלָה, רוּחוֹת, שׁוֹמְרֵי הַשְּׁעָרִים, וַעֲלֵיהֶם מְמֻנֶּה אֶחָד בְּכָל שַׁעַר וְשַׁעַר, וְנִשְׁמוֹת הָרְשָׁעִים נִמְסָרוֹת לְאוֹתָם מְמֻנִּים עַל יְדֵי דוּמָה. כֵּיוָן שֶׁנִּמְסָרוֹת בִּידֵיהֶם, סוֹתְמִים שְׁעָרִים שֶׁל אֵשׁ לוֹהֵט.</p>\n<p>שֶׁהֲרֵי יֵשׁ שְׁעָרִים אַחַר שְׁעָרִים. כָּל הַשְּׁעָרִים פְּתוּחִים וּסְתוּמִים, הַחִיצוֹנִיִּים פְּתוּחִים וְהַפְּנִימִיִּים סְתוּמִים, וּבְכָל שַׁבָּת וְשַׁבָּת כֻּלָּם פְּתוּחִים, וְיוֹצְאִים הָרְשָׁעִים עַד לְאוֹתָם הַשְּׁעָרִים הַחִיצוֹנִיִּים, וּפוֹגְשִׁים נְשָׁמוֹת אֲחֵרוֹת שֶׁמִּתְעַכְּבוֹת בַּפְּתָחִים הַחִיצוֹנִיִּים. וּכְשֶׁיּוֹצֵאת שַׁבָּת, הַכָּרוֹז עוֹמֵד בְּכָל פֶּתַח וּפֶתַח וְאוֹמֵר: (תהלים ט) יָשׁוּבוּ רְשָׁעִים לִשְׁאוֹלָה וְגוֹ'. בֹּא רְאֵה, נִשְׁמוֹת הַצַּדִּיקִים הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָן שֶׁלֹּא יִמָּסְרוּ לִידֵי דוּמָה, שֶׁהוּא הַמְמֻנֶּה. זֶהוּ שֶׁכָּתוּב יִשְׁמֹר צֵאתְךְ וּבוֹאֶךְ, וְכָתוּב יִשְׁמֹר אֶת נַפְשֶׁךְ.</p>\n<p>אֹסְרִי לַגֶּפֶן עִירֹה. מַהִי הַגֶּפֶן? זוֹ כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פ) גֶּפֶן מִמִּצְרַיִם תַּסִּיעַ, וְכָתוּב (שם קכח) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה. אֶשְׁתְּךְ כַּגֶּפֶן הַקְּדוֹשָׁה הַזּוֹ. אָמַר רַבִּי יוֹסֵי, זוֹ הַגֶּפֶן שֶׁמְּבָרְכִים בָּהּ בּוֹרֵא פְּרִי הַגֶּפֶן. בּוֹרֵא - הַיְנוּ שֶׁכָּתוּב (בראשית א) עֵץ עֹשֶׂה פְּרִי. פְּרִי הַגֶּפֶן - זֶה עֵץ פְּרִי. עֹשֶׂה פְּרִי - זָכָר. עֵץ פְּרִי - זוֹ נְקֵבָה. מִשּׁוּם כָּךְ בּוֹרֵא פְּרִי הַגֶּפֶן, זֶה זָכָר וּנְקֵבָה כְּאֶחָד. (נשמות הצדיקים הן פרי הגפן, כמו שאמר בורא פרי הגפן,)</p>\n<p>אֹסְרִי לַגֶּפֶן עִירֹה - זֶה מֶלֶךְ הַמָּשִׁיחַ שֶׁעָתִיד לִשְׁלֹט עַל כָּל חֵילוֹת הָעַמִּים, הַחֲיָלוֹת הַמְמֻנִּים עַל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְהֵם חֹזֶק שֶׁלָּהֶם לְהִתְחַזֵּק, וְעָתִיד מֶלֶךְ הַמָּשִׁיחַ לְהִתְגַּבֵּר עֲלֵיהֶם.</p>\n<p>מִשּׁוּם שֶׁגֶּפֶן זוֹ שׁוֹלֶטֶת עַל כָּל אוֹתָם הַכְּתָרִים הַתַּחְתּוֹנִים שֶׁשּׁוֹלְטִים בָּהֶם עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, זוֹ מְנַצַּחַת לְמַעְלָה. יִשְׂרָאֵל, שֶׁהֵם שּרֵקָה, יְכַלּוּ וִינַצְּחוּ הַחֲיָלוֹת הָאֲחֵרִים לְמַטָּה, וְעַל כֻּלָּם יִתְגַּבֵּר מֶלֶךְ הַמָּשִׁיחַ. זֶהוּ שֶׁכָּתוּב (זכריה ט) עָנִי וְרֹכֵב עַל חֲמוֹר וְעַל עַיִר. עַיִר וַחֲמוֹר הֵם שְׁנֵי כְתָרִים שֶׁשּׁוֹלְטִים בָּהֶם עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְהֵם מִצַּד הַשְּׂמֹאל, צַד הַחֹל.</p>\n<p>וּמַה שֶּׁאָמַר עָנִי - וְכִי מֶלֶךְ הַמָּשִׁיחַ נִקְרָא עָנִי? אֶלָּא כָּךְ אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם שֶׁאֵין לוֹ מִשֶּׁלּוֹ, וְקוֹרְאִים לוֹ מֶלֶךְ הַמָּשִׁיחַ. זוֹהִי הַלְּבָנָה הַקְּדוֹשָׁה לְמַעְלָה שֶׁאֵין לָהּ אוֹר אֶלָּא מִן הַשֶּׁמֶשׁ.</p>\n<p>מֶלֶךָ הַמָּשִׁיחַ הַזֶּה יִשְׁלֹט בְּשִׁלְטוֹנוֹ, יִתְיַחֵד בִּמְקוֹמוֹ, וְאָז (שם) הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ, סְתָם. אִם לְמַטָּה - עָנִי הוּא, שֶׁהֲרֵי בְּצַד הַלְּבָנָה הוּא. אִם לְמַעְלָה - עָנִי, אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, לֶחֶם עֹנִי. וְעִם כָּל זֶה, רֹכֵב עַל חֲמוֹר וְעַל עַיִר, חָזְקָם שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לִכְפּוֹתָם תַּחְתָּיו, וְיִתְחַזֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא בִּמְקוֹמוֹ.</p>\n<p>כִּבֵּס בַּיַּיִן לְבוּשׁוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה, וְכָתוּב פּוּרָה דָּרַכְתִּי לְבַדִּי וְגוֹ'. כִּבֵּס בַּיַּיִן - זֶה הַצַּד שֶׁל גְּבוּרָה, דִּין הַקָּשֶׁה, לִהְיוֹת עַל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבְדַם עֲנָבִים סוּתֹה - זֶה הָעֵץ לְמַטָּה, בֵּית דִּין שֶׁנִּקְרָא עֲנָבִים, וְהַיַּיִן נִמְסָר (נשמר) בְּדַם עֲנָבִים כְּדֵי לְהִתְלַבֵּשׁ בִּשְׁנֵיהֶם, לִשְׁבֹּר תַּחְתָּיו כָּל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וּמַלְכֵי הָעוֹלָם.</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, אֹסְרִי לַגֶּפֶן עִירֹה, וְכָתוּב (בראשית מ) וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם וְהִוא כְפֹרַחַת עָלְתָה נִצָּהּ. בֹּא רְאֵה כַּמָּה אֲטוּמִים הֵם בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בִּכְבוֹד רִבּוֹנָם וְלֹא מִסְתַּכְּלִים בְּדִבְרֵי הַתּוֹרָה וְלֹא יוֹדְעִים דַּרְכֵיהֶם בַּמֶּה יִתָּפְסוּ, שֶׁכָּתוּב (משלי ד) דֶּרֶךְ רְשָׁעִים כָּאֲפֵלָה לֹא יָדְעוּ בַּמֶּה יִכָּשֵׁלוּ.</p>\n<p>בִּזְמַן קַדְמוֹן הָיְתָה נְבוּאָה שׁוֹרָה עַל בְּנֵי אָדָם, וְהָיוּ יוֹדְעִים וּמִתְבּוֹנְנִים לָדַעַת בַּכָּבוֹד הָעֶלְיוֹן. כֵּיוָן שֶׁפָּסְקָה מֵהֶם נְבוּאָה, הָיוּ מִשְׁתַּמְּשִׁים בְּבַת קוֹל. עַכְשָׁו פָּסְקָה נְבוּאָה וּפָסְקָה בַּת קוֹל, וְלֹא מִשְׁתַּמְּשִׁים בְּנֵי אָדָם אֶלָּא בַּחֲלוֹם.</p>\n<p>וַחֲלוֹם הוּא דַּרְגָּה תַחְתּוֹנָה הִיא חִיצוֹנָה, שֶׁהֲרֵי שָׁנִינוּ, חֲלוֹם הוּא אֶחָד מִשִּׁשִּׁים שֶׁל נְבוּאָה, מָה הַטַּעַם? מִשּׁוּם שֶׁבָּא מִדַּרְגָּה שִׁשִּׁית לְמַטָּה, וַהֲרֵי נִתְבָּאֵר. בֹּא רְאֵה, הַחֲלוֹם נִרְאָה לְכֻלָּם, מִשּׁוּם שֶׁחֲלוֹם בָּא מִצַּד הַשְּׂמֹאל, וְיוֹרֵד בְּכַמָּה דְרָגוֹת, וְנִרְאֶה חֲלוֹם, אֲפִלּוּ לְחַיָּבִים וַאֲפִלּוּ לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת.</p>\n<p>מִשּׁוּם שֶׁלִּפְעָמִים לוֹקְחִים חֲלוֹם וְשׁוֹמְעִים אוֹתָם הַמִּינִים הָרָעִים, וּמוֹדִיעִים לִבְנֵי אָדָם. מֵהֶם שֶׁצּוֹחֲקִים (בהם) עַל בְּנֵי אָדָם וּמוֹדִיעִים לָהֶם דְּבָרִים כּוֹזְבִים, וְלִפְעָמִים שׁוֹמְעִים דִּבְרֵי אֱמֶת, וְלִפְעָמִים שֶׁהֵם שְׁלוּחִים לָרְשָׁעִים וּמוֹדִיעִים לָהֶם דְּבָרִים עֶלְיוֹנִים.</p>\n<p>מַה כָּתוּב בָּרָשָׁע הַזֶּה? רָאָה חֲלוֹם אֱמֶת, שֶׁכָּתוּב וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם. מַהִי גֶפֶן? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב (תהלים פ) הַבֵּט מִשָּׁמַיִם וּרְאֵה וּפְקֹד גֶּפֶן זֹאת. מִשָּׁמַיִם, שֶׁהֲרֵי מִמָּקוֹם זֶה נִזְרְקָה, כְּמוֹ שֶׁנֶּאֱמַר (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. וּפְקֹד גֶּפֶן זֹאת, גֶּפֶן שֶׁהִיא זֹאת, וַדַּאי.</p>\n<p>שְׁלשָה שָׂרִיגִם - כְּמוֹ שֶׁנֶּאֱמַר (בראשית כט) שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ. וְהִיא כְפֹרַחַת - שֶׁכָּתוּב (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה, שֶׁהֵאִירָה הַלְּבָנָה. עָלְתָה נִצָּהּ - זוֹ יְרוּשָׁלַיִם שֶׁל מַטָּה. דָּבָר אַחֵר עָלְתָה נִצָּהּ - לְמַעְלָה, אוֹתָהּ דַּרְגָּה שֶׁעוֹמֶדֶת עָלֶיהָ וּמֵינִיקָה אוֹתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) אֲשֶׁר זַרְעוֹ בוֹ עַל הָאָרֶץ. הִבְשִׁילוּ אַשְׁכְּלֹתֶיהָ עֲנָבִים - לִשְׁמֹר בָּהֶם יַיִן הַמְשֻׁמָּר.</p>\n<p>רְאֵה כַּמָּה רָאָה אוֹתוֹ רָשָׁע. מַה כָּתוּב? (שם מ) וְכוֹס פַּרְעֹה בְּיָדִי וָאֶקַּח אֶת הָעֲנָבִים וָאֶשְׂחַט אֹתָם. כָּאן רָאָה אוֹתָהּ כּוֹס הַתַּרְעֵלָה, יְנִיקַת בֵּית הַדִּין, שֶׁיּוֹצֵאת מֵאוֹתָם עֲנָבִים שֶׁנָּתְנוּ לְפַרְעֹה וְשָׁתָה אוֹתוֹ, כְּמוֹ שֶׁהָיָה בִּשְׁבִיל יִשְׂרָאֵל. כֵּיוָן שֶׁשָּׁמַע אֶת זֶה יוֹסֵף, שָׂמַח וְיָדַע דְּבַר אֱמֶת בַּחֲלוֹם הַזֶּה. לָכֵן פָּתַר לוֹ חֲלוֹם לְטוֹב עַל שֶׁבִּשֵּׂר אֶת יוֹסֵף בָּזֶה.</p>\n<p>בֹּא רְאֵה, אֹסְרִי לַגֶּפֶן עִירֹה - שֶׁנִּכְפִּים תַּחַת הַגֶּפֶן הַ את כָּל אוֹתָם חֲיָלוֹת חֲזָקִים שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, כְּמוֹ שֶׁאָמַרְנוּ, בִּשְׁבִיל גֶּפֶן זֹאת נִקְשָׁר וְנִכְפֶּה אוֹתוֹ הַכֹּחַ שֶׁלָּהֶם, וְנִתְבָּאֵר.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, יֵשׁ גֶּפֶן וְיֵשׁ גֶּפֶן. יֵשׁ גֶּפֶן קְדוֹשָׁה עֶלְיוֹנָה, וְיֵשׁ גֶּפֶן שֶׁנִּקְרֵאת (דברים לב) גֶּפֶן סְדוֹם, וְיֵשׁ (ירמיה ב) גֶּפֶן נָכְרִיָּה בַּת אֵל נֵכָר. מִשּׁוּם כָּךְ כָּתוּב גֶּפֶן זֹאת, אוֹתָהּ שֶׁנִּקְרֵאת כֻּלֹּה זֶרַע אֱמֶת. שׂוֹרֵק - אֵלּוּ יִשְׂרָאֵל שֶׁיּוֹצְאִים מֵהַגֶּפֶן הַזּוֹ. כְּשֶׁחָטְאוּ יִשְׂרָאֵל וְעָזְבוּ אֶת הַגֶּפֶן הַזּוֹ, מַה כָּתוּב? כִּי מִגֶּפֶן סְדוֹם גַּפְנָם וְגוֹ', וְלָכֵן יֵשׁ גֶּפֶן וְיֵשׁ גֶּפֶן.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יִצְחָק, נֵלֵךְ בַּשָּׂדֶה הַזֶּה, שֶׁהוּא דֶּרֶךְ יוֹתֵר יְשָׁרָה. הָלְכוּ. עַד שֶׁהָלְכוּ, אָמַר רַבִּי יְהוּדָה, כָּתוּב (משלי לא) לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג כִּי כָל בֵּיתָהּ לָבֻשׁ שָׁנִים. פָּסוּק זֶה רַבִּי חִזְקִיָּה חֲבֵרֵנוּ בֵּאֵר בּוֹ, שֶׁאָמַר, דִּין הָרְשָׁעִים בַּגֵּיהִנֹּם שְׁנֵים עָשָׂר חֹדֶשׁ, חֲצִי מֵהֶם בַּחַמָּה וַחֲצִי מֵהֶם בַּשֶּׁלֶג.</p>\n<p>בְּשָׁעָה שֶׁנִּכְנָסִים לָאֵשׁ, הֵם אוֹמְרִים: זֶהוּ וַדַּאי גֵּיהִנֹּם. נִכְנָסִים לַשֶּׁלֶג, אוֹמְרִים: זוֹ חֲרִיפוּת הַחֹרֶף (הקר) שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַתְחִילִים וְאוֹמְרִים: וָה, וְאַחַר כָּךְ אוֹמְרִים: וַי. וְדָוִד אָמַר, (תהלים מ) וַיַּעֲלֵנִי מִבּוֹר שָׁאוֹן מִטִּיט הַיָּוֵן וַיָּקֶם וְגוֹ'. מִמָּקוֹם שֶׁאוֹמְרִים וָה, וְאַחַר כָּךְ וַי.</p>\n<p>וְהֵיכָן נִתְקָנוֹת נַפְשָׁם? בַּשֶּׁלֶג, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סח) בְּפָרֵשׂ שַׁדַּי מְלָכִים בָּהּ תַּשְׁלֵג בְּצַלְמוֹן. יָכוֹל אַף יִשְׂרָאֵל כֵּן? תַּלְמוּד לוֹמַר, לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל בֵּיתָהּ לָבֻשׁ שָׁנִים. אַל תִּקְרֵי שָׁנִים אֶלָּא שְׁנַיִם, כְּמוֹ מִילָה וּפְרִיעָה, צִיצִית וּתְפִלִּין, מְזוּזָה וְנֵר חֲנֻכָּה וְכוּ'.</p>\n<p>בֹּא רְאֵה, לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא כָּל בֵּיתָהּ לָבֻשׁ שָׁנִים, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב (ישעיה סג) חֲמוּץ בְּגָדִים וְגוֹ', לְבוּשׁ שֶׁל הַדִּין הַקָּשֶׁה, לְהִפָּרַע מֵעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִלְבֹּשׁ לְבוּשׁ אָדם וְחֶרֶב אֲדֻמָּה וּלְהִפָּרַע מֵהָאָדם. לְבוּשׁ אָדם, שֶׁכָּתוּב חֲמוּץ בְּגָדִים, וְכָתוּב (שם) מַדּוּעַ אָדם לִלְבוּשֶׁךְ. הַסַּיִף אֲדֻמָּה, שֶׁכָּתוּב (שם לד) חֶרֶב לַה' מָלְאָה דָם. וּלְהִפָּרַע מִן הָאָדם, שֶׁכָּתוּב כִּי זֶבַח לַה' בְּבָצְרָה וְגוֹ'. עוֹד כִּי כָל בֵּיתָהּ לָבֻשׁ שָׁנִים - שֶׁהֲרֵי זֶה בָּא מִצַּד שֶׁל הַדִּין הַקָּשֶׁה.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַדַּאי זֶה כָּךְ, אֶלָּא כָּל בֵּיתָהּ לָבֻשׁ שָׁנִים, מָהֵם הַשָּׁנִים? אֵלּוּ שָׁנִים קַדְמוֹנִיּוֹת, מִשּׁוּם שֶׁהִיא נִכְלֶלֶת מִכֻּלָּם וְיוֹנֶקֶת מִכָּל הַצְּדָדִים, כַּכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם.</p>\n<p>עֵד שֶׁהָיוּ הוֹלְכִים, פָּגְשׁוּ בְּאוֹתוֹ תִינוֹק שֶׁהָיָה הוֹלֵךְ לְקַפּוֹטְקִיָּא מֵאַחֲרֵי הַחֲמוֹר, וְזָקֵן אֶחָד רוֹכֵב. אָמַר אוֹתוֹ זָקֵן לְאוֹתוֹ תִינוֹק, בְּנִי, אֱמֹר לִי אֶת פְּסוּקְךְ. אָמַר לוֹ, פְּסוּקִי אֵינוֹ אֶחָד, אֶלָּא רֵד לְמַטָּה אוֹ אֶרְכַּב לְפָנֶיךְ וְאֹמַר לְךְ. אָמַר לוֹ, לֹא רוֹצֶה, אֲנִי זָקֵן וְאַתָּה תִינוֹק, שֶׁאֶשְׁקֹל אֶת עַצְמִי עִמְּךְ. אָמַר לוֹ, אִם כָּךְ, אָז לָמָּה שָׁאַלְתָּ פָּסוּק? אָמַר לוֹ, כְּדֵי שֶׁנֵּלֵךְ בַּדֶּרֶךְ. אָמַר, תִּפַּח רוּחוֹ שֶׁל אוֹתוֹ זָקֵן, שֶׁהוּא רוֹכֵב וְלֹא יוֹדֵעַ דָּבָר, וְאָמַר שֶׁלֹּא יִהְיֶה שָׁקוּל עִמִּי. נִפְרַד מֵאוֹתוֹ זָקֵן וְהָלַךְ לוֹ בַּדֶּרֶךְ.</p>\n<p>כְּשֶׁהִגִּיעוּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק, קָרַב אֲלֵיהֶם. שָׁאֲלוּ אוֹתוֹ וְסָח לָהֶם אֶת הַמַּעֲשֶׂה. אָמַר לוֹ רַבִּי יְהוּדָה, יָפֶה עָשִׂיתָ, לֵךְ עִמָּנוּ וְנֵשֵׁב כָּאן וְנִשְׁמַע דָּבָר מִפִּיךְ. אָמַר לָהֶם, אֲנִי עָיֵף, שֶׁלֹּא אָכַלְתִּי הַיּוֹם הַזֶּה. הוֹצִיאוּ לֶחֶם וְנָתְנוּ לוֹ. הִתְרַחֵשׁ לָהֶם נֵס וּמָצְאוּ מַעְיַן מַיִם דַּקִּיק תַּחַת עֵץ. שָׁתוּ מִמֶּנּוּ, וְהֵם שָׁתוּ וְיָשְׁבוּ.</p>\n<p>פָּתַח אוֹתוֹ תִינוֹק וְאָמַר, (תהלים לז) לְדָוִד אַל תִּתְחַר בַּמְּרֵעִים אַל תְּקַנֵּא בְּעֹשֵׂי עַוְלָה. לְדָוִד, אִם שִׁירָה - לֹא אָמַר, אִם תְּפִלָּה - לֹא אָמַר. אֶלָּא בְּכָל מָקוֹם לְדָוִד סְתָם, רוּחַ הַקֹּדֶשׁ אָמַר אֶת זֶה.</p>"],[9522011483,"<p>אַל תִּתְחַר בַּמְּרֵעִים, מַה זֶּה אַל תִּתְחַר בַּמְּרֵעִים? הָיָה צָרִיךְ (לכתב) אַל תִּתְחַבֵּר! אֶלָּא אַל תַּעֲשֶׂה תַחֲרוּת בַּמְּרֵעִים, כִּי לֹא יָדַעְתָּ יְסוֹד עַצְמְךְ וְלֹא תוּכַל לוֹ, אוּלַי הוּא עֵץ שֶׁלֹּא נֶעֱקָר לְעוֹלָמִים וְתִדָּחֶה מִלְּפָנָיו.</p>\n<p>וְאַל תְּקַנֵּא בְּעֹשֵׂי עַוְלָה, שֶׁלֹּא תַשְׁגִּיחַ בְּמַעֲשֵׂיהֶם וְלֹא תָבא לְקַנֵּא בָהֶם, שֶׁכָּל מִי שֶׁרוֹאֶה אֶת מַעֲשֵׂיהֶם וְלֹא מְקַנֵּא לַקָּדוֹשׁ- בָּרוּךְ-הוּא, עוֹבֵר עַל שְׁלֹשָׁה לָאוִים, שֶׁכָּתוּב (שמות כ) לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי. לֹא תַעֲשֶׂה לְךְ פֶסֶל וְכָל תְּמוּנָה. לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם כִּי אָנֹכִי ה' אֱלֹהֶיךְ אֵל קַנָּא.</p>"],[9522011484,"<p>לָכֵן צָרִיךְ הָאָדָם לְהִפָּרֵד מֵהֶם וְלִסְטוֹת דַּרְכּוֹ מֵהֶם, לָכֵן נִפְרַדְתִּי וְסָטִיתִי אֶת דַּרְכִּי. מִכָּאן וָהָלְאָה שֶׁמָּצָאתִי אֶתְכֶם, אֲנִי אוֹמֵר פְּסוּקִים הַלָּלוּ לִפְנֵיכֶם. פָּתַח וְאָמַר, וַיִּקְרָא אֶל מֹשֶׁה, כָּאן אָלֶ\"ף קְטַנָּה לָמָּה. מִשּׁוּם שֶׁקְּרִיאָה זוֹ לֹא הָיְתָה בִּשְׁלֵמוּת. מָה הַטַּעַם? שֶׁזֶּה לֹא הָיָה אֶלָּא בַּמִּשְׁכָּן, וּבְאֶרֶץ אַחֶרֶת מִשּׁוּם שֶׁשְּׁלֵמוּת לֹא נִמְצֵאת אֶלָּא בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>עוֹד, כָּאן שְׁכִינָה, (שם, נקבה) שָׁם שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה, אָדָם שֵׁת אֱנוֹשׁ. אָדָם - שְׁלֵמוּת זָכָר וּנְקֵבָה. כָּאן נְקֵבָה. עוֹד, סוֹף הַפָּסוּק, וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר, מִשּׁוּם כָּךְ אָלֶ\"ף קְטַנָּה.</p>\n<p>עוֹד אָלֶ\"ף קְטַנָּה, מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּכִסְאוֹ וְכֶתֶר הַמַּלְכוּת עָלָיו, נִקְרָא מֶלֶךְ עֶלְיוֹן. כְּשֶׁיּוֹרֵד וְהוֹלֵךְ לְבֵית עַבְדּוֹ, נִקְרָא מֶלֶךְ קָטָן. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל זְמַן שֶׁהוּא לְמַעְלָה עַל הַכֹּל, נִקְרָא מֶלֶךְ עֶלְיוֹן. כֵּיוָן שֶׁהוּרַד מְדוֹרוֹ לְמַטָּה, הוּא מֶלֶךְ, אֲבָל לֹא עֶלְיוֹן כְּמוֹ מִקֹּדֶם, וְלָכֵן אָלֶ\"ף קְטַנָּה.</p>\n<p>וַיִּקְרָא, כָּךְ שָׁנִינוּ, זִמֵּן אוֹתוֹ לְהֵיכָלוֹ. מֵאֹהֶל מוֹעֵד, מַה זֶּה אֹהֶל מוֹעֵד? הָאֹהֶל שֶׁבּוֹ תְלוּיִים מוֹעֵד וְחַג וְשַׁבָּת לִמְנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) וְהָיוּ לְאֹתֹת וּלְמוֹעֲדִים. בּוֹ מַתְחִיל הַחֶשְׁבּוֹן לְהִמָּנוֹת, וּמִיהוּ? הַלְּבָנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לג) אֹהֶם בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח.</p>\n<p>לֵאמֹר, מַה זֶּה לֵאמֹר? כְּדֵי לְגַלּוֹת (אבל הכל אחד ויפה הוא, משום שהשלמות והיפי הוא מקום לגלות) מַה שֶּׁהָיָה נִסְתָּר פְּנִימָה. וּבְכָל מָקוֹם לֵאמֹר, כְּמוֹ שֶׁנֶּאֱמַר וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵאמֹר, שֶׁנִּתְּנָה רְשׁוּת לְגַלּוֹת, אֲבָל הַכֹּל אֶחָד, וְיָפֶה הוּא, מִשּׁוּם שֶׁהֲרֵי נִמְנָה לַלְּבָנָה הַדָּבָר הַהוּא, מִמָּקוֹם שֶׁמֹּשֶׁה עוֹמֵד.</p>\n<p>וַיְדַבֵּר ה' - לְמַעְלָה. אֶל מֹשֶׁה - בָּאֶמְצַע. לֵאמֹר - אַחֲרוֹן, מָקוֹם שֶׁיֵּשׁ רְשׁוּת לְגַלּוֹת. וְעוֹד וַיִּקְרָא אֶל מֹשֶׁה, מַה כָּתוּב לְמַעְלָה? (שמות טל) וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה וְגוֹ'. לָמָּה אֶל מֹשֶׁה? כָּךְ אָמְרוּ, מִשּׁוּם שֶׁמֹּשֶׁה רָאָה אוֹתוֹ בֶּהָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ בְּמַרְאֵה הָעַיִן, כְּמוֹ שֶׁנֶּאֱמַר (שם כז) כַּאֲשֶׁר הֶרְאָה אֹתְךְ בָּהָר. וְכָתוּב וּכְתִיב, (המדבר ח) כַּמַּרְאֶה אֲשֶׁר הֶרְאָה ה' אֶת מֹשֶׁה וְגו'. (שמות כה) וּרְאֵה וַעֲשֵׂה בְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר. עַכְשָׁו הֵבִיאוּ לוֹ כְּדֵי שֶׁיִּרְאֶה, אִם הוּא כְּמוֹ אוֹתוֹ מִשְׁכָּן שֶׁרָאָה.</p>\n<p>אֲבָל לָמָּה וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה? אֶלָּא, לְמֶלֶךְ שֶׁרָצָה לִבְנוֹת פַּלְטֵרִין לַגְּבִירָה, צִוָּה אֶת הָאֻמָּנִים: הֵיכָל זֶה בְּמָקוֹם פְּלוֹנִי, וְהֵיכָל זֶה בְּמָקוֹם פְּלוֹנִי, כָּאן מָקוֹם לַמִּטָּה, וְכָאן מָקוֹם לִמְנוּחָה. כֵּיוָן שֶׁעָשׂוּ אוֹתָם הָאֻמָּנִים, הֶרְאוּ לַמֶּלֶךְ. כָּךְ וַיָּבִיאוּ אֶת הַמִּשְׁכָּן אֶל מֹשֶׁה, בַּעַל הַבַּיִת, אִישׁ הָאֱלֹהִים. כֵּיוָן שֶׁנִּשְׁלַם הַהֵיכָל, הִזְמִינָה הַגְּבִירָה אֶת הַמֶּלֶךְ לַהֵיכָל, הִזְמִינָה אֶת בַּעְלָהּ אִתָּהּ, מִשּׁוּם כָּךְ וַיִּקְרָא אֶל מֹשֶׁה.</p>\n<p>וּמִשּׁוּם שֶׁמֹּשֶׁה הוּא בַּעַל הַבַּיִת, מַה כָּתוּב? (שמות לג) וּמֹשֶׁה יִקַּח אֶת הָאֹהֶל וְנָטָה לוֹ מִחוּץ לַמַּחֲנֶה. מֹשֶׁה שֶׁהוּא בַּעַל הַבַּיִת עָשָׂה כָּךְ, מַה שֶּׁאֵין רְשׁוּת לְאִישׁ אַחֵר לַעֲשׂוֹת כָּךְ.</p>\n<p>וַיְדַבֵּר ה' אֵלָיו - דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה. וְאָז, בְּשָׁעָה שֶׁהִזְדַּמֵּן מֹשֶׁה לְהִכָּנֵס, אָז פָּתַח וְאָמַר, אָדָם כִּי יַקְרִיב מִכֶּם. מָה אָדָם עוֹשֶׂה כָּאן? אֶלָּא כְּשֶׁהִתְחַבְּרוּ שֶׁמֶשׁ וּלְבָנָה כְּאֶחָד, פָּתַח וְאָמַר אָדָם, כַּכָּתוּב (חבקוק ג) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה. עָמַד, וְלֹא עָמְדוּ.</p>\n<p>כִּי יַקְרִיב מִכֶּם - כָּאן נִרְמָז, מִי שֶׁיַּעֲשֶׂה עֲבוֹדַת קָרְבָּן הַשָּׁלֵם, שֶׁיִּמָּצֵא זָכָר וּנְקֵבָה. מַשְׁמָע שֶׁכָּתוּב מִכֶּם, שֶׁיִּמָּצֵא בַּמַּרְאֶה שֶׁלָּכֶם. קָרְבָּן לַה' - שֶׁמַּקְרִיב הַכֹּל לְהֵאָחֵז כְּאֶחָד, לְמַעְלָה וּלְמַטָּה.</p>\n<p>מִן הַבְּהֵמָה - לְהַרְאוֹת אָדָם וּבְהֵמָה הַכֹּל כְּאֶחָד. מִן הַבָּקָר וּמִן הַצּאן - אֵלּוּ הַמֶּרְכָּבוֹת הַטְּהוֹרוֹת. שֶׁכֵּיוָן שֶׁאָמַר מִן הַבְּהֵמָה, יָכוֹל מִן הַכֹּל, בֵּין טְהוֹרוֹת וּבֵין טְמֵאוֹת? חָזַר וְאָמַר מִן הַבָּקָר וּמִן הַצֹאן.</p>\n<p>תַּקְרִיבוּ אֶת קָרְבַּנְכֶם, קָרְבָּנִי הָיָה צָרִיךְ (לכתב) ! מַה זֶּה קָרְבַּנְכֶם? אֶלָּא בַּתְּחִלָּה קָרְבָּן לַה', וְעַכְשָׁו קָרְבַּנְכֶם. קָרְבָּן לַה' אָדָם. קָרְבַּנְכֶם מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצּאן, לְהַרְאוֹת יִחוּד מִלְּמַטָּה לְמַעְלָה וּמִלְמַעְלָה לְמַטָּה. מִלְּמַטָּה לְמַעְלָה הַיְנוּ קָרְבָּן לַה'. מִלְמַעְלָה לְמַטָּה הַיְנוּ קָ רְבַּנְכֶם.</p>\n<p>לְמֶלֶךָ שֶׁיּוֹשֵׁב עַל הַר עֶלְיוֹן, לְמַעְלָה לְמַעְלָה, וְכִסֵּא מֻתְקָן עַל אוֹתוֹ הַר, וּמֶלֶךְ עֶלְיוֹן עַל הַכֹּל. אָדָם שֶׁמַּקְרִיב דּוֹרוֹן לַמֶּלֶךְ, צָרִיךְ לַעֲלוֹת מִדַּרְגָּה לְדַרְגָּה עַד שֶׁעוֹלֶה מִלְּמַטָּה לְמַעְלָה, לַמָּקוֹם שֶׁהַמֶּלֶךְ יוֹשֵׁב עֶלְיוֹן עַל הַכֹּל, וְאָז יוֹדְעִים שֶׁהֲרֵי מַעֲלִים דּוֹרוֹן לַמֶּלֶךְ, וְאוֹתוֹ דוֹרוֹן הוּא שֶׁל הַמֶּלֶךְ. יוֹרֵד הַדּוֹרוֹן מִלְמַעְלָה לְמַטָּה, הֲרֵי יוֹדְעִים שֶׁאוֹתוֹ דוֹרוֹן שֶׁל הַמֶּלֶךְ יוֹרֵד מִלְמַעְלָה לַאֲהוּב הַמֶּלֶךְ שֶׁהוּא לְמַטָּה.</p>\n<p>כָּךָ בַּתְּחִלָּה, אָדָם עוֹלֶה בְּדַרְגוֹתָיו מִלְּמַטָּה לְמַעְלָה, וְאָז קָרְבָּן לַה'. מִן הַבְּהֵמָה מִן הַבָּקָר, יוֹרֵד בְּדַרְגוֹתָיו מִלְמַעְלָה לְמַטָּה, וְאָז זֶה קָרְבַּנְכֶם. וּמִשּׁוּם כָּךְ כָּתוּב (שיר ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי, הַיְנוּ אָדָם וְקָרְבָּן לַה'. אִכְלוּ רֵעִים, הַיְנוּ מִן הַבְּהֵמָה מִן הַבָּקָר וּמִן הַצֹאן, וְאָז תַּקְרִיבוּ אֶת קָרְבַּנְכֶם.</p>\n<p>בָּאוּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה וּנְשָׁקוּהוּ עַל רֹאשׁוֹ. אָמְרוּ, בָּרוּךְ הָרַחֲמָן שֶׁזָּכִינוּ לִשְׁמֹעַ אֶת זֶה, וּבָרוּךְ הָרַחֲמָן שֶׁלֹּא נֶאֶבְדוּ הַדְּבָרִים הַלָּלוּ בְּאוֹתוֹ זָקֵן. קָמוּ וְהָלְכוּ. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ גֶפֶן אַחַת נְטוּעָה בְּגִנָּה אַחַת.</p>\n<p>פָּתַח אוֹתוֹ תִינוֹק וְאָמַר, אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂרֵקָה בְנִי אֲתוֹנוֹ. פָּסוּק זֶה הוּא סוֹד עֶלְיוֹן. אֹסְרִי!? אָסַר הָיָה צָרִיךְ לִכְתֹּב! עִירֹה!? עַיִר הָיָה צָרִיךְ לִכְתֹּב! אֶלָּא סוֹד הוּא לַדַּרְדַּקִּים שֶׁהֵם בְּבֵית רַבָּן לְהִשָּׁמֵר מֵאוֹתוֹ הַחֵץ שֶׁל עַיִר, וְהַשֵּׁם הַקָּדוֹשׁ נִכְלָל שָׁם י\"ה.</p>\n<p>וּכְמוֹ שֶׁכָּאן רָמוּז הַשֵּׁם הַקָּדוֹשׁ, כָּךְ גַּם וְלַשּׂרֵקָה, שׂוֹרֵק הָיָה צָרִיךְ לִכְתֹּב! נִכְלָל שָׁמָּה ו\"ה. בְּנִי!? בֵּן הָיָה צָרִיךְ לִכְתֹּב! שׂוֹרֵק, כַּכָּתוּב (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק. בֵּן, כַּכָּתוּב (זכריה ט) בֶּן אֲתֹנוֹת. לָמָּה שּׁרֵקָה, וְלָמָּה בְּנִי?</p>\n<p>אֶלָּא, כְּמוֹ שֶׁיֵּשׁ שֵׁם קָדוֹשׁ לִכְפּוֹת אֶת הָעַיִר, כָּךְ גַּם יֵשׁ שֵׁם קָדוֹשׁ לִכְפּוֹת כֹּחַ אַחֵר, שֶׁהוּא חֲמוֹר, שֶׁאִלְמָלֵא הַשֵּׁם הַקָּדוֹשׁ רָמוּז כָּאן, הָיוּ מַחֲרִיבִים עוֹלָם, י\"ה בְּכֹחַ זֶה, (וי\"ה) ו\"ה בְּכֹחַ זֶה, לִשְׁמֹר מֵהֶם אֶת הָעוֹלָם, וְלִשְׁמֹר אֶת הָאָדָם שֶׁלֹּא יִשְׁלְטוּ בוֹ בָּעוֹלָם.</p>\n<p>אָסְרִי לַגֶּפֶן, אֵיזוֹ גֶפֶן? זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְלָמָּה נִקְרֵאת גֶּפֶן? אֶלָּא מַה גֶּפֶן לֹא מְקַבֶּלֶת עָלֶיהָ נְטִיעָה אַחֶרֶת, כָּךְ גַּם כְּנֶסֶת יִשְׂרָאֵל לֹא מְקַבֶּלֶת עָלֶיהָ אֶלָּא אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כְּנֶסֶת יִשְׂרָאֵל נִכְפִּים לְפָנֶיהָ כָּל הַכֹּחוֹת הָאֲחֵרִים וְלֹא יְכוֹלִים לְהָרַע וְלִשְׁלֹט בָּעוֹלָם, וְלָכֵן הִטִּיל הַכָּתוּב אֶת הַשֵּׁם הַקָּדוֹשׁ בֵּינֵיהֶם בְּצַד זֶה וּבְצַד זֶה. בְּנִי אֲתֹנוֹ, שֶׁנֶּעֱקַר מִשּׁוּם אוֹתוֹ שׂוֹרֵק, כְּמוֹ שֶׁנֶּאֱמַר וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק וְגוֹ'.</p>\n<p>כִּבֵּס בַּיַּיִן לְבֻשׁוֹ וְגוֹ'. כִּבֵּס!? כּוֹבֵס הָיָה צָרִיךְ לִכְתֹּב! אֶלָּא כִּבֵּס מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וּמִיהוּ? זֶה מֶלֶךְ הַמָּשִׁיחַ. בַּיַּיִן - צַד הַשְּׂמֹאל. וּבְדַם עֲנָבִים - צַד הַשְּׂמֹאל, לְמַטָּה. וְעָתִיד מֶלֶךְ הַמָּשִׁיחַ לִשְׁלֹט לְמַעְלָה עַל כָּל הַכֹּחוֹת הָאֲחֵרִים שֶׁל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְלִשְׁבֹּר אֶת כֹּחָם מִלְמַעְלָה וּמִלְּמַטָּה.</p>\n<p>דָּבָר אַחֵר כִּבֵּס בַּיַּיִן לְבֻשׁוֹ - כְּמוֹ הַיַּיִן הַזֶּה, מַרְאֶה שִׂמְחָה, וְכֻלּוֹ דִּין (לעמים עובדי עבודת כוכבים ומזלות). כָּךְ גַּם מֶלֶךְ הַמָּשִׁיחַ, יַרְאֶה שִׂמְחָה לְיִשְׂרָאֵל, וְכֻלּוֹ דִּין לָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. כָּתוּב (בראשית א) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, זוֹ רוּחוֹ שֶׁל מֶלֶךְ הַמָּשִׁיחַ, וּמִיּוֹם שֶׁנִּבְרָא הָעוֹלָם הוּא רוֹחֵץ לְבוּשׁוֹ בַּיַּיִן הָעֶלְיוֹן.</p>\n<p>רְאֵה מַה כָּתוּב אַחֲרָיו, חַכְלִילִי עֵינַיִם מִיָּיִן וּלְבֶן שִׁנַּיִם מֵחָלָב. זֶה יַיִן הָעֶלְיוֹן, (שמרוה של התורה) שֶׁל הַתּוֹרָה שֶׁמַּרְוֶה, מִמֶּנּוּ שׁוֹתֶה. וּלְבֶן שִׁנַּיִם מֵחָלָב, שֶׁהֲרֵי הַתּוֹרָה יַיִן וְחָלָב, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>כָּתוּב (תהלים קד) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ (למה? משום שממקום של שמחה הוא בא, ומהו סוף הפסוק)? לְהַצְהִיל פָּנִים מִשָּׁמֶן, וַדַּאי מִמָּקוֹם שֶׁנִּקְרָא שָׁמֶן. בּא רְאֵה, שִׁירַת הַיַּיִן חֶדְוָה, הוּא מָקוֹם שֶׁכָּל שִׂמְחָה יוֹצֵאת מִמֶּנּוּ, וְסוֹפוֹ דִּין, מָה הַטַּעַם? מִשּׁוּם שֶׁסּוֹפוֹ מְקוֹם כִּנּוּס שֶׁל הַכֹּל, דִּין הוּא, וּבוֹ נִדּוֹן הָעוֹלָם, וְלָכֵן רֵאשִׁית חֶדְוָה, וְסוֹף דִּין. מִשּׁוּם כָּךְ לְהַצְהִיל פָּנִים מִשָּׁמֶן, מִמָּקוֹם שֶׁכָּל חֶדְוָה יוֹצֵאת מִמֶּנּוּ.</p>\n<p>וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד, אֵיזֶה לֶחֶם? אֶלָּא לֶחֶם סוֹעֵד (סומך) אֶת הָעוֹלָם. וְאִם תֹּאמַר שֶׁבּוֹ תָלוּי לְבַדּוֹ סַעַד הָעוֹלָם - לֹא כָּךְ, שֶׁהֲרֵי לַיְלָה בְּלִי יוֹם לֹא נִמְצָא, וְלֹא צָרִיךְ לְהַפְרִידָם. וּמִי שֶׁמַּפְרִידָם יִתְפָּרֵד מֵהַחַיִּים, וְהַיְנוּ שֶׁכָּתוּב (דברים ח) לְמַעַן הוֹדִיעֲךְ כִּי לֹא עַל הַלֶּחֶם לְבַדּוֹ יִחְיֶה הָאָדָם, מִשּׁוּם שֶׁלֹּא צָרִיךְ לְהַפְרִיד.</p>\n<p>וְאִם תֹּאמַר, דָּוִד אֵיךְ אָמַר וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד, הוֹאִיל וְלֹא תָלוּי בּוֹ לְבַדּוֹ סַעַד כָּל הָעוֹלָם? אֶלָּא דִּיּוּק הַדָּבָר וְלֶחֶם, וָא\"ו הִתּוֹסֵף, כְּמוֹ וַה', וְעַל זֶה הַכֹּל נִמְצָא כְּאֶחָד.</p>\n<p>בֹּא רְאֵה, מִי שֶׁמְּבָרֵךְ עַל הַמָּזוֹן, לֹא יְבָרֵךְ עַל שֻׁלְחָן רֵיק, וְצָרִיךְ לְהִמָּצֵא לֶחֶם עַל הַשֻּׁלְחָן וְכוֹס שֶׁל יַיִן בְּיָמִין, מָה הַטַּעַם? בִּשְׁבִיל לְקַשֵּׁר שְׂמֹאל בַּיָּמִין, וְלֶחֶם שֶׁיִּתְבָּרֵךְ מֵהֶם וּלְהִתְקַשֵּׁר בָּהֶם, וְלִהְיוֹת הַכֹּל קֶשֶׁר אֶחָד, לְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי. שֶׁהֲרֵי לֶחֶם נִקְשָׁר בְּיַיִן, וְיַיִן בְּיָמִין, וְאָז הַבְּרָכוֹת שׁוֹרוֹת בָּעוֹלָם, וְהַשֻּׁלְחָן נִתְקָן כָּרָאוּי.</p>"],[9522011485,"<p>אָמַר רַבִּי יִצְחָק, אִלְמָלֵא לֹא הִזְדַּמְּנָה לָנוּ דֶּרֶךְ זוֹ אֶלָּא לִשְׁמֹעַ הַדְּבָרִים הַלָּלוּ - דַּי לָנוּ. אָמַר רַבִּי יְהוּדָה, נָאֶה הוּא לְתִינוֹק זֶה שֶׁלֹּא יֵדַע כָּל זֶה, וַאֲנִי פּוֹחֵד עָלָיו אִם יִתְקַיֵּם בָּעוֹלָם מִשּׁוּם זֶה. אָמַר רַבִּי יִצְחָק, וְלָמָּה? אָמַר לוֹ, מִשּׁוּם שֶׁתִּינוֹק זֶה יָכוֹל לְהִסְתַּכֵּל בְּמָקוֹם שֶׁאֵין רְשׁוּת לְאָדָם לְהִסְתַּכֵּל בּוֹ, וַאֲנִי פּוֹחֵד עָלָיו, שֶׁעַד שֶׁלֹּא יַגִּיעַ לְפִרְקוֹ יַשְׁגִּיחַ וְיִסְתַּכֵּל וְיַעֲנִישׁוּ אוֹתוֹ.</p>\n<p>שָׁמַע אוֹתוֹ הַתִּינוֹק. אָמַר, אֵינִי פּוֹחֵד מֵעֹנֶשׁ לְעוֹלָמִים, שֶׁהֲרֵי בְּשָׁעָה שֶׁאַבָּא הִסְתַּלֵּק מִן הָעוֹלָם, בֵּרַךְ אוֹתִי וְהִתְפַּלֵּל עָלַי, וְיָדַעְתִּי שֶׁזְּכוּת אָבִי תָּגֵן עָלַי. אָמְרוּ לוֹ, וּמִי הוּא אָבִיךְ? אָמַר, (אין רבי יהודה) בְּנוֹ שֶׁל רַב הַמְנוּנָא הַזָּקֵן. לָקְחוּ אוֹתוֹ וְהִרְכִּיבוּ אוֹתוֹ עַל כִּתְפֵיהֶם שְׁלֹשָׁה מִילִין.</p>\n<p>קָרְאוּ עָלָיו, (שופטים יד) מֵהָאֹכֵל יָצָא מַאֲכָל וּמֵעַז יָצָא מָתוֹק וְגוֹ'. אָמַר לָהֶם אוֹתוֹ תִינוֹק, דָּבָר בָּא לִידֵיכֶם, פָּרְשׁוּ אוֹתוֹ. אָמְרוּ לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא זִמֵּן לָנוּ אֶת דֶּרֶךְ הַחַיִּים, אֱמֹר אַתָּה.</p>\n<p>פָּתַח וְאָמַר, מֵהָאֹכֵל יָצָא מַאֲכָל וּמֵעַז יָצָא מָתוֹק, פָּסוּק זֶה יֵשׁ לָנוּ בּוֹ סֶמֶךְ. מֵהָאֹכֵל - זֶה צַדִּיק, שֶׁכָּתוּב (משלי יג) צַדִּיק אֹכֵל לְשּׁבַע נַפְשׁוֹ. צַדִּיק אוֹכֵל וַדַּאי וְנוֹטֵל הַכֹּל, לָמָּה? לְשּבַע נַפְשׁוֹ, לָתֵת שּׁבַע לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא נֶפֶשׁ דָּוִד. יָצָא מַאֲכָל - שֶׁאִלְמָלֵא אוֹתוֹ צַדִּיק לֹא יֵצֵא מָזוֹן לְעוֹלָמִים וְלֹא יוּכַל הָעוֹלָם לַעֲמֹד (בו). וּמֵעַז יָצָא מָתוֹק - זֶה יִצְחָק שֶׁבֵּרַךְ אֶת יַעֲקֹב (בראשית כז) בְּטַל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ.</p>\n<p>עוֹד, אַף עַל גַּב שֶׁהַכֹּל אֶחָד, אִלּוּלֵא תֹקֶף הַדִּין הַקָּשֶׁה, לֹא יוֹצֵא דְבַשׁ. מִי הַדְּבַשׁ? זוֹ תוֹרָה שֶׁבְּעַל פֶּה, שֶׁכָּתוּב (תהלים יט) וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים. וּמֵעַז - זוֹ תוֹרָה שֶׁבִּכְתָב, שֶׁכָּתוּב (שם כט) ה' עֹז לְעַמּוֹ יִתֵּן. יָצָא מָתוֹק - זוֹ תוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>הָלְכוּ כְּאֶחָד שְׁלֹשָׁה יָמִים, עַד שֶׁהִגִּיעוּ לַמָּבוֹי שֶׁל הַקִּיר שֶׁל אִמּוֹ. כֵּיוָן שֶׁרָאֲתָה אוֹתוֹ, סִדְּרָה אֶת הַבַּיִת, וְיָשְׁבוּ שָׁם שְׁלֹשָׁה יָמִים אֲחֵרִים. בֵּרְכוּ אוֹתוֹ וְהָלְכוּ, וְסִדְּרוּ דְבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר, וַדַּאי יְרֻשַּׁת הַתּוֹרָה יָרַשׁ, וְאִלְמָלֵא זְכוּת אָבוֹת יֵעָנֵשׁ מִלְמַעְלָה. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתָם שֶׁהוֹלְכִים אַחַר הַתּוֹרָה, יוֹרְשִׁים אוֹתָהּ הֵם וּבְנֵיהֶם לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (ישעיה נט) וַאֲנִי זאת בְּרִיתִי אוֹתָם אָמַר ה' רוּחִי אֲשֶׁר עָלֶיךְ וְגוֹ'.</p>"],[9522011486,"<p>זְבוּלְן לְחוֹף יַמִּים יִשְׁכֹּן וְהוּא לְחוֹף אֳנִיֹּת וְיַרְכָתוֹ וְגוֹ'. רַבִּי אַבָּא פָּתַח, (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר הוֹדְךְ וַהֲדָרֶךְ. וְכִי זֶה הוֹד וְהָדָר לַחֲגֹר כְּלֵי זַיִן וּלְהִזְדָּרֵז בָּזֶה? מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְעוֹרֵךְ קְרָב בַּתּוֹרָה וּמְזָרֵז עַצְמוֹ בָּהּ - זֶהוּ שֶׁבַח (של רבונו), זֶהוּ הוֹד וְהָדָר, וְאַתָּה אוֹמֵר חֲגוֹר חַרְבְּךְ?</p>\n<p>אֶלָּא וַדַּאי שֶׁעִקַּר הַדָּבָר, אוֹת בְּרִית הַקֹּדֶשׁ נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא וְרָשַׁם אוֹתוֹ בִּבְנֵי אָדָם כְּדֵי שֶׁיִּשְׁמְרוּ אוֹתוֹ וְלֹא יִפְגְּמוּ אוֹתוֹ בִּפְגָם אֶת רֹשֶׁם הַמֶּלֶךְ הַזֶּה, וּמִי שֶׁפּוֹגֵם אוֹתוֹ, הֲרֵי עוֹמֶדֶת נֶגְדּוֹ (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית, לִנְקֹם נִקְמַת הַבְּרִית הַקָּדוֹשׁ שֶׁנִּרְשָׁם בּוֹ, וְהוּא פּוֹגֵם אוֹתוֹ.</p>\n<p>וּמִי שֶׁרוֹצֶה לִשְׁמֹר מָקוֹם זֶה, יִזְדָּרֵז וִיתַקֵּן עַצְמוֹ וְיָשִׂים כְּנֶגְדּוֹ בְּשָׁעָה שֶׁהַיֵּצֶר תּוֹקֵף אוֹתוֹ אֶת הַחֶרֶב שֶׁעוֹמֶדֶת עַל הַיָּרֵךְ, לְהִפָּרַע מִמִּי שֶׁפּוֹגֵם מָקוֹם זֶה, וְאָז חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר. גִּבּוֹר הוּא, וְגִבּוֹר נִקְרָא. וְעַל כָּךְ הוֹדְךְ וַהֲדָרֶךְ.</p>\n<p>דָּבָר אַחֵר חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר - מִי שֶׁיּוֹצֵא לַדֶּרֶךְ, יְתַקֵּן עַצְמוֹ בִּתְפִלָּה שֶׁל רִבּוֹנוֹ וְיִזְדָּרֵז בַּצֶּדֶק הַזֶּה, חֶרֶב עֶלְיוֹנָה, בִּתְפִלָּה וּבַקָּשׁוֹת עַד שֶׁלֹּא יֵצֵא לַדֶּרֶךְ, כַּכָּתוּב (תהלים פה) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. בֹּא רְאֵה, זְבוּלוּן תָּמִיד יָצָא לַדְּרָכִים וְלַשְּׁבִילִים וְעָרַךְ קְרָבוֹת, וְהִזְדָּרֵז בַּחֶרֶב הָעֶלְיוֹנָה הַזּוֹ בִּתְפִלָּה וּבַקָּשׁוֹת עַד שֶׁלֹּא יָצָא לַדֶּרֶךְ, וְאָז נִצַּח אֶת הָעַמִּים וְהִתְגַּבֵּר עֲלֵיהֶם. וְאִם תֹּאמַר, יְהוּדָה הֲרֵי נִתְקַן לָזֶה לַעֲרֹךְ קְרָבוֹת וְתִקּוּנִים בַּחֶרֶב הַזּוֹ, לָמָּה</p>\n<p>אֶלָּא, בּא זְרְבוּאֵלהוּ, ן? שְׁנֵים עָשָׂר הַשְּׁבָטִים הַלָּלוּ, כֻּלָּם תִּקּוּן שֶׁל הַמַּלְכָּה הֵם. שְׁנֵי תִקּוּנִים שֶׁל נְקֵבוֹת אָמַר שְׁלֹמֹה בְּשִׁיר הַשִּׁירִים, אֶחָד לָרוֹעֶה הָעֶלְיוֹן - יוֹבֵל, וְאֶחָד לַכַּלָּה - שְׁנַת הַשְּׁמִטָּה. תִּקּוּן אֶחָד לְמַעְלָה, וְתִקּוּן אֶחָד לְמַטָּה. גַּם מַעֲשֵׂה בְרֵאשִׁית הוּא כָּךְ, בִּשְׁנֵי הַמְּקוֹמוֹת הַלָּלוּ. מַעֲשֶׂה אֶחָד לְמַעְלָה, וּמַעֲשֶׂה אֶחָד לְמַטָּה, וְלָכֵן נִפְתְּחָה הַתּוֹרָה בְּב', מַעֲשֶׂה שֶׁלְּמַטָּה כְּמַעֲשֶׂה שֶׁלְּמַעְלָה. זֶה עוֹשֶׂה עוֹלָם הָעֶלְיוֹן, וְזֶה עוֹשֶׂה עוֹלָם הַתַּחְתּוֹן. כְּמוֹ זֶה.</p>\n<p>שְׁנֵי תִקּוּנִים שֶׁל נְקֵבוֹת אָמַר שְׁלֹמֹה, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה. אֶחָד לְמַעְלָה - בְּתִקּוּן עֶלְיוֹן שֶׁל הַשֵּׁם הַקָּדוֹשׁ. אֶחָד לְמַטָּה - בְּתִקּוּן תַּחְתּוֹן כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בֹּא רְאֵה, אַשְׁרֵי חֶלְקוֹ שֶׁל יַעֲקֹב הַקָּדוֹשׁ שֶׁזָּכָה לָזֶה. וַהֲרֵי נִתְבָּאֵר, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם לֹא נִמְצְאָה מִטָּה שְׁלֵמָה כְּמוֹ מִטָּתוֹ שֶׁל יַעֲקֹב, וּבְשָׁעָה שֶׁרָצָה לְהִסְתַּלֵּק מִן הָעוֹלָם, אָז הָיָה שָׁלֵם בְּכָל צְדָדָיו. אַבְרָהָם מִימִינוֹ, יִצְחָק מִשְּׂמֹאלוֹ, הוּא בָּאֶמְצַע, שְׁכִינָה לְפָנָיו. כֵּיוָן שֶׁרָאָה יַעֲקֹב אֶת זֶה, קָרָא לְבָנָיו וְאָמַר לָהֶם הֵאָסְפוּ, כְּדֵי שֶׁיִּמָּצֵא תִקּוּן שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה.</p>\n<p>בֹּא רְאֵה אֶת סוֹד הַדָּבָר. שְׁנֵי תִקּוּנִים נִמְצְאוּ שָׁם, אֶחָד עֶלְיוֹן וְאֶחָד תַּחְתּוֹן, שֶׁיִּהְיֶה הַכֹּל שָׁלֵם כָּרָאוּי. תִּקּוּן עֶלְיוֹן, תִּקּוּן נִסְתָּר וְנִגְלֶה, שֶׁהֲרֵי תִּקּוּן שֶׁל הַיּוֹבֵל הוּא, אוֹתוֹ שֶׁאָמַר שְׁלֹמֹה בְּשִׁיר הַשִּׁירִים, כְּמוֹ שֶׁאָמַרְנוּ, הָרֹאשׁ הַנִּסְתָּר שֶׁלֹּא הִתְגַּלָּה כָּאן וְלֹא יָפֶה לְגַלּוֹתוֹ. הַזְּרוֹעוֹת וְהַגּוּף הִתְגַּלּוּ, וְהֵם יְדוּעִים. שׁוֹקַיִם נִסְתְּרוּ וְלֹא הִתְגַּלּוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁנְּבוּאָה לֹא שׁוֹרָה כִּי אִם בָּאָרֶץ הַקְּדוֹשָׁה, וְתִקּוּן זֶה נִסְתָּר וְנִגְלֶה.</p>\n<p>תִּקּוּן אַחֵר לְמַטָּה - תִּקּוּן הַכַּלָּה שֶׁאָמַר שְׁלֹמֹה בְּשִׁיר הַשִּׁירִים, זֶהוּ תִּקּוּן שֶׁהִתְגַּלָּה יוֹתֵר, וְתִקּוּן זֶה בִּשְׁנֵים עָשָׂר שְׁבָטִים, שֶׁהֵם תַּחְתֶּיהָ, וְתִקּוּן הַגּוּף שֶׁלָּהּ.</p>"],[9522011487,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, (מלכים א ז) וַיַּעַשׂ אֶת הַיָּם מוּצָק וְגוֹ'. וְכָתוּב עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלֹשָׁה פֹנִים צָפוֹנָה וּשְׁלֹשָׁה פֹנִים יָמָּה וּשְׁלֹשָׁה פֹּנִים נֶגְבָּה וְגוֹ' וְהַיָּם עֲלֵיהֶם מִלְמָעְלָה וְגוֹ'. וְכָתוּב וְאֶת הַבָּקָר שְׁנֵים עָשָׂר תַּחַת הַיָּם (וגו'). עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר, כָּךְ הוּא וַדַּאי, שֶׁהַיָּם הַזֶּה מְתֻקָּן בִּשְׁנֵים עָשָׂר בִּשְׁנֵי עוֹלָמוֹת, בִּשְׁנֵים עָשָׂר לְמַעְלָה מֶרְכָּבוֹת מְמֻנּוֹת לְמַעְלָה בִּשְׁנֵים עָשָׂר, לְמַטָּה שְׁנֵים עָשָׂר שְׁבָטִים. כֵּיוָן שֶׁרָאָה יַעֲקֹב אֶת הַתִּקּוּן הָעֶלְיוֹן וְרָאָה שְׁכִינָה עוֹמֶדֶת מוּלוֹ, רָצָה לְהַשְׁלִים תִּקּוּנֶיהָ. קָרָא לִשְׁנֵים עָשָׂר בָּנָיו, וְאָמַר לָהֶם הֵאָסְפוּ, הַתְקִינוּ עַצְמְכֶם לְהַשְׁלִים אֶת הָאֱמוּנָה.</p>\n<p>בֹּא רְאֵה, שְׁנֵים עָשָׂר שְׁבָטִים בְּאַרְבָּעָה דְגָלִים בְּאַרְבָּעָה צְדָדִים, שְׁלֹשָׁה פוֹנִים צָפוֹנָה, וּשְׁלֹשָׁה פוֹנִים יַמָּה, וּשְׁלֹשָׁה פוֹנִים נֶגְבָּה, וּשְׁלֹשָׁה פוֹנִים מִזְרָחָה, וְהַיָּם עֲלֵיהֶם. וְכָךְ הוּא וַדַּאי, שְׁלֹשָׁה שְׁבָטִים לְכָל צַד, לְאַרְבָּעָה רוּחוֹת הָעוֹלָם, וּשְׁלֹשָׁה שְׁבָטִים לִזְרוֹעַ יָמִין, וּשְׁלֹשָׁה שְׁבָטִים לִזְרוֹעַ שְׂמֹאל, וּשְׁלֹשָׁה שְׁבָטִים לְיֶרֶךְ יָמִין, וּשְׁלֹשָׁה שְׁבָטִים לְיֶרֶךְ שְׂמֹאל, וְגוּף הַשְּׁכִינָה עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב וְהַיָּם עֲלֵיהֶם.</p>\n<p>מָה הַטַּעַם שְׁלֹשָׁה שְׁבָטִים לִזְרוֹעַ וּשְׁלֹשָׁה שְׁבָטִים לְיָרֵךְ וְכֵן לַכֹּל? אֶלָּא סוֹד הַדָּבָר - שְׁלֹשָׁה קְשָׁרִים הֵם בִּזְרוֹעַ יָמִין, וּשְׁלֹשָׁה בִּשְׂמֹאל, וּשְׁלֹשָׁה בְּיֶרֶךְ יָמִין, וּשְׁלֹשָׁה קְשָׁרִים בְּיֶרֶךְ שְׂמֹאל. נִמְצְאוּ שְׁנֵים עָשָׂר קְשָׁרִים לְאַרְבָּעָה צְדָדִים, וְהַגּוּף עֲלֵיהֶם. נִמְצְאוּ שְׁנֵים עָשָׂר עִם הַגּוּף כְּמוֹ שֶׁלְּמַעְלָה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (בראשית מט) כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר, וְזאת, מִשּׁוּם שֶׁבָּהּ הִשְׁתַּלֵּם הַחֶשְׁבּוֹן, כְּמוֹ שֶׁנֶּאֱמַר וִהַיָּם עֲלֵיהֶם מִלְמָעְלָה.</p>\n<p>שִׁבְעָֹה עֵינֵי ה' (זכריה ז) - הֵם שִׁבְעָה עֵינֵי הָעֵדָה, שִׁבְעִים סַנְהֶדְרִין. שַׂעֲרוֹתֶיהָ, כְּמוֹ שֶׁכָּתוּב (במדבר ב) כָּל הַפְּקוּדִים לְמַחֲנֵה יְהוּדָה מְאַת אֶלֶף וְגוֹ'. כָּל הַפְּקוּדִים לְמַחֲנֵה רְאוּבֵן, וְכֵן לְכֻלָּם.</p>\n<p>וְאִם תֹּאמַר, בְּמִצְרַיִם בְּהִסְתַּלְּקוּת יַעֲקֹב מֵהָעוֹלָם, שֶׁנִּמְצְאָה שְׁלֵמוּת בְּאוֹתָהּ שָׁעָה, כָּל זֶה אֵיפֹה הוּא? וַדַּאי שִׁבְעִים נְפָשׁוֹת הָיוּ, וְכָל אוֹתָם שֶׁהוֹלִידוּ בִּשְׁבַע עֶשְׂרֵה שָׁנִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן, כַּכָּתוּב (שמות א) וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וַיִּרְבּוּ וַיַּעַצְמוּ בִּמְאֹד מְאֹד, וְכָתוּב (תהלים מ) עָצְמוּ מִשַּׂעֲרוֹת רֹאשִׁי. אַשְׁרֵי חֶלְקוֹ שֶׁל יַעֲקֹב הַשָּׁלֵם, שֶׁהוּא הִשְׁתַּלֵּם לְמַעְלָה וּלְמַטָּה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא, אֲבָל בַּתִּקּוּן הָעֶלְיוֹן שֶׁל הַיּוֹבֵל אֵיךְ נִמְצָא כָּל זֶה? אָמַר לוֹ, אַרְיֵה, כֵּיוָן שֶׁסִּדֵּר רַגְלָיו לְהִכָּנֵס לַכֶּרֶם, מִיהוּ שֶׁיִּכָּנֵס עִמּוֹ?</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (איוב כג) וְהוּא בְאֶחָד וּמִי יְשִׁיבֶנּוּ וְנַפְשׁוֹ אִוְּתָה וַיָּעַשׂ. זֶה תִּקּוּן הָעֶלְיוֹן הַזֶּה, הוּא הַכֹּל אֶחָד, לֹא הָיָה בּוֹ פֵּרוּד כַּתַּחְתּוֹן הַזֶּה, שֶׁהֲרֵי כָּתוּב (בראשית ב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. וְאַף עַל גַּב שֶׁיֵּשׁ בּוֹ פֵּרוּד, כְּשֶׁיִּתְבּוֹנְנוּ בַדְּבָרִים, הַכֹּל עוֹלֶה לְאֶחָד.</p>\n<p>אֲבָל תִּקּוּן הַיּוֹבֵל הַזֶּה עוֹמֵד עַל שְׁנֵים עָשָׂר, כְּמוֹ הַתַּחְתּוֹן הַזֶּה, וְאַף עַל גַּב שֶׁהוּא אֶחָד, הָאֶחָד הַזֶּה מַשְׁלִים לְכָל צַד, בְּצַד זֶה וּבְצַד זֶה. אוֹתָם שִׁשָּׁה צְדָדִים עֶלְיוֹנִים הֵם שְׁנֵים עָשָׂר, שֶׁכָּל אֶחָד מַלְוֶה לַחֲבֵרוֹ וְנִכְלָל מִמֶּנּוּ, וְנִמְצְאוּ שְׁנֵים עָשָׂר, וְהַגּוּף וְהַכֹּל עוֹמֵד עַל שְׁנֵים עָשָׂר. מִי הַגּוּף? זֶה יַעֲקֹב, וַהֲרֵי נִתְבָּאֵר, אֶלָּא רֹאשׁ וְגוּף בְּאֶחָד עוֹמְדִים.</p>\n<p>עוֹד שְׁנֵים עָשָׂר - שְׁלֹשָׁה קְשָׁרִים שֶׁל זְרוֹעַ יָמִין, חֶסֶ\"ד חֲסָדִים. שְׁלֹשָׁה קְשָׁרִים שֶׁל זְרוֹעַ שְׂמֹאל, גְּבוּרָ\"ה גְּבוּרוֹת. שְׁלֹשָׁה קְשָׁרִים בְּיֶרֶךְ יָמִין, נֵצַ\"ח נְצָחִים. שְׁלֹשָׁה קְשָׁרִים בְּיֶרֶךְ שְׂמֹאל, הוֹ\"ד וְהוֹדוֹת - הֲרֵי שְׁנֵים עָשָׂר. וְהַגּוּף עוֹמֵד עֲלֵיהֶם - הֲרֵי שְׁלֹשָׁה עָשָׂר. עוֹד, בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הַתּוֹרָה מִתְפָּרֶשֶׁת, וְהַכֹּל אֶחָד, מִלְמַעְלָה לְמַטָּה בְּיִחוּד, עַד אוֹתוֹ מָקוֹם שֶׁעוֹמֵד עַל פֵּרוּד.</p>\n<p>שִׁבְעָה עֵינַיִם עֶלְיוֹנִים, אֵלֶּה שֶׁכָּתוּב (זכריה ד) עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים, זְכָרִים, שֶׁהֲרֵי זֶהוּ מָקוֹם שֶׁל זָכָר הוּא. כָּאן עֵינֵי ה' מְשׁוֹטְטוֹת, בְּתִקּוּן הַשְּׁכִינָה לְמַטָּה, מָקוֹם שֶׁל הַנְּקֵבָה (עומדת). שֶׁבַע עֵינַיִם עֶלְיוֹנוֹת כְּנֶגֶד זֶה שֶׁכָּתוּב לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְגוֹ'. מָקוֹם זֶה מַשְׁלִים לְכָל צַד.</p>\n<p>עוֹד הַשֵּׂעָר, כַּכָּתוּב (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה'. זֶהוּ שֶׁכָּתוּב (שם מ) עָצְמוּ מִשַּׂעֲרוֹת רֹאשִׁי. וְכָתוּב (איכה ג) חַסְדֵי ה' כִּי לֹא תָמְנוּ וְגוֹ'. וְתִקּוּנִים אֵלּוּ הִתְעַלּוּ (ממקום) לְמָקוֹם אַחֵר. וְאַף עַל גַּב שֶׁכָּאן נֶאֱמַר יוֹתֵר, וְעָלָה בְּמִשְׁקָל עֶלְיוֹן וְתַחְתּוֹן, וּשְׁלֹמֹה הַמֶּלֶךְ אֲמָרָם וְהִצְטָרַכְנוּ לְפָרְשָׁם. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים יוֹתֵר, שֶׁיּוֹדְעִים דֶּרֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָאן הַכֹּל הִתְגַּלָּה לְיוֹדְעֵי מִדּוֹת.</p>"],[9522011488,"<p>אָמַר רַבִּי יְהוּדָה, זְבוּלֻן וְיִשָּׂשכָר תְּנַאי עָשׂוּ. אֶחָד יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, וְאֶחָד יוֹצֵא וְעוֹשֶׂה מִסְחָר, וְתוֹמֵךְ בְּיִשָּׂשכָר, שֶׁכָּתוּב (משלי ג) וְתֹמְכֶיהָ מְאֻשָּׁר. וְהָיָה פּוֹרֵשׁ לַיַּמִּים לַעֲשׂוֹת מִסְחָר, וְחֶלְקוֹ כָּךְ הָיָה, שֶׁהֲרֵי הַיָּם הָיָה יְרֻשָּׁתוֹ.</p>\n<p>וְלָכֵן קוֹרֵא לוֹ יָרֵךְ. דֶּרֶךְ הַיָּרֵךְ לָצֵאת וּלְהִכָּנֵס. זֶהוּ שֶׁכָּתוּב (דברים לג) שְׂמַח זְבוּלֻן בְּצֵאתֶךְ וְיִשָּׂשכָר בְּאֹהָלֶיךְ. לְחוֹף יַמִּים יִשְׁכֹּן - בְּאוֹתָם יוֹרְדֵי הַיָּם לַעֲשׂוֹת מִסְחָר. לְחוֹף יַמִּים - אַף עַל גַּב שֶׁיָּם אֶחָד הָיָה בִּירֻשָּׁתוֹ, בִּשְׁנֵי יַמִּים הוּא שׁוֹרֶה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כָּל שְׁאָר הַיַּמִּים הָיוּ מְחַפְּשִׂים סְחוֹרָה בַּיָּם שֶׁלּוֹ. וְהוּא לְחוֹף אֳנִיֹּת, מָקוֹם שֶׁשָּׁם נִמְצָאוֹת כָּל הָאֳנִיּוֹת לַעֲשׂוֹת סְחוֹרָה. וְיַרְכָתוֹ, אָמַר רַבִּי חִזְקִיָּה, יַרְכָתוֹ מַגִּיעָה עַד גְּבוּל צִידוֹן, וּתְחוּם שֶׁלּוֹ נִפְרָד עַד אוֹתוֹ מָקוֹם, וּסְחוֹרָה שֶׁל כָּל בַּעֲלֵי הַסְּחוֹרָה סוֹבְבִים, וְשָׁבִים בִּסְחוֹרָתָם לְאוֹתוֹ מָקוֹם.</p>\n<p>רַבִּי אָחָא אָמַר, כָּתוּב (ויקרא ב) וְלֹא תַשְׁבִּית מֶלַח בְּרִית אֱלֹהֶיךְ מֵעַל מִנְחָתֶךְ עַל כָּל קָרְבָּנְךְ תַּקְרִיב מֶלַח. וְכִי לָמָּה מֶלַח? אֶלָּא מִשּׁוּם שֶׁהוּא מְמָרֵק וּמְבַשֵּׂם אֶת הַמַּר לָתֵת לוֹ טַעַם, וְאִם לֹא הָיָה (משום) מֶלַח, לֹא יָכוֹל הָעוֹלָם לִסְבֹּל אֶת הַמַּר. זֶהוּ שֶׁכָּתוּב (ישעיה כו) כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל. וְכָתוּב (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ.</p>\n<p>וּמֶלַח הִיא בְּרִית שֶׁהָעוֹלָם עוֹמֵד בּוֹ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וְלָכֵן נִקְרָא בְּרִית אֱלֹהֶיךְ, וְנִקְרָא יָם הַמֶּלַח, וְהַיָּם נִקְרָא עַל שְׁמוֹ.</p>\n<p>רַבִּי חִיָּיא אָמַר, כָּתוּב (תהלים יא) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב, זֶה הַמֶּלַח בַּיָּם (במים), וּמִי שֶׁמַּפְרִידָם גּוֹרֵם לְעַצְמוֹ מִיתָה, לָכֵן כָּתוּב לֹא תַשְׁבִּית מֶלַח, שֶׁהֲרֵי זֶה לֹא הוֹלֵךְ בְּלִי זֶה.</p>\n<p>אָמַר רַבִּי אָחָא, יָם אֶחָד הוּא, וְנִקְרָא יַמִּים. אֶלָּא יֵשׁ מָקוֹם בַּיָּם שֶׁהוּא מַיִם צְלוּלִים, וְיֵשׁ מָקוֹם שֶׁבּוֹ מַיִם מְתוּקִים, וְיֵשׁ מָקוֹם בּוֹ מַיִם מָרִים, וְלָכֵן קוֹרְאִים יַמִּים, וְעַל זֶה לְחוֹף יַמִּים. אָמַר רַבִּי אַבָּא, כָּל שֵׁבֶט וְשֵׁבֶט וְכָל אֶחָד וְאֶחֶד קֶשֶׁר אֶחָד מֵאוֹתָם קְשָׁרִים שֶׁמִּתְחַבְּרִים בַּגּוּף.</p>\n<p>רַבִּי אַבָּא הָיָה יוֹשֵׁב לַיְלָה אֶחָד, וְקָם לַעֲסֹק בַּתּוֹרָה. עַד שֶׁהָיָה יוֹשֵׁב, בָּא רַבִּי יוֹסֵי וְהִכָּה בַּפֶּתַח. אָמַר, בְּתֵבַת הַשָּׂרִים מְצוּיִים תַּכְשִׁיטִים.</p>\n<p>יָשְׁבוּ וְעָסְקוּ בַּתּוֹרָה. בֵּין כָּךְ קָם בֶּן הַמְאָרֵחַ וְיָשַׁב לִפְנֵיהֶם. אָמַר לָהֶם, מַה שֶּׁכָּתוּב (יהושע ב) וְהַחֲיִיתֶם אֶת אָבִי וְאֶת אִמִּי וְגוֹ', וְכָתוּב וּנְתַתֶּם לִי אוֹת אֱמֶת, מָה רָצְתָה מֵהֶם? אָמַר רַבִּי אַבָּא, יָפֶה שָׁאַלְתָּ, אֲבָל אִם שָׁמַעְתָּ דָבָר - אֱמֹר בְּנִי. אָמַר, עוֹד שְׁאֵלָה, שֶׁהֲרֵי הֵם נָתְנוּ לָהּ מַה שֶּׁלֹּא רָצְתָה מֵהֶם, שֶׁכָּתוּב אֶת תִּקְוַת חוּט הַשָּׁנִי הַזֶּה תִּקְשְׁרִי בַּחֲלוֹם וְגוֹ'.</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, הִיא רָצְתָה סִימַן חַיִּים, שֶׁכָּתוּב וְהַחֲיִיתֶם אֶת אָבִי וְגוֹ', וְאָמְרָה, סִימַן חַיִּים אֵינוֹ שׁוֹרֶה אֶלָּא בְּאוֹת אֱמֶת, וּמַהִי אוֹת אֱמֶת? זוֹ אוֹת ו', מִשּׁוּם שֶׁבּוֹ שְׁרוּיִים חַיִּים. כָּךְ לָמַדְנוּ, סִימָן שֶׁל מֹשֶׁה בִּקְשָׁה, וְהֵם לָמָּה נָתְנוּ לָהּ תִּקְוַת חוּט הַשָּׁנִי?</p>\n<p>אֶלָּא, הֵם אָמְרוּ, מֹשֶׁה הֲרֵי הִסְתַּלֵּק מִן הָעוֹלָם, שֶׁהֲרֵי הִתְכַּנֵּס הַשֶּׁמֶשׁ, וַהֲרֵי הִגִּיעַ זְמַן הַלְּבָנָה לִשְׁלֹט, סִימָן שֶׁל הַלְּבָנָה יֵשׁ לָנוּ לָתֵת לָךְ, וּמַהוּ? תִּקְוַת חוּט הַשָּׁנִי הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. סִימָן שֶׁל יְהוֹשֻׁעַ יִהְיֶה אֶצְלֵךְ, מִשּׁוּם שֶׁכָּעֵת שִׁלְטוֹן הַלְּבָנָה. קָמוּ רַבִּי אַבָּא וְרַבִּי יוֹסֵי וּנְשָׁקוּהוּ. אָמְרוּ, וַדַּאי עָתִיד אַתָּה לִהְיוֹת רֹאשׁ יְשִׁיבָה אוֹ אִישׁ גָּדוֹל בְּיִשְׂרָאֵל, וּמִיהוּ? רַבִּי בּוֹן.</p>\n<p>עוֹד שָׁאַל וְאָמַר, כָּל בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר שְׁבָטִים, הִסְתַּדְּרוּ לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, לָמָּה הִקְדִּים בַּבְּרָכוֹת אֶת זְבוּלוּן לְיִשָּׂשכָר תָּמִיד, וַהֲרֵי יִשָּׂשכָר הִשְׁתַּדְּלוּתוֹ בַּתּוֹרָה, וְתוֹרָה מַקְדִּימָה בְּכָל מָקוֹם? לָמָּה הִקְדִּים אֶת זְבוּלוּן בַּבְּרָכוֹת? אָבִיו הִקְדִּים אוֹתוֹ, מֹשֶׁה הִקְדִּים אוֹתוֹ?</p>\n<p>אֶלָּא זְבוּלוּן זָכָה עַל שֶׁהוֹצִיא פַּת מִפִּיו וְנָתַן לְפִיו שֶׁל יִשָּׂשכָר, מִשּׁוּם כָּךְ הִקְדִּימוֹ בַּבְּרָכוֹת. מִכָּאן לָמַדְנוּ, מִי שֶׁסּוֹעֵד אֶת בַּעַל הַתּוֹרָה, נוֹטֵל בְּרָכוֹת לְמַעְלָה וּלְמַטָּה, וְלֹא עוֹד, אֶלָּא שֶׁזּוֹכֶה לִשְׁנֵי שֻׁלְחָנוֹת, מַה שֶּׁלֹּא זוֹכֶה בֶּן אָדָם אַחֵר. זוֹכֶה לְעֹשֶׁר שֶׁיִּתְבָּרֵךְ בָּעוֹלָם הַזֶּה, וְזוֹכֶה לִהְיוֹת לוֹ חֵלֶק בָּעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב זְבוּלֻן לְחוֹף יַמִּים יִשְׁכֹּן וְהוּא לְחוֹף אֳנִיֹּת. כֵּיוָן שֶׁכָּתוּב לְחוֹף יַמִּים, אָז לָמָּה וְהוּא לְחוֹף אֳנִיֹּת? אֶלָּא לְחוֹף יַמִּים - בָּעוֹלָם הַזֶּה, לְחוֹף אֳנִיֹּת - בָּעוֹלָם הַבָּא, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) שָׁם אֳנִיּוֹת יְהַלֵּכוּן וְגוֹ'. שֶׁשָּׁם הוּא שֶׁפַע הָעוֹלָם הַבָּא.</p>"],[9522011489,"<p>פָּתַח וְאָמַר, (שיר ה) הִשְׁבַּעְתִּי אֶתְכֶם בְּנוֹת יְרוּשָׁלַיִם אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ שֶׁחוֹלַת אַהֲבָה אָנִי. וְכִי מִי קָרוֹב לַמֶּלֶךְ כְּמוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא אוֹמֶרֶת, אִם תִּמְצְאוּ אֶת דּוֹדִי מַה תַּגִּידוּ לוֹ? אֶלָּא בְּנוֹת יְרוּשָׁלַיִם אֵלּוּ הֵם נִשְׁמוֹת הַצַּדִּיקִים, שֶׁהֵם תָּמִיד קְרוֹבִים לַמֶּלֶךְ, וּמוֹדִיעִים לַמֶּלֶךְ בְּכָל יוֹם אֶת עִסְקֵי הַגְּבִירָה.</p>\n<p>שֶׁכָּךָ לָמַדְנוּ, בְּשָׁעָה שֶׁהַנְּשָׁמָה יוֹרֶדֶת לָעוֹלָם, כְּנֶסֶת יִשְׂרָאֵל נִכְנֶסֶת עָלֶיהָ בְּקִיּוּם שֶׁל שְׁבוּעָה, שֶׁתַּגִּיד לַמֶּלֶךְ וְתוֹדִיעַ לוֹ אַהֲבָתָהּ אֵלָיו, כְּדֵי לְהִתְפַּיֵּס עִמּוֹ.</p>\n<p>וּבַמֶּה,? מִשּׁוּם שֶׁחִיּוּב עַל בֶּן אָדָם לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ בַּפֶּה, בְּלֵב וָנֶפֶשׁ, וְלִקְשֹׁר הַכֹּל כְּשַׁלְהֶבֶת הַקְּשׁוּרָה בַּגַּחֶלֶת, וּבְאוֹתוֹ הַיִּחוּד שֶׁעוֹשֶׂה, גּוֹרֵם לְפַיֵּס הַמֶּלֶךְ עִם הַגְּבִירָה, וּמוֹדִיעַ לַמֶּלֶךְ אַהֲבָתָהּ אֵלָיו.</p>\n<p>דָּבָר אַחֵר בְּנוֹת יְרוּשָׁלַיִם - אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים, שֶׁשָּׁנִינוּ, יְרוּשָׁלַיִם עוֹמֶדֶת עַל שְׁנֵים עָשָׂר הָרִים. וּמִי שֶׁאָמַר עַל שִׁבְעָה, לֹא אָמַר לְהַשְׁלִים שְׁלֵמוּת. וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד, שֶׁיֵּשׁ שִׁבְעָה וְיֵשׁ אַרְבָּעָה וְיֵשׁ שְׁנֵים עָשָׂר, וְהַכֹּל אֶחָד.</p>\n<p>וַדַּאי עַל שְׁנֵים עָשָׂר הָרִים עוֹמֶדֶת, שְׁלֹשָׁה הָרִים לְצַד זֶה, וּשְׁלֹשָׁה הָרִים לְצַד זֶה, וְכֵן לְאַרְבַּע זָוִיּוֹת, וְאָז נִקְרֵאת חַיָּה, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל י) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל. וְאֵלֶּה נִקְרָאוֹת בְּנוֹת יְרוּשָׁלַיִם, מִשּׁוּם שֶׁעוֹמֶדֶת עֲלֵיהֶן, וְהֵן מְעִידוֹת עֵדוּת לַמֶּלֶךְ עַל כְּנֶסֶת יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (תהלים קכב) שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם ה'. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁיּוֹדְעִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עֲלֵיהֶם כָּתוּב (דברים יד) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ וּבְךְ בָּחַר ה' וְגוֹ'.</p>"],[9522011490,"<p>יִשָּׂשכָר חֲמֹר גָּרֶם רֹבֵץ בֵּין הַמִּשְׁפְּתָיִם. אָמַר רַבִּי אֶלְעָזָר, וְכִי יִשָּׂשכָר נִקְרָא חֲמוֹר? אִם מִשּׁוּם שֶׁהִשְׁתַּדֵּל בַּתּוֹרָה, נִקְרָא לוֹ סוּס אוֹ אַרְיֵה אוֹ נָמֵר, לָמָּה חֲמוֹר? אֶלָּא אָמְרוּ, מִשּׁוּם שֶׁחֲמוֹר נוֹשֵׂא מַשָּׂא, וְלֹא בוֹעֵט בַּאֲדוֹנוֹ כְּמוֹ שְׁאָר הַבְּהֵמוֹת, וְאֵין בּוֹ גַּסּוּת הָרוּחַ, וְלֹא חוֹשֵׁשׁ לִשְׁכַּב בְּמָקוֹם מְתֻקָּן. אַף כָּךְ יִשָּׂשכָר, שֶׁהִשְׁתַּדְּלוּתוֹ בַּתּוֹרָה, נוֹטֵל מַשָּׂא הַתּוֹרָה, וְלֹא בוֹעֵט בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, וְאֵין בּוֹ גַּסּוּת הָרוּחַ, כְּמוֹ הַחֲמוֹר שֶׁלֹּא חוֹשֵׁשׁ לִכְבוֹדוֹ אֶלָּא לִכְבוֹד רִבּוֹנוֹ (רבו). רֹבֵץ בֵּין הַמִּשְׁפְּתָיִם, כְּמוֹ שֶׁאָמַרְנוּ (אבות פ\"ו) וְעַל הָאָרֶץ תִּישַׁן, וְחַיֵּי צַעַר תִּחְיֶה, וּבַתּוֹרָה אַתָּה עָמֵל.</p>\n<p>דָּבָר אַחֵר יִשָּׂשכָר חֲמֹר גָּרֶם רֹבֵץ וְגוֹ' - פָּתַח וְאָמַר, (תהלים כז) לְדָוִד ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָע ה' מָעוֹז חַיַּי מִמִּי אֶפְחָד. כַּמָּה חֲבִיבִים הֵם דִּבְרֵי הַתּוֹרָה, כַּמָּה חֲבִיבִים אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, לֹא פוֹחֵד מִפִּגְעֵי הָעוֹלָם, שָׁמוּר הוּא לְמַעְלָה, שָׁמוּר הוּא לְמַטָּה. וְלֹא עוֹד, אֶלָּא שֶׁכּוֹפֵת כָּל פִּגְעֵי הָעוֹלָם וּמוֹרִיד אוֹתָם לְעֹמֶק תְּהוֹם רַבָּה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּכְנָס הַלַּיְלָה, הַפְּתָחִים נִסְתָּמִים, וּכְלָבִים וַחֲמוֹרִים שׁוֹרִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְנִתֶּנֶת רְשׁוּת לְהַשְׁחִית, וְכָל בְּנֵי הָעוֹלָם יְשֵׁנִים בְּמִטּוֹתֵיהֶם, וְנִשְׁמוֹת הַצַּדִּיקִים עוֹלוֹת לְהִתְעַנֵּג לְמַעְלָה. כְּשֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן וְנֶחֱלָק הַלַּיְלָה, הִתְעוֹרְרוּת קְדֻשָּׁה מִתְעוֹרֶרֶת בָּעוֹלָם, וְזֶה נֶאֱמַר בְּכַמָּה מְקוֹמוֹת.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁעוֹמֵד בְּאוֹתָהּ שָׁעָה וּמִשְׁתַּדֵּל בַּתּוֹרָה. כֵּיוָן שֶׁהוּא פּוֹתֵחַ בַּתּוֹרָה, אֶת כָּל אוֹתָם הַמִּינִים הָרָעִים הוּא מַכְנִיס לְנֶקֶב תְּהוֹם רַבָּה, וְכוֹפֵת אֶת הַחֲמוֹר, וּמוֹרִידוֹ בַּשָּׂרִים שֶׁתַּחַת הֶעָפָר שֶׁל זֻהֲמַת הַקֶּשֶׁר.</p>\n<p>מִשּׁוּם כָּךְ יִשָּׂשכָר, שֶׁהִשְׁתַּדְּלוּתוֹ בַּתּוֹרָה, כּוֹפֵת אֶת הַחֲמוֹר וּמוֹרִיד אוֹתוֹ מֵאוֹתוֹ גֶּרֶם הַמַּעֲלוֹת, שֶׁהוּא עוֹלֶה לְהַזִּיק לָעוֹלָם, וְשָׂם מְדוֹרוֹ בֵּין הַמִּשְׁפְּתָיִם, בֵּין זֻהֲמַת הַשָּׂרִים שֶׁבֶּעָפָר.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיַּרְא מְנֻחָה כִּי טוֹב וְאֶת הָאָרֶץ כִּי נָעֵמָה וַיֵּט שִׁכְמוֹ לִסְבֹּל וַיְהִי לְמַס עֹבֵד. וַיַּרְא מְנֻחָה כִּי טוֹב - זוֹ תּוֹרָה שֶׁבִּכְתָב. וְאֶת הָאָרֶץ כִּי נָעֵמָה - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. וַיֵּט שִׁכְמוֹ לִסְבֹּל - לִסְבֹּל עֹל הַתּוֹרָה וְלִדְבֹּק בָּהּ יָמִים וְלֵילוֹת. וַיְהִי לְמַס עֹבֵד - לִהְיוֹת עוֹבֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְלִדְבּק בּוֹ וּלְהַתִּישׁ אֶת עַצְמוֹ בָּהּ.</p>\n<p>רַבִּי שִׁמְעוֹן וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים מֵהַגָּלִיל הָעֶלְיוֹן לִטְבֶרְיָה. אָמַר רַבִּי שִׁמְעוֹן, נֵלֵךְ וְנִשְׁתַּדֵּל בַּתּוָֹרה, שֶׁכָּל מִי שֶׁיּוֹדֵעַ לְהִשְׁתַּדֵּל בַּתּוֹרָה וְלֹא מִשְׁתַּדֵּל - מִתְחַיֵּב בְּנַפְשׁוֹ, וְלֹא עוֹד, אֶלָּא נוֹתְנִים עָלָיו עֹל הָאָרֶץ וְשִׁעְבּוּד רַע, שֶׁכָּתוּב בְּיִשָּׂשכָר וַיֵּט שִׁכְמוֹ לִסְבֹּל. מַה זֶּה וַיֵּט? סָטָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ח) וַיִּטּוּ אַחֲרֵי הַבָּצַע. מִי שֶׁסּוֹטֶה דַרְכּוֹ וְעַצְמוֹ שֶׁלֹּא לִסְבֹּל עֹל תּוֹרָה, מִיָּד וַיְהִי לְמַס עֹבֵד.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא. אַשְׁרֵיהֶם בְּנֵי הָעוֹלָם, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, נֶאֱהָב לְמַעְלָה וְנֶאֱהָב לְמַטָּה, וְיוֹרֵשׁ בְּכָל יוֹם יְרֻשַּׁת הָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב לְהַנְחִיל אֹהֲבַי יֵשׁ. מַה זֶּה יֵשׁ? זֶהוּ עוֹלָם הַבָּא שֶׁלֹּא פוֹסְקִים מֵימָיו לְעוֹלָמִים וְנוֹטֵל שָׂכָר טוֹב עֶלְיוֹן שֶׁלֹּא זוֹכֶה בּוֹ אָדָם אַחֵר, וּמִיהוּ? יֵ\"שׁ. וּמִשּׁוּם כָּךְ רָמַז לָנוּ בִּשְׁמוֹ שֶׁל יִשָּׂשכָר שֶׁהִשְׁתַּדֵּל בַּתּוֹרָה - יֵשׁ שָׂכָר. זֶהוּ שָׂכָר שֶׁל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, יֵ\"שׁ.</p>\n<p>כָּתוּב (דניאל ז) חָזֵה הֲוֵית עַד דִּי כָרְסָוָן רְמִיו וְעַתִּיק יוֹמִין יְתִב וְגוֹ' חָזֵה הֲוֵית עַד דִּי כָרְסָוָן רְמִיו - כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, שְׁנֵי כִסְאוֹת נָפְלוּ, שְׁנַיִם לְמַעְלָה וּשְׁנַיִם לְמַטָּה. שְׁנַיִם לְמַעְלָה, כִּי הִתְרַחֲקָה הַתַּחְתּוֹנָה מֵהָעֶלְיוֹנָה. כִּסֵּא שֶׁל יַעֲקֹב הִתְרַחֵק מִכִּסֵּא דָוִד, וְכִסֵּא דָוִד נָפַל. זֶהוּ שֶׁכָּתוּב (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ. שְׁנֵי כִסְאוֹת לְמַטָּה - יְרוּשָׁלַיִם, וְאוֹתָם בַּעֲלֵי הַתּוֹרָה. וְהַכִּסְאוֹת שֶׁלְּמַטָּה כְּמוֹ הַכִּסְאוֹת שֶׁלְּמַעְלָה, בַּעֲלֵי הַתּוֹרָה, הַיְנוּ כִּסֵּא שֶׁל יַעֲקֹב. יְרוּשָׁלַיִם הַיְנוּ כִּסֵּא שֶׁל דָּוִד. וְעַל זֶה כָּתוּב עַד דִּי כָרְסְוָן, וְלֹא כִסֵּא. כִּסְאוֹת רַבִּים נָפְלוּ, וְכֻלָּם לֹא נָפְלוּ אֶלָּא מֵעֶלְבּוֹנָהּ שֶׁל תּוֹרָה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁאוֹתָם צַדִּיקֵי אֱמֶת מִשְׁתַּדְּלִים בַּתּוֹרָה, כָּל אוֹתָם כֹּחוֹת שְׁאָר הָעַמִּים, שֶׁל שְׁאָר הַחֲיָלוֹת, כָּל הַחֲיָלוֹת שֶׁלָּהֶם נִכְפִּים וְלֹא שׁוֹלְטִים בָּעוֹלָם, וְיִשְׂרָאֵל (ויש) מְזֻמָּנִים עֲלֵיהֶם לְהַעֲלוֹתָם עַל הַכֹּל. וְאִם לֹא, חֲמוֹר גּוֹרֵם לְיִשְׂרָאֵל לָלֶכֶת לַגָּלוּת וְלִפֹּל בֵּין הָעַמִּים וְלִשְׁלֹט עֲלֵיהֶם, וְכָל זֶה לָמָּה? מִשּׁוּם וַיַּרְא מְנֻחָה כִּי טוֹב, וּמְתֻקָּן לְפָנָיו, וְיָכוֹל לְהַרְוִיחַ בִּגְלָלָהּ כַּמָּה טוֹבוֹת וְכַמָּה כִסּוּפִים, וְהִטָּה דַרְכּוֹ שֶׁלֹּא לִסְבֹּל עֹל תּוֹרָה, מִשּׁוּם כָּךְ וַיְהִי לְמַס עֹבֵד.</p>\n<p>כָּתוּב (שיר ז) הַדּוּדָאִים נָתְנוּ רֵיחַ וְעַל פְּתָחֵינוּ כָּל מְגָדִים חֲדָשִׁים גַּם יְשָׁנִים וְגוֹ'. הַדּוּדָאִים נָתְנוּ רֵיחַ - (הדודאים) אֵלּוּ אוֹתָם שֶׁמָּצָא רְאוּבֵן, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ל) וַיִּמְצָא דוּדָאִים בַּשָּׂדֶה, וְלֹא הִתְחַדְּשׁוּ דִּבְרֵי תוֹרָה אֶלָּא עַל יָדָיו בְּיִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר וּמִבְּנֵי יִשָּׂשכָר יוֹדְעֵי בִינָה לָעִתִּים וְגוֹ'.</p>\n<p>וְעַל פְּתָחֵינוּ כָּל מְגָדִים - הֵם גָּרְמוּ לִהְיוֹת עַל פְּתָחֵינוּ, עַל פִּתְחֵי בָּתֵּי כְנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, כָּל מְגָדִים. חֲדָשִׁים גַּם יְשָׁנִים - כַּמָּה דְבָרִים חֲדָשִׁים וְעַתִּיקִים שֶׁל הַתּוֹרָה שֶׁהִתְגַּלּוּ עַל יְדֵיהֶם, לְקָרֵב אֶת יִשְׂרָאֵל לַאֲבִיהֶם שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב לָדַעַת מַה יַּעֲשֶׂה יִשְׂרָאֵל.</p>\n<p>דּוֹדִי צָפַנְתִּי לָךְ (שיר ז) - מִכָּאן לָמַדְנוּ, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כָּרָאוּי וְיוֹדֵעַ לְחַדֵּשׁ דְּבָרִים וּלְחַדֵּד דְּבָרִים כָּרָאוּי, אוֹתָם הַדְּבָרִים עוֹלִים עַד כִּסֵּא הַמֶּלֶךְ, וּכְנֶסֶת יִשְׂרָאֵל פּוֹתַחַת לָהֶם שְׁעָרִים וְגוֹנֶזֶת אוֹתָם. וּבְשָׁעָה שֶׁנִּכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן, מוֹצִיאָה אוֹתָם לְפָנָיו, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּכֵּל בָּהֶם וְשָׂמֵחַ. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בַּעֲטָרוֹת עֶלְיוֹנוֹת וְשָׂמֵחַ בַּגְּבִירָה. זֶהוּ שֶׁכָּתוּב חֲדָשִׁים גַּם יְשָׁנִים דּוֹדִי צָפַנְתִּי לָךְ. וּמֵאוֹתָהּ שָׁעָה דְּבָרָיו כְּתוּבִים בַּסֵּפֶר, זֶהוּ שֶׁכָּתוּב (מלאכי ג) וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כָּרָאוּי, אַשְׁרָיו בָּעוֹלָם הַזֶּה וְאַשְׁרָיו בָּעוֹלָם הַבָּא. עַד כָּאן שִׁלְטוֹן יְהוּדָה, זְרוֹעַ שֶׁנִּכְלֶלֶת בַּכֹּל, בַּכֹּחַ שֶׁל כָּל הַצְּדָדִים, שְׁלֹשָׁה קְשָׁרִים שֶׁל הַזְּרוֹעַ לְהִתְגַּבֵּר עַל הַכֹּל.</p>"],[9522011491,"<p>דָּן יָדִין עַמּוֹ כְּאַחַד שִׁבְטֵי יִשְׂרָאֵל. רַבִּי חִיָּיא אָמַר, פָּסוּק זֶה כָּךְ יֵשׁ לוֹ לוֹמַר, דָּן יָדִין לְשִׁבְטֵי יִשְׂרָאֵל, אוֹ דָּן יָדִין לְשִׁבְטֵי יִשְׂרָאֵל כְּאֶחָד. מַהוּ דָּן יָדִין עַמּוֹ, וְאַחַר כָּךְ כְּאַחַד שִׁבְטֵי יִשְׂרָאֵל? אֶלָּא דָּן, הוּא שֶׁכָּתוּב בּוֹ (במדבר י) מְאַסֵּף לְכָל הַמַּחֲנוֹת, שֶׁהוּא יֶרֶךְ שְׂמֹאל, וְהוֹלֵךְ בַּסּוֹף.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁיְּהוּדָה וּרְאוּבֵן נוֹסְעִים, הַלְוִיִּם וְהָאָרוֹן פּוֹרְשִׂים דְּגָלִים, וְנוֹסֵעַ דֶּגֶל אֶפְרַיִם שֶׁהוּא לְמַעֲרָב. יֶרֶךְ יָמִין נוֹסַעַת מֵחֻלְיוֹת הַמִּדָּה. וְאִם תֹּאמַר, זְבוּלוּן שֶׁהוּא נִכְנָס וְיוֹצֵא, שֶׁכָּתוּב בּוֹ (דברים לג) שְׂמַח זְבוּלֻן בְּצֵאתֶךְ, וְכָתוּב וְיַרְכָתוֹ וְגוֹ'. אֶלָּא וַדַּאי יְהוּדָה נִכְלָל מֵהַכֹּל.</p>\n<p>בֹּא רְאֵה, מַלְכוּת הָעֶלְיוֹנָה נִכְלֶלֶת מֵהַכֹּל, וִיהוּדָה הוּא מַלְכוּת תַּחְתּוֹנָה. כְּמוֹ שֶׁמַּלְכוּת עֶלְיוֹנָה נִכְלֶלֶת מֵהַכֹּל, כָּךְ גַּם מַלְכוּת תַּחְתּוֹנָה נִכְלֶלֶת מֵהַכֹּל, מִגּוּף, מִיָּרֵךְ, כְּדֵי לְהִתְגַּבֵּר בְּכֹחוֹ.</p>\n<p>כָּתוּב מִימִינ\"וֹ אֵ\"שׁ דָּ\"ת לָמוֹ. תּוֹרָה נִתְּנָה מִצַּד הַגְּבוּרָה, וּגְבוּרָה נִכְלֶלֶת בְּיָמִין וּבַגּוּף וְיָרֵךְ וּבַכֹּל. כָּךְ גַּם הַסֵּדֶר הָרִאשׁוֹן הוּא יְהוּדָה, מַלְכוּת שֶׁבָּאָה מִצַּד שֶׁל גְּבוּרָה וְנִכְלֶלֶת בַּיָּמִין, בַּגּוּף וּבַיָּרֵךְ, וּבַכֹּל נִכְלֶלֶת, כְּמוֹ שֶׁהַמַּלְכוּת הָעֶלְיוֹנָה נִכְלֶלֶת מֵהַכֹּל.</p>\n<p>סֵדֶר שֵׁנִי רְאוּבֵן, שֶׁהוּא לְצַד דָּרוֹם, וְדָרוֹם הוּא יָמִין. אֶת כָּל כֹּחַ הַיָּמִין נָטַל יְהוּדָה, מִשּׁוּם (שנעשתה) שֶׁהָעָבְרָה הַמַּלְכוּת מֵרְאוּבֵן, כְּמוֹ שֶׁנֶּאֱמַר פַּחַז כַּמַּיִם אַל תּוֹתַר, וְנָטַל אוֹתָהּ יְהוּדָה, וְהִתְגַּבֵּר בְּתֹקֶף הַיָּמִין שֶׁהָיָה מֵרְאוּבֵן, וְכָךְ כָּתוּב בְּדָוִד, (תהלים קיא) נְאֻם ה' לַאדנִי שֵׁב לִימִינִי, מִשּׁוּם שֶׁשְּׂמֹאל נִכְלֶלֶת בַּיָּמִין וּמִתְחַזֵּק בְּכֹחוֹ. זֶהוּ שֶׁכָּתוּב (שם קיח) יְמִין ה' עֹשָׂה חָיִל וְגוֹ'. יְהוּדָה וּרְאוּבֵן הָיוּ שְׁתֵּי זְרוֹעוֹת.</p>\n<p>סֵדֶר שְׁלִישִׁי אֶפְרַיִם, שֶׁהוּא יֶרֶךְ יָמִין, וְנוֹסֵעַ לִפְנֵי הַשְּׂמֹאל תָּמִיד. וְדָן (זה), שֶׁהוּא יֶרֶךְ שְׂמֹאל, נוֹסֵעַ בַּסּוֹף, וְעַל כָּךְ הוּא הַמְאַסֵּף לְכָל הַמַּחֲנוֹת לְצִבְאוֹתָם וְהוֹלֵךְ בַּסּוֹף.</p>\n<p>יְהוּדָה נוֹטֵל כֹּחַ בִּשְׁתֵּי זְרוֹעוֹת, מִשּׁוּם שֶׁרְאוּבֵן, שֶׁהוּא יָמִין, (העברה) אָבְדָה מִמֶּנּוּ הַבְּכוֹרָה, הַכְּהֻנָּה וְהַמַּלְכוּת, וְעַל זֶה כָּתוּב בִּיהוּדָה (דברים לג) יָדָיו רָב לוֹ וְעֵזֶר מִצָּרָיו תִּהְיֶה.</p>\n<p>בֹּא רְאֵה, כָּתוּב (מלכים א י) וַיַּעַשׂ הַמֶּלֶךְ שְׁלֹמֹה כִּסֵּא שֵׁן גָּדוֹל. הַכִּסֵּא שֶׁל שְׁלֹמֹה עָשָׂה אוֹתוֹ כְּמוֹ שֶׁלְּמַעְלָה, וְכָל הַדְּיוֹקְנָאוֹת (של כאן) שֶׁלְּמַעְלָה עָשָׂה כָּךְ. וְעַל זֶה כָּתוּב וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ, מֶלֶךְ דָּבָר סָתוּם הוּא. וְכֵן (מלכים א ב) וּשְׁלֹמֹה יָשַׁב עַל כִּסֵּא דָּוִד אָבִיו וַתִּכֹּן מַלְכֻתוֹ מְאֹד, שֶׁעָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת.</p>\n<p>דָּן יָדִין עַמּוֹ - בַּהַתְחָלָה, וְאַחַר כָּךְ שִׁבְטֵי יִשְׂרָאֵל כְּאַחַד, כְּיִחוּדוֹ שֶׁל עוֹלָם, כְּמוֹ שֶׁהָיָה בְּשִׁמְשׁוֹן, שֶׁהוּא יְחִידִי עָשָׂה דִין בָּעוֹלָם, וְדָן וְהָרַג כְּאֶחָד, וְלֹא הִצְטָרֵךְ סֶמֶךְ.</p>\n<p>דָּן יָדִין עַמּוֹ. רַבִּי יִצְחָק אָמַר, דָּן, הַיְנוּ נָחָשׁ, אוֹרֵב עַל דְּרָכִים וּשְׁבִילִים. וְאִם תֹּאמַר עַל שִׁמְשׁוֹן לְבַדּוֹ הוּא, אַף כָּךְ גַּם לְמַעְלָה, זֶהוּ נֶפֶשׁ אַחֶרֶת (נחש קטן) מְאַסֵּף לְכָל הַמַּחֲנוֹת, וְאוֹרֵב בַּדְּרָכִים וּבַשְּׁבִילִים. אַחַר כָּךְ מִכָּאן יוֹצְאִים חֲיָלוֹת וּמַחֲנוֹת, אוֹתָם שֶׁאוֹרְבִים לָאֲנָשִׁים עַל חֲטָאִים, שֶׁזּוֹרְקִים אוֹתָם לְאָחוֹר אַחֲרֵי כִתְפֵיהֶם. אָמַר רַבִּי חִיָּיא, נָחָשׁ הַקַּדְמוֹנִי לְמַעְלָה, עַד שֶׁלֹּא יִתְבַּסֵּם בְּיַיִן שֶׁל שִׂמְחָה.</p>\n<p>נָחָשׁ עֲלֵי דֶרֶךְ. בֹּא רְאֵה, כְּמוֹ שֶׁיֵּשׁ דֶּרֶךְ לְמַעְלָה, כָּךְ גַּם יֵשׁ דֶּרֶךְ לְמַטָּה, וְהַיָּם נִפְרָד לְכַמָּה דְרָכִים בְּכָל צַד. וְיֵשׁ דֶּרֶךְ אַחַת שֶׁבָּאָה וּמַגְדִּילָה אֶת הַיָּם, וּמְגַדֵּל דָּגִים רָעִים לְמִינֵיהֶם. כְּמוֹ שֶׁהוֹצִיאוּ מַיִם לְמַטָּה, דָּגִים טוֹבִים, דָּגִים רָעִים, דְּגֵי צְפַרְדֵּעַ, כְּמוֹ זֶה דָּגִים רָעִים לְמִינֵיהֶם.</p>\n<p>וּכְשֶׁמִּשְׁתַּמְּטִים מִדֶּרֶךְ הַיָּם, נִרְאִים רוֹכְבִים עַל סוּסֵיהֶם. וְאִלְמָלֵא הַנָּחָשׁ הַזֶּה, שֶׁהוּא כּוֹנֵס אֶת כָּל הַמַּחֲנוֹת, אוֹרֵב בְּסוֹף הַדְּרָכִים וּמְפַזֵּר אוֹתָם לְאָחוֹר, הָיוּ מַחֲרִיבִים אֶת הָעוֹלָם. מִצַּד שֶׁל אֵלֶּה יוֹצְאִים מְכַשְּׁפִים לָעוֹלָם. בֹּא רְאֵה, בְּבִלְעָם כָּתוּב, (במדבר כד) וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, מִשּׁוּם שֶׁהֵם עוֹמְדִים לִלְחֹשׁ בְּכִשְׁפֵי הָעוֹלָם.</p>\n<p>רְאֵה מַה כָּתוּב? יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ. מַה זֶּה עֲלֵי דֶרֶךְ? אֶלָּא נָחָשׁ, מִי שֶׁמִּשְׁתַּדֵּל אַחֲרָיו, מַכְחִישׁ פָּמַלְיָה שֶׁל מַעְלָה, וּמִיהוּ? אוֹתָהּ דֶּרֶךְ עֶלְיוֹנָה שֶׁיּוֹצֵאת מִלְמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מג) הַנּוֹתֵן בַּיָּם דָּרֶךְ וְגוֹ'. נָחָשׁ, מִי שֶׁמִּשְׁתַּדֵּל אַחֲרָיו, כְּאִלּוּ הוֹלֵךְ עַל אוֹתָהּ דֶּרֶךְ עֶלְיוֹנָה לְהַכְחִישׁוֹ, מִשּׁוּם שֶׁמֵּאוֹתָהּ דֶּרֶךְ נִזּוֹנִים הָעוֹלָמוֹת הָעֶלְיוֹנִים.</p>\n<p>וְאִם תֹּאמַר, דָּן לָמָּה הוּא בַּדַּרְגָּה הַזּוֹ? אֶלָּא כַּכָּתוּב (בראשית ג) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים. כָּךְ גַּם הַנֹּשֵׁךְ עִקְּבֵי סוּס וְגוֹ', כְּדֵי לִשְׁמֹר אוֹתוֹ לְכָל הַמַּחֲנוֹת. אָמַר רַבִּי אֶלְעָזָר, תִּקּוּן הַכִּסֵּא הוּא. בּא רְאֵה, כִּסֵּא שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, נָחָשׁ אֶחָד מְנַעֲנֵעַ בְּקִשְׁרֵי הַשַּׁרְבִיט שֶׁלְּמַעְלָה מֵהָאֲרָיוֹת.</p>\n<p>כָּתוּב (שופטים ג) וַתָּחֶל רוּחַ ה' לְפַעֲמוֹ בְּמַחֲנֵה דָן וְגוֹ'. בּא רְאֵה, שִׁמְשׁוֹן הָיָה נְזִיר עוֹלָם, וּפָרוּשׁ מִן הָעוֹלָם הוּא, וְהִתְגַּבֵּר בּוֹ כֹּחַ חָזָק, וְהוּא הָיָה נָחָשׁ בָּעוֹלָם הַזֶּה כְּנֶגֶד עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, שֶׁהֲרֵי יְרֻשַּׁת חֵלֶק בִּרְכַּת דָּן אָבִיו יָרַשׁ, שֶׁכָּתוּב יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ וְגוֹ'.</p>\n<p>אָמַר רַבִּי חִיָּיא, נָחָשׁ יָדוּעַ, שְׁפִיפוֹן מַהוּ? אָמַר לוֹ, סוֹד הַתִּקּוּן שֶׁל מְכַשְּׁפִים שֶׁנָּחָשׁ הוּא שְׁפִיפוֹן, כָּךְ גַּם אוֹתוֹ בִּלְעָם הָרָשָׁע, בַּכֹּל הָיָה יוֹדֵעַ. בֹּא רְאֵה, כָּתוּב (במדבר כג) וַיֵּלֶךְ שֶׁפִי, לִפְעָמִים בָּזֶה וְלִפְעָמִים בָּזֶה.</p>\n<p>וְאִם תֹּאמַר, דָּן אֵין דַּרְגָּתוֹ בָּזֶה - כָּךְ זֶה וַדַּאי, אֶלָּא הִתְמַנָּה עַל דַּרְגָּה זוֹ (לאותו) לִהְיוֹת צַד אַחֲרוֹן, וְשֶׁבַח הוּא שֶׁלּוֹ, מְמֻנִּים שֶׁל הַמֶּלֶךְ בָּזֶה, וּמְמֻנֶּה עַל זֶה, וְכָבוֹד הוּא לְכָל אוֹתָם הַמְמֻנִּים. וְכִסֵּא הַמֶּלֶךְ נִתְקָן בְּכָל אוֹתָם הַמְמֻנִּים, בְּכָל אוֹתָם הַמְמֻנִּים שֶׁתַּחְתֵּיהֶם נִפְרָדוֹת דְּרָכִים וּדְרָגוֹת, הֵן לְטוֹב וְהֵן לְרַע, וְכֻלָּם נֶאֱחָזִים בְּתִקּוּנֵי הַכִּסֵּא הַלָּלוּ. וְלָכֵן דָּן לְצַד צָפוֹן, בְּנֶקֶב תְּהוֹם רַבָּה. שֶׁבְּצַד צָפוֹן כַּמָּה קְבוּצוֹת מְחַבְּלִים הִזְדַּמְּנוּ לְשָׁם, וְכֻלָּם שָׂרִים מְמֻנִּים לְהָרַע אֶת הָעוֹלָם.</p>\n<p>לָכֵן הִתְפַּלֵּל יַעֲקֹב וְאָמַר לִישׁוּעָתְךְ קִוִּיתִי ה', בְּכָל הַשְּׁבָטִים לֹא אָמַר לִישׁוּעָתְךְ אֶלָּא בָּזֶה, מִשּׁוּם שֶׁרָאָה לוֹ תֹּקֶף חָזָק שֶׁל הַנָּחָשׁ, מְרַחֵשׁ דִּין לְהִ תְגַּבֵּר.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים לִרְאוֹת אֶת רַבִּי שִׁמְעוֹן בְּקַפּוֹטְקִיָּא. אָמַר רַבִּי חִזְקִיָּה זֶה שֶׁאָמַרְנוּ לְעוֹלָם יְסַדֵּר אָדָם שִׁבְחוֹ שֶׁל רִבּוֹנוֹ וְאַחַר כָּךְ יִתְפַּלֵּל תְּפִלָּתוֹ. מִי שֶׁלִּבּוֹ טָרוּד וְרוֹצֶה לְהִתְפַּלֵּל תְּפִלָּתוֹ, וְהוּא בְצָרָה, וְלֹא יָכוֹל לְסַדֵּר אֶת שֶׁבַח רִבּוֹנוֹ כָּרָאוּי, מַה הוּא?</p>\n<p>אָמַר לוֹ, אַף עַל גַּב שֶׁלֹּא יָכוֹל לְכַוֵּן לִבּוֹ וּרְצוֹנוֹ, סִדּוּר וְשֶׁבַח שֶׁל רִבּוֹנוֹ לָמָּה שֶׁיִּגָּרַע? אֶלָּא יְסַדֵּר אֶת שֶׁבַח רִבּוֹנוֹ אַף עַל גַּב שֶׁלֹּא יָכוֹל לְכַוֵּן, וְיִתְפַּלֵּל תְּפלָּתוֹ. זֶהוּ שֶׁכָּתוּב תְּפִלָּה לְדָוִד שִׁמְעָה ה' צֶדֶק הַקְשִׁיבָה רִנָּתִי. שִׁמְעָה ה' צֶדֶק - בַּתְּחִלָּה, מִשּׁוּם שֶׁהוּא סִדּוּר שֶׁל שֶׁבַח רִבּוֹנוֹ. וְאַחַר כָּךְ הַקְשִׁיבָה רִנָּתִי הַאֲזִינָה תְּפִלָּתִי. מִי שֶׁיָּכוֹל לְסַדֵּר שֶׁבַח רִבּוֹנוֹ וְלֹא עוֹשֶׂה, עָלָיו כָּתוּב (ישעיה א) גַּם כִּי תַרְבּוּ תְפִלָּה אֵינֶנִּי שֹׁמֵעַ יְדֵיכֶם וְגוֹ'.</p>\n<p>כָּתוּב (שמות כט) אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם. תְּפִלּוֹת כְּנֶגֶד תְּמִידִין תִּקְּנוּם. בֹּא רְאֵה, בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר גַּם לְמַעְלָה, וּבַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה גַּם כָּךְ לְמַעְלָה מִמֶּנּוּ, עַד שֶׁמַּגִּיעָה הַהִתְעוֹרְרוּת לְמָקוֹם שֶׁצָּרִיךְ הַנֵּר לְהִדָּלֵק וְנִדְלָק, וּבְהִתְעוֹרְרוּת הֶעָשָׁן שֶׁלְּמַטָּה נִדְלָק נֵר לְמַעְלָה, וּכְשֶׁזֶּה נִדְלָק (מנורות), כָּל הַמְּנוֹרוֹת הָאֲחֵרוֹת דּוֹלְקוֹת, וּמִתְבָּרְכִים מִמֶּנּוּ כָּל הָעוֹלָמוֹת. נִמְצָא שֶׁהִתְעוֹרְרוּת הַקָּרְבָּן תִּקּוּן הָעוֹלָם וְהַבְּרָכוֹת שֶׁל כָּל הָעוֹלָמוֹת.</p>\n<p>הֲרֵי כֵּיצַד? מַתְחִיל הֶעָשָׁן לַעֲלוֹת, אוֹתָם דְּיוֹקְנָאוֹת קְדוֹשִׁים שֶׁמְּמֻנִּים עַל הָעוֹלָם נֶהֱנִים (נתקנים) לְהִתְעוֹרֵר, וּמְעוֹרְרִים אֶת הַדְּרָגוֹת בִּתְשׁוּקָה עֶלְיוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) הַכְּפִירִים שֹׁאֲגִים לַטָּרֶף וְגוֹ'. אֵלֶּה מְעוֹרְרִים לִדְרָגוֹת עֶלְיוֹנוֹת שֶׁמֵּעֲלֵיהֶן עַד שֶׁהַהִתְעוֹרְרוּת מַגִּיעָה, עַד שֶׁרוֹצֶה הַמֶּלֶךְ לִהִתְגַּבֵּר בַּגְּבִירָה.</p>\n<p>וּבַתְּשׁוּקָֹה שֶׁלְּמַטָּה נוֹבְעִים מַיִם תַּחְתּוֹנִים כְּנֶגֶד מַיִם עֶלְיוֹנִים, שֶׁהֲרֵי לֹא נוֹבְעִים מַיִם עֶלְיוֹנִים אֶלָּא בַּהִתְעוֹרְרוּת שֶׁל תְּשׁוּקָה שֶׁלְּמַטָּה, וְאָז הַתְּשׁוּקָה נִדְבֶּקֶת, וְנוֹבְעִים מַיִם תַּחְתּוֹנִים כְּנֶגֶד מַיִם עֶלְיוֹנִים, וְהָעוֹלָמוֹת מִתְבָּרְכִים, וְכָל הַמְּנוֹרוֹת דּוֹלְקוֹת, וְעֶלְיוֹנִים וְתַחְתּוֹנִים נִמְצָאִים בִּבְרָכוֹת.</p>\n<p>בֹּא רְאֵה, כֹּהֲנִים וּלְוִיִּם מִתְעוֹרְרִים לְחַבֵּר שְׂמֹאל בְּיָמִין. אָמַר רַבִּי חִזְקִיָּה, הַכֹּל כָּךְ הוּא וַדַּאי, אֲבָל כָּךְ שָׁמַעְתִּי, כֹּהֲנִים וּלְוִיִּם, זֶה מְעוֹרֵר שְׂמֹאל, וְזֶה מְעוֹרֵר יָמִין, מִשּׁוּם שֶׁהִתְחַבְּרוּת זָכָר אֶל הַנְּקֵבָה אֵינוֹ אֶלָּא בִּשְׂמֹאל וְיָמִין, כְּמוֹ שֶׁנֶּאֱמַר (שירב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וְאָז מִתְחַבֵּר הַזָּכָר בַּנְּקֵבָה, וּתְשׁוּקָה נִמְצֵאת, וְהָעוֹלָמוֹת מִתְבָּרְכִים, וְעֶלְיוֹנִים וְתַחְתּוֹנִים בְּשִׂמְחָה.</p>\n<p>וְלָכֵן כֹּהֲנִים וּלְוִיִם מְעוֹרְרִים דָּבָר לְמַטָּה, לְעוֹרֵר תְּשׁוּקָה וַחֲבִיבוּת לְמַעְלָה, שֶׁהַכֹּל תָּלוּי בַּיָּמִין וּבַשְּׂמֹאל. נִמְצָא שֶׁהַקָּרְבָּן יְסוֹד הָעוֹלָם, תִּקּוּן שֶׁל הָעוֹלָם, שִׂמְחָה שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים. אָמַר רַבִּי יוֹסֵי, וַדַּאי יָפֶה אָמַרְתָּ, וְכָךְ הוּא, וְכָךְ שָׁמַעְתִּי הַדָּבָר וְשָׁכַחְתִּי אוֹתוֹ, וַאֲנִי שָׁמַעְתִּי זֶה, וְהַכֹּל בְּאֶחָד עוֹלֶה.</p>\n<p>עַכְשָׁו תְּפִלָּה בִּמְקוֹם קָרְבָּן, וְצָרִיךְ אָדָם לְסַדֵּר שֶׁבַח רִבּוֹנוֹ כָּרָאוּי, וְאִם לֹא יְסַדֵּר, אֵין תְּפִלָּתוֹ תְּפִלָּה. בּא רְאֵה, סִדּוּר שָׁלֵם שֶׁל שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - מִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, שֶׁבָּזֶה מִתְעוֹרְרוֹת וְנִשְׁפָּעוֹת בְּרָכוֹת לְכָל הָעוֹלָמוֹת.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, לֹא הִשְׁרָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל בַּגָּלוּת בֵּין הָעַמִּים אֶלָּא כְּדֵי שֶׁיִּתְבָּרְכוּ שְׁאָר הָעַמִּים בִּגְלָלָם, שֶׁהֲרֵי הֵם מַשְׁפִּיעִים בְּרָכוֹת מִלְמַעְלָה לְמַטָּה בְּכָל יוֹם.</p>\n<p>הָלְכוּ, עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ נָחָשׁ אֶחָד שֶׁהָיָה מִסְתּוֹבֵב (ומצדד) בַּדֶּרֶךְ, וְסָטוּ מִן הַדֶּרֶךְ. בָּא אֲלֵיהֶם אִישׁ אֶחָד. הָרַג אוֹתוֹ הַנָּחָשׁ. הֶחֱזִירוּ רָאשֵׁיהֶם וְרָאוּ אֶת אוֹתוֹ אִישׁ שֶׁמֵּת. אָמְרוּ, וַדַּאי אוֹתוֹ נָחָשׁ עָשָׂה אֶת שְׁלִיחוּת רִבּוֹנוֹ. בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילָנוּ.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, יְהִי דָן נָחָשׁ עֲלֵי דֶרֶךְ, מָתַי הָיָה דָּן נָחָשׁ? בִּימֵי יָרָבְעָם, שֶׁכָּתוּב (מלכים א יב) וְאֶת הָאֶחָד נָתַן בְּדָן. לָמָּה נִתַּן שָׁם עֲלֵי דֶרֶךְ, עַל אוֹתוֹ הַדֶּרֶךְ? כְּדֵי לִמְנֹעַ (אותו דרך שעולים) שֶׁלֹּא יַעֲלוּ לִירוּשָׁלַיִם (ולא יעלו שם). וְזֶה דָּן הָיָה לָהֶם נָחָשׁ לְיִשְׂרָאֵל עֲלֵי דֶרֶךְ, עֲלֵי דֶרֶךְ וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר וַיִּוָּעַץ הַמֶּלֶךְ וְגוֹ'. שְׁפִיפֹן עֲלֵי אֹרַח, שֶׁעָקַץ אֶת יִשְׂרָאֵל. וְהַכֹּל לֹא הָיָה אֶלָּא עֲלֵי דֶרֶךְ וַעֲלֵי אֹרַח, לִמְנֹעַ מִיִּשְׂרָאֵל שֶׁלֹּא יַעֲלוּ לִירוּשָׁלַיִם לַחְגֹּג חַגֵּיהֶם וּלְהַקְרִיב קָרְבָּנוֹת וְעוֹלוֹת וְלַעֲבֹד שָׁם.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהִגִּיעוּ הַבְּרָכוֹת לְיַד מֹשֶׁה לְבָרֵךְ אֶת כָּל הַשְּׁבָטִים, רָאָה אֶת דָּן שֶׁהָיָה קָשׁוּר בְּנָחָשׁ, חָזַר וְקָשַׁר אוֹתוֹ בְּאַרְיֵה, זֶהוּ שֶׁכָּתוּב (דברים לג) וּלְדָן אָמַר דָּן גּוּר אַרְיֵה יְזַנֵּק מִן הַבָּשָׁן. מָה הַטַּעַם? כְּדֵי (שהוא) שֶׁיִּהְיֶה רֵאשִׁית וָסוֹף, שֶׁל אַרְבָּעָה הַדְּגָלִים קָשׁוּר בִּיהוּדָה, שֶׁהוּא מֶלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר גּוּר אַרְיֵה יְהוּדָה, וְהוּא רֵאשִׁית הַדְּגָלִים, וְסוֹף הַדְּגָלִים הוּא דָּן, שֶׁכָּתוּב דָּן גּוּר אַרְיֵה וְגוֹ', לִהְיוֹת רֵאשִׁית וָסוֹף קִשׁוּרִים בְּמָקוֹם אֶחָד.</p>\n<p>לִישׁוּעָתְךָֹ קִוִּיתִי ה'. רַבִּי חִיָּיא אָמַר, כְּמוֹ שֶׁנֶּאֱמַר (שופטים יג) וְהוּא יָחֵל לְהוֹשִׁיעַ אֶת יִשְׂרָאֵל מִיַּד פְּלִשְׁתִּים. אָמַר (רבי אחא), וְכִי לָמָּה קִוִּיתִי, וַהֲרֵי הִסְתַּלֵּק יַעֲקֹב מִן הָעוֹלָם בְּאוֹתוֹ הַזְּמַן מִלִּפְנֵי שָׁנִים? לָמָּה אָמַר שֶׁהוּא מְחַכֶּה לְאוֹתָהּ הַיְשׁוּעָה? (אלא ודאי) אָמַר לוֹ, וַדַּאי סוֹד הַדָּבָר כַּכָּתוּב (שמות יז) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל, יִשְׂרָאֵל סְתָם. אַף כָּאן וְהוּא יָחֵל לְהוֹשִׁיעַ אֶת יִשְׂרָאֵל - יִשְׂרָאֵל סְתָם. לָכֵן אָמַר לִישׁוּעָתְךְ קִוִּיתִי ה'. אָמַר רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, וְיָפֶה. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים לְהִשְׁתַּדֵּל בַּתּוֹרָה כְּדֵי לִזְכּוֹת בָּהּ בַּחַיִּים שֶׁלְּמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר (דברים ל) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ לָשֶׁבֶת עַל הָאֲדָמָה וְגוֹ'.</p>"],[9522011492,"<p>גָּד גְּדוּד יְגוּדֶנּוּ וְהוּא יָגֻד עָקֵב. רַבִּי יֵיסָא אָמַר, מִגָּד נִשְׁמָע שֶׁהֲרֵי חֲיָלוֹת יֵצְאוּ לַעֲרֹךְ קְרָב, מַשְׁמָע שֶׁכָּתוּב גָּד. בְּכָל מָקוֹם גִּימֶ\"ל דָּלֶ\"ת, חֲיָלוֹת וּמַחֲנוֹת יוֹצְאִים מֵהֶם, שֶׁהֲרֵי גִּימֶ\"ל נוֹתֵן וְדָלֶ\"ת לוֹקֵחַ, וּמִכָּאן (ומושכת) כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת תְּלוּיִים בָּהֶם.</p>\n<p>בֹּא רְאֵה, אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, לֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים, וְהוּא מַשְׁלִים לָעֲנִיִּים, וְלָכֵן עוֹמְדִים כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת וְנִזּוֹנִים מִכָּאן. וְעַל זֶה גָּד, זֶה מוֹצִיא וְנוֹתֵן, וְזֶה לוֹקֵט וְלוֹקֵחַ, וְנִזּוֹנִים הַבַּיִת וְכָל אַנְשֵׁי הַבַּיִת.</p>\n<p>אָמַר רַבִּי יִצְחָק, אִלְמָלֵא שֶׁהָיָה גָּד מִבְּנֵי הַשְּׁפָחוֹת, הַשָּׁעָה עָמְדָה לוֹ לְהַשְׁלִים יוֹתֵר מֵהַכֹּל. זֶהוּ שֶׁכָּתוּב (בראשית ל) בָּא גָּד, קְרִי, וְכָתוּב בָּגָד חָסֵר אָלֶ\"ף, שֶׁהֲרֵי הַשָּׁעָה עוֹמֶדֶת בִּשְׁלֵמוּת, וְהִסְתַּלְּקָה מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (איוב ו) אַחַי בָּגְדוּ כְמוֹ נָחַל, מִשּׁוּם שֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ הִסְתַּלֵּק בְּאוֹתָהּ שָׁעָה, וְכָתוּב בָּגָד חָסֵר אָלֶ\"ף, וְלָכֵן לֹא זָכָה בְּאָרֶץ הַקְּדוֹשָׁה וְהִסְתַּלֵּק מִמֶּנָּה.</p>\n<p>רַבִּי יְהוּדָה אָמַר, מִנַּיִן לִרְאוּבֵן שֶׁהָיָה כָּזֶה? כַּכָּתוּב פַּחַז כַּמַּיִם אַל תּוֹתַר, שֶׁהִסְתַּלְּקוּ הַמַּיִם וְלֹא שָׁפְעוּ, וַהֲרֵי נִתְבָּאֵר בַּמֶּה פָּגַם, וּשְׁנֵיהֶם לֹא זָכוּ בָּאָרֶץ הַקְּדוֹשָׁה, וַחֲיָלוֹת וּמַחֲנוֹת לְהַנְחִיל לְיִשְׂרָאֵל אֶת הָאָרֶץ. בֹּא רְאֵה, מַה שֶּׁנִּפְגַּם בְּגָד, הִשְׁתַּלֵּם בְּאָשֵׁר. זֶהוּ שֶׁכָּתוּב מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. עַכְשָׁו הִשְׁלִים גִּימֶ\"ל לְדָלֶ \"ת.</p>"],[9522011493,"<p>רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא נִשְׁמְטוּ בִּמְעָרַת לוֹד, שֶׁנִּכְנְסוּ מִפְּנֵי תֹקֶף הַשֶּׁמֶשׁ, שֶׁהָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי אַבָּא, נְסוֹבֵב אֶת הַמְּעָרָה הַזּוֹ בְּדִבְרֵי תוֹרָה. פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, שִׂימֵנִי כַּחוֹתָם עַל לִבֶּךְ כַחוֹתָם עַל זְרוֹעֶךְ וְגוֹ', רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶת יָהּ. בְּפָסוּק זֶה הִתְעוֹרַרְנוּ, אֲבָל לַיְלָה אֶחָד הָיָה, כְּשֶׁהָיִיתִי עוֹמֵד לִפְנֵי אַבָּא וְשָׁמַעְתִּי מִמֶּנּוּ דָּבָר, שֶׁאֵין שְׁלֵמוּת וְרָצוֹן וּתְשׁוּקַת כְּנֶסֶת יִשְׂרָאֵל בַּקָּדוֹשׁ-בָּרוּךְ-הוּא אֶלָּא בְּנִשְׁמוֹת הַצַּדִּיקִים, שֶׁהֵם מְעוֹרְרִים נְבִיעַת הַמַּיִם הַתַּחְתּוֹנִים כְּנֶגֶד הָעֶלְיוֹנִים, וּבְאוֹתָהּ שָׁעָה שְׁלֵמוּת הָרָצוֹן וְהַתְּשׁוּקָה בִּדְבֵקוּת אַחַת לַעֲשׂוֹת פֵּרוֹת.</p>\n<p>בֹּא רְאֵה, אַחַר שֶׁנִּדְבְּקוּ זֶה בָּזֶה וְהִיא קִבְּלָה רָצוֹן, הִיא אוֹמֶרֶת, שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ. לָמָּה כַּחוֹתָם? אֶלָּא דַרְכּוֹ שֶׁל חוֹתָם, כֵּיוָן שֶׁנִּדְבָּק בְּמָקוֹם אֶחָד, אַף עַל גַּב שֶׁזָּז מִמֶּנּוּ, הֲרֵי נִשְׁאָר רֹשֶׁם בְּאוֹתוֹ מָקוֹם וְלֹא זָז מִמֶּנּוּ, שֶׁכָּל הָרֹשֶׁם וְכָל הַדְּמוּת שֶׁלּוֹ נִשְׁאָר בּוֹ. כָּךְ אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, הֲרֵי נִדְבַּקְתִּי בְּךְ, אַף עַל גַּב שֶׁזַּזְתִּי מִמְּךְ וְהָלַכְתִּי לַגָּלוּת, שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ, כְּדֵי שֶׁיִּשָּׁאֵר כָּל דְּמוּתִי בְּךְ כַּחוֹתָם הַזֶּה שֶׁיִּשָּׁאֵר כָּל דְּמוּתוֹ בְּאוֹתוֹ מָקוֹם שֶׁנִּדְבַּק בּוֹ.</p>\n<p>כִּי עַזָּה כַמָּוֶת אַהֲבָה, חֲזָקָה הִיא, כִּפְרֵדַת הָרוּחַ מֵהַגּוּף. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁאָדָם מַגִּיעַ לְהִסְתַּלֵּק מִן הָעוֹלָם וְרוֹאֶה מַה שֶּׁרוֹאֶה, הָרוּחַ הוֹלֶכֶת בְּכָל אֵיבְרֵי הַגּוּף וְהַגַּלִּים עוֹלִים, כְּמִי שֶׁהוֹלֵךְ בַּיָּם בְּלִי מְשׁוֹטִים, עוֹלֶה וְיוֹרֵד וְלֹא מוֹעִיל לוֹ. בָּא וְנִפְרָד מִכָּל אֵיבְרֵי הַגּוּף, וְאֵין (להם) קֹשִׁי כְּמוֹ הַיּוֹם שֶׁנִּפְרֶדֶת הָרוּחַ מֵהַגּוּף. כָּךְ חֹזֶק הָאַהֲבָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל לַקָּדוֹשׁ-בָּרוּךְ-הוּא כְּחֹזֶק הַמָּוֶת בְּשָׁעָה שֶׁרוֹצָה הָרוּחַ לְהִפָּרֵד מֵהַגּוּף.</p>\n<p>קָשָׁה כִּשְׁאוֹל קִנְאָה, כָּל מִי שֶׁאוֹהֵב וְלֹא קוֹשֵׁר עִמּוֹ קִנְאָה, אֵין אַהֲבָתוֹ אַהֲבָה. כֵּיוָן שֶׁקִּנֵּא, הֲרֵי הָאַהֲבָה הֻשְׁלְמָה. מִכָּאן לָמַדְנוּ שֶׁצָּרִיךְ אָדָם לְקַנֵּא לְאִשְׁתּוֹ כְּדֵי שֶׁיִּתְקַשֵּׁר עִמָּהּ אַהֲבָה שְׁלֵמָה, שֶׁהֲרֵי מִתּוֹךְ כָּךְ לֹא יִתֵּן עֵינוֹ בְּאִשָּׁה אַחֶרֶת. מַה זֶּה קָשָׁה כִּשְׁאוֹל? אֶלָּא מַה שְּׁאוֹל קָשֶׁה בְּעֵינֵי הָרְשָׁעִים לָרֶדֶת אֵלָיו, כָּךְ קִנְאָה קָשָׁה בְּעֵינֵי מִי שֶׁאוֹהֵב וּמְקַנֵּא לְהִפָּרֵד מֵאַהֲבָה.</p>\n<p>דָּבָר אַחֵר קָשָׁה כִּשְׁאוֹל קִנְאָה - מַה שְּׁאוֹל, בְּשָׁעָה שֶׁמּוֹרִידִים אֵלֶיהָ אֶת הָרְשָׁעִים, מוֹדִיעִים לָהֶם חֲטָאֵיהֶם עַל מָה הוֹרִידוּ אוֹתָם, וְקָשֶׁה לָהֶם, כָּךְ מִי שֶׁמְּקַנֵּא, הוּא תּוֹבֵעַ עַל חֶטְאוֹ וּמְחַשֵּׁב (וחושד) כַּמָּה מַעֲשִׂים, וְאָז נִקְשָׁר בּוֹ קֶשֶׁר הָאַהֲבָה.</p>\n<p>רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶת יָהּ, מַה זֶּה שַׁלְהֶבֶת יָהּ? זוֹ שַׁלְהֶבֶת שֶׁבּוֹעֶרֶת וְיוֹצֵאת מִתּוֹךְ שׁוֹפָר שֶׁהוּא מִתְעוֹרֵר וְשׂוֹרֵף, וּמִיהוּ? הַשְּׂמֹאל. זֶהוּ שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, זֶה שׂוֹרֵף שַׁלְהֶבֶת שֶׁל הָאַהֲבָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְלָכֵן (שם ח) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. שֶׁהֲרֵי כְּשֶׁבָּא הַיָּמִין שֶׁהוּא מַיִם, מוֹסִיף שְׂרֵפַת הָאַהֲבָה, וְלֹא נִכְבְּתָה שַׁלְהֶבֶת הַשְּׂמֹאל, כְּמוֹ שֶׁנֶּאֱמַר וִימִינוֹ תְּחַבְּקֵנִי, זֶהוּ מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה, וְכֵן הַכֹּל כַּגָּוֶן הַזֶּה.</p>\n<p>עַד שֶׁהָיוּ יוֹשְׁבִים, שָׁמְעוּ אֶת קוֹלוֹ שֶׁל רַבִּי שִׁמְעוֹן שֶׁהָיָה בָּא בַּדֶּרֶךְ, הוּא וְרַבִּי יְהוּדָה וְרַבִּי יִצְחָק. הִתְקָרֵב לַמְּעָרָה, יָצְאוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא. אָמַר רַבִּי שִׁמְעוֹן, מִכָּתְלֵי הַמְּעָרָה רָאִיתִי שֶׁשְּׁכִינָה כָּאן. יָשְׁבוּ. אָמַר רַבִּי שִׁמְעוֹן, בַּמָּה עֲסַקְתֶּם? אָמַר רַבִּי אַבָּא, בְּאַהֲבַת כְּנֶסֶת יִשְׂרָאֵל לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְרַבִּי אֶלְעָזָר פֵּרַשׁ פָּסוּק זֶה בִּכְנֶסֶת יִשְׂרָאֵל, שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ וְגוֹ'. אָמַר לוֹ, אֶלְעָזָר, בְּאַהֲבָה עֶלְיוֹנָה וְקֶשֶׁר הַחֲבִיבוּת הִסְתַּכַּלְתָּ.</p>\n<p>שָׁתַק רַבִּי שִׁמְעוֹן שָׁעָה. אָמַר, בְּכָל מָקוֹם צָרִיךְ שְׁתִיקָה, חוּץ מִשְּׁתִיקָה שֶׁל הַתּוֹרָה. גְּנִיזָה אַחַת יֵשׁ לִי גְּנוּזָה, וְאֵינִי רוֹצֶה שֶׁתֹּאבַד מִכֶּם, וְהִיא דָּבָר עֶלְיוֹן, וּמָצָאתִי אוֹתוֹ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא הַזָּקֵן.</p>\n<p>בֹּא רְאֵה, בְּכָל מָקוֹם הַזָּכָר רוֹדֵף אַחַר הַנְּקֵבָה וּמְעוֹרֵר אֵלֶיהָ אַהֲבָה, וְכָאן מָצָאנוּ שֶׁהִיא מְעוֹרֶרֶת אַהֲבָה וְרוֹדֶפֶת אַחֲרָיו, וְדֶרֶךְ הָעוֹלָם שֶׁאֵין שֶׁבַח הַנְּקֵבָה לִרְדּף אַחֲרֵי הַזָּכָר, אֶלָּא דָּבָר נִסְתָּר הוּא, וְדָבָר עֶלְיוֹן מִבֵּית גִּנְזֵי הַמֶּלֶךְ.</p>"],[9522011494,"<p>בֹּא רְאֵה, שָׁלֹשׁ נְשָׁמוֹת הֵן, וְהֵן עוֹלוֹת בִּדְרָגוֹת עֶלְיוֹנוֹת יְדוּעוֹת, וְעַל שֶׁהֵן שָׁלֹשׁ - הֵן אַרְבַּע. אַחַת נְשָׁמָה עֶלְיוֹנָה שֶׁלֹּא נִתְפֶּסֶת וְלֹא מִתְעוֹרֵר בָּהּ הַגִּזְבָּר (הגזע) שֶׁל הָאוֹצָר הָעֶלְיוֹן, כָּל שֶׁכֵּן הַתַּחְתּוֹן. וְזוֹ נְשָׁמָה לְכָל הַנְּשָׁמוֹת, וְהִיא נִסְתֶּרֶת וְלֹא נִגְלֵית לְעוֹלָמִים וְלֹא נוֹדַעַת, וְכֻלָּם בָּהּ תְּלוּיוֹת.</p>\n<p>וְזוֹ מִתְעַטֶּפֶת בְּעִטּוּף שֶׁל זֹהַר הַכַּרְמֶל (של הבדולח) בְּתוֹךְ הַזֹּהַר, וְנוֹטֵף טִפּוֹת טִפּוֹת מַרְגָּלִיּוֹת, וְנִקְשָׁרִים כֻּלָּם כְּאֶחָד, כְּמוֹ הַקְּשָׁרִים שֶׁל אֵיבְרֵי גּוּף אֶחָד, וְהוּא נִכְנָס לְתוֹכָם וּמַרְאֶה בָהֶם מַעֲשָׂיו. הוּא וְהֵם אֶחָד הֵם, וְאֵין בָּהֶם הַפְרָדָה. זוֹ נְשָׁמָה עֶלְיוֹנָה טְמִירָה שֶׁל הַכֹּל.</p>\n<p>נְשָׁמָה אַחֶרֶת נְקֵבָה נִסְתֶּרֶת בְּתוֹךְ חֵילוֹתֶיהָ, וְהִיא נְשָׁמָה לָהֶם, וּמֵהֶם אָחוּז הַגּוּף לְהַרְאוֹת בָּהֶם מַעֲשֶׂיהָ לְכָל הָעוֹלָם, כְּמוֹ גוּף שֶׁהוּא כְּלִי לַנְּשָׁמָה לַעֲשׂוֹת בּוֹ מַעֲשֶׂה, וְאֵלֶּה כְּמוֹ אוֹתָם הַקְּשָׁרִים הַטְּמִירִים שֶׁלְּמַעְלָה.</p>\n<p>נְשָׁמָה אַחֶרֶת הִיא נִשְׁמַת הַצַּדִּיקִים לְמַטָּה. נִשְׁמוֹת הַצַּדִּיקִים בָּאוֹת מֵאוֹתָן נְשָׁמוֹת עֶלְיוֹנוֹת, מִנִּשְׁמַת הַנְּקֵבָה וּמִנִּשְׁמַת הַזָּכָר, וְלָכֵן נִשְׁמוֹת הַצַּדִּיקִים הֵן עֶלְיוֹנוֹת עַל כָּל אוֹתָם הַחֲיָלוֹת וְהַמַּחֲנוֹת שֶׁלְּמַעְלָה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי הֵם עֶלְיוֹנִים מִשְּׁנֵי צְדָדִים, לָמָּה יָרְדוּ לָעוֹלָם הַזֶּה וְלָמָּה הִסְתַּלְּקוּ מִמֶּנּוּ? לְמֶלֶךְ שֶׁנּוֹלַד לוֹ בֵּן, שָׁלַח אוֹתוֹ לִכְפָר אֶחָד לְגַדְּלוֹ, וּלְגַדֵּל אוֹתוֹ עַד שֶׁיִּגְדַּל (לו), וִילַמְּדוּ אוֹתוֹ דַּרְכֵי הֵיכַל הַמֶּלֶךְ. שָׁמַע הַמֶּלֶךְ שֶׁהֲרֵי בְּנוֹ גָּדַל וְהִתְגַּדֵּל, מֶה עָשָׂה בְּאַהֲבַת בְּנוֹ? שׁוֹלֵחַ לוֹ אֶת הַגְּבִירָה אִמּוֹ בִּשְׁבִילוֹ, וּמַכְנִיסוֹ לְהֵיכָלוֹ, וְשָׂמֵחַ עִמּוֹ כָּל הַיּוֹם.</p>\n<p>כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלִיד בֵּן מֵהַגְּבִירָה, וּמִיהוּ? זוֹ נְשָׁמָה עֶלְיוֹנָה קְדוֹשָׁה. שָׁלַח אוֹתָהּ לִכְפָר, לָעוֹלָם הַזֶּה, שֶׁתִּתְגַּדֵּל בּוֹ וִילַמְּדוּ אוֹתָהּ דַּרְכֵי הֵיכַל הַמֶּלֶךְ. כֵּיוָן שֶׁיּוֹדֵעַ הַמֶּלֶךְ שֶׁהֲרֵי בְּנוֹ גָּדַל בַּכְּפָר הַזֶּה וּזְמַן הִגִּיעַ לַהֲבִיאוֹ לְהֵיכָלוֹ, מֶה עָשָׂה בְּאַהֲבַת בְּנוֹ? שׁוֹלֵחַ אֶת הַגְּבִירָה בִּשְׁבִילוֹ וּמַכְנִיס אוֹתוֹ לְהֵיכָלוֹ. הַנְּשָׁמָה לֹא עוֹלָה מִן הָעוֹלָם הַזֶּה עַד שֶׁבָּאָה הַגְּבִירָה בִּשְׁבִילָהּ, וּמַכְנִיסָה אוֹתָהּ לְהֵיכַל הַמֶּלֶךְ, וְיוֹשֶׁבֶת שָׁם לְעוֹלָמִים.</p>\n<p>וְעִם כָּל זֶה, דֶּרֶךְ הָעוֹלָם שֶׁאוֹתָם בְּנֵי הַכְּפָר בּוֹכִים עַל פְּרֵדַת בֶּן הַמֶּלֶךְ מֵהֶם. פִּקֵּחַ אֶחָד הָיָה שָׁם, אָמַר לָהֶם, עַל מָה אַתֶּם בּוֹכִים, וְכִי לֹא בֶּן הַמֶּלֶךְ הוּא, וְלֹא נִרְאֶה יוֹתֵר לָדוּר בֵּינֵיכֶם אֶלָּא בַּהֵיכָל שֶׁל אָבִיו? כָּךְ מֹשֶׁה, שֶׁהָיָה פִּקֵּחַ, רָאָה בְּנֵי כְפָר שֶׁהָיוּ בוֹכִים, וְעַל זֶה אָמַר (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם לֹא תִתְגֹּדֲדוּ.</p>\n<p>בֹּא רְאֵה, אִלּוּ הָיוּ יוֹדְעִים אֶת זֶה כָּל הַצַּדִּיקִים, הָיוּ שְׂמֵחִים אוֹתוֹ יוֹם שֶׁמַּגִּיעַ לָהֶם לְהִסְתַּלֵּק מִן הָעוֹלָם, וְכִי לֹא כָּבוֹד עֶלְיוֹן הוּא שֶׁהַגְּבִירָה בָּאָה בִּשְׁבִילָם, וּלְהוֹבִיל אוֹתָם לְהֵיכַל הַמֶּלֶךְ שֶׁיִּשְׂמַח בָּהֶם הַמֶּלֶךְ כָּל יוֹם? שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִשְׁתַּעֲשֵׁעַ אֶלָּא בְּנִשְׁמוֹת הַצַּדִּיקִים.</p>\n<p>בֹּא רְאֵה, הִתְעוֹרְרוּת הָאַהֲבָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל לַקָּדוֹשׁ-בָּרוּךְ-הוּא, נִשְׁמוֹת הַצַּדִּיקִים לְמַטָּה מְעוֹרְרִים אוֹתָהּ, מִשּׁוּם שֶׁהֵם בָּאִים מִצַּד הַמֶּלֶךְ, מִצַּד הַזָּכָר, וְהִתְעוֹרְרוּת זוֹ מַגִּיעָה לַנְּקֵבָה מִצַּד שֶׁל הַזָּכָר, וּמִתְעוֹרֶרֶת אַהֲבָה. נִמְצָא שֶׁזָּכָר מְעוֹרֵר חֲבִיבוּת וְאַהֲבָה לַנְּקֵבָה, וְאָז הַנְּקֵבָה נִקְשֶׁרֶת בְּאַהֲבָה לַזָּכָר.</p>\n<p>כְּמוֹ זֶה תְּשׁוּקַת הַנְּקֵבָה לִשְׁפֹּךְ מַיִם תַּחְתּוֹנִים כְּנֶגֶד מַיִם עֶלְיוֹנִים אֵינָהּ אֶלָּא בְּנִשְׁמוֹת הַצַּדִּיקִים. אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁעֲלֵיהֶם קַיָּמִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְעַל זֶה (משלי ח) וְצַדִּיק יְסוֹד עוֹלָם, כָּתוּב סְתָם.</p>\n<p>וְסוֹד הַכֹּל - צַדִּיק, הוּא יְסוֹד שֶׁלְּמַעְלָה, וְהוּא יְסוֹד לְמַטָּה, וּכְנֶסֶת יִשְׂרָאֵל נִכְלֶלֶת מִצַּדִּיק מִלְּמַעְלָה וּמִמַּטָּה. צַדִּיק מִצַּד זֶה וְצַדִּיק מִצַּד זֶה יוֹרְשִׁים אוֹתָהּ. זֶהוּ שֶׁכָּתוּב (תהלים לז) צַדִּיקִים יִירְשׁוּ אָרֶץ, יִירְשׁוּ אָרֶץ וַדַּאי. בֹּא רְאֵה, צַדִּיק יוֹרֵשׁ אֶרֶץ זוֹ וּמוֹרִיק עָלֶיהָ בְּרָכוֹת בְּכָל יוֹם, וְנוֹתֵן לָהּ תַּפְנוּקִים וְעִדּוּנִים בְּשֶׁפַע עֶלְיוֹן שֶׁשּׁוֹפֵעַ עָלֶיהָ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדָּבָר.</p>\n<p>וְסוֹד הַכָּתוּב - (בראשית מט) מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. וְעִם כָּל זֶה דָּבָר אַחֵר, שֶׁכָּתוּב (שיר ו) רָאוּהָ בָּנוֹת וַיְאַשְּׁרוּהָ, וְעַל זֶה אָמְרָה לֵאָה, (בראשית ל) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, וְהַכֹּל יָפֶה. וּבֹא רְאֵה, מִן הָעוֹלָם הַבָּא נִמְשָׁךְ וְשׁוֹפֵעַ לָצַּדִּיק הַזֶּה לָתֵת תַּפְנוּקִים וְעִדּוּנִים לָאָרֶץ הַזּוֹ, שֶׁהִיא לֶחֶם עֹנִי, וְנַעֲשֶׂה לֶחֶם מְעֻנָּג. זֶהוּ שֶׁכָּתוּב מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ וְהוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ, וַדַּאי, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, זֶהוּ מָקוֹם שֶׁהַכֹּל מְאַשְּׁרִים אוֹתוֹ, וּמִיהוּ? הָעוֹלָם הַבָּא, שֶׁהָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מְאַשְּׁרִים אוֹתוֹ וּמִשְׁתּוֹקְקִים אֵלָיו. שְׁמֵנָה לַחְמוֹ, מִי? עַד כָּאן לֹא פֵרַשׁ מִי הוּא הַמָּקוֹם. אֶלָּא, יֵשׁ לֶחֶם וְיֵשׁ לֶחֶם, כְּמוֹ שֶׁיֵּשׁ אִילָן וְיֵשׁ אִילָן. יֵשׁ עֵץ הַחַיִּים, וְיֵשׁ עֵץ שֶׁתָּלוּי בּוֹ הַמָּוֶת. יֵשׁ לֶחֶם שֶׁנִּקְרָא לֶחֶם עֹנִי, וְיֵשׁ לֶחֶם שֶׁנִּקְרָא לֶחֶם מְעֻנָּג. וּמִיהוּ (לחם)? זֶה ו', וְזֶה הוּא לַחְמ\"וֹ, לֶחֶ\"ם ו', וְעַל זֶה כָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, מִן הַשָּׁמַיִם וַדַּאי.</p>\n<p>וְעַל זֶה, מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ, לֶחֶם ו', שֶׁהֲרֵי מִמֶּנּוּ נִזּוֹן הָעֵץ הַזֶּה, וְהוּא מְעַטֵּר אוֹתוֹ, כַּכָּתוּב (שיר ג) בָּעֲטָרָה שֶׁעִטְּרָה לוֹ אִמּוֹ. וּכְשֶׁהוּא לוֹקֵחַ, וַדַּאי הוּא יִתֵּן מַעֲדַנֵּי מֶלֶךְ. וּמִי הַמֶּלֶךְ? זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֲרֵי מִמֶּנּוּ נִזּוֹנֵית, וְהוּא נוֹתֵן לָהּ עַל יַד הַצַּדִּיק דַּרְגָּה קְדוֹשָׁה אוֹת הַבְּרִית, וּמִכָּאן לִשְׁאָר הַדְּרָגוֹת שֶׁלְּמַטָּה, וְכֻלָּם כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא הַזָּקֵן אָמַר כָּךְ: מֵאָשֵׁר שְׁמֵנָה לַחְמוֹ - זֶה לֶחֶם שַׁבָּת, שֶׁהוּא מְעֻנָּג, עַל אֶחָד שְׁנַיִם, כַּכָּתוּב לָקְטוּ לֶחֶם מִשְׁנֶה. מַה זֶּה לֶחֶם מִשְׁנֶה? אֶלָּא שְׁנֵי לֶחֶם, לֶחֶם מִן הַשָּׁמַיִם וְלֶחֶם מִן הָאָרֶץ. זֶהוּ לֶחֶם עֹנֶג, וְזֶהוּ לֶחֶם עֹנִי. וּבְשַׁבָּת נִכְלָל לֶחֶם הַתַּחְתּוֹן בַּלֶּחֶם הָעֶלְיוֹן, וּמִתְבָּרֵךְ זֶה מִשּׁוּם זֶה, וְהוּא לֶחֶם מִשְׁנֶה.</p>\n<p>וְעוֹד הָיָה אוֹמֵר, לֶחֶם מִשְׁנֶה שֶׁל שַׁבָּת לוֹקֵחַ מִשַּׁבָּת הָעֶלְיוֹנָה שֶׁשּׁוֹפַעַת וּמְאִירָה לַכֹּל, וּמִתְחַבֵּר לֶחֶם בְּלֶחֶם, וְהוּא מִשְׁנֶה. וּבְכָל מָקוֹם סוֹד שֶׁל לֶחֶם נְקֵבָה הִיא, מִשּׁוּם כָּךְ שְׁמֵנָה כָּתוּב וְלֹא שָׁמֵן, וְכָתוּב (בראשית לט) כִּי אִם הַלֶּחֶם אֲשֶׁר הוּא אוֹכֵל, זוֹ אִשְׁתּוֹ.</p>\n<p>וְאִם תֹּאמַר, (שמואל א ט) וְהַלֶּחֶם אָזַל מִכֵּלֵינוּ, וְלֹא כָתוּב אָזְלָה? לִשְׁאָר הַמָּזוֹן קוֹרְאִים לֶחֶם, וְהַדְּבָרִים יְדוּעִים מַה הוּא שְׁאָר הַמָּזוֹן וּמַה הוּא לֶחֶם מַמָּשׁ. לֶחֶם שֶׁלְּמַעְלָה בְּכָל מָקוֹם זָכָר, לֶחֶם תַּחְתּוֹן בְּכָל מָקוֹם נְקֵבָה. וְאָנוּ מָצָאנוּ שֶׁלִּפְעָמִים כָּתוּב זָכָר וְלִפְעָמִים נְקֵבָה, וְהַכֹּל דָּבָר אֶחָד, זֶהוּ כְּמוֹ זֶה, וְהַכֹּל יָפֶה.</p>\n<p>בֹּא רְאֵה, אָשֵׁר רָשׁוּם לְמַעְלָה וְרָשׁוּם לְמַטָּה בְּתִקּוּנֵי כַלָּה, וְעַל כָּל שְׁנֵים עָשָׂר הַשְּׁבָטִים הַיָּם עוֹמֵד עֲלֵיהֶם וְנִתְקָן בָּהֶם. זֶהוּ שֶׁכָּתוּב (מלכים א ז) וְהַיָּם עֲלֵיהֶם מִלְמָעְלָה. וְסוֹד הַדָּבָר - נִתְקָן לְמַעְלָה וְנִתְקָן לְמַטָּה בָּאָרֶץ. נִתְקָן לְמַעְלָה בְּתִקּוּנִים יְדוּעִים כְּמוֹ שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְנִתְקָן לְמַטָּה בִּשְׁנֵים עָשָׂר הַשְּׁבָטִים הַלָּלוּ כְּמוֹ שֶׁלְּמַעְלָה, וְעַל כָּךְ שְׁכִינָה לְמַעְלָה וּשְׁכִינָה לְמַטָּה בִּשְׁבִיל (בתוכם של) יִשְׂרָאֵל, וּבִשְׁנֵים עָשָׂר שְׁבָטִים (ובשני שבטים) (ובשני צדדים) נִכְלֶלֶת וְנִתְקֶנֶת. אָשֵׁר בְּתִקּוּנֶיהָ עוֹמֵד כִּשְׁאָר הַשְּׁבָטִים.</p>\n<p>וְאִם לֹא שֶׁגִּלָּה מֹשֶׁה - לֹא נוֹדַע, שֶׁכָּתוּב (דברים לג) וְטֹבֵל בַּשֶּׁמֶן רַגְלוֹ, לְהַרְאוֹת אֵיפֹה הַקֶּשֶׁר שֶׁלּוֹ בִּמְקוֹמוֹ, שֶׁהוּא מַשְׁפִּיעַ אוֹתוֹ שֶׁמֶן מִשְׁחָה מִלְמַעְלָה. מִשּׁוּם כָּךְ כָּתוּב בָּרוּךְ מִבָּנִים אָשֵׁר וְגוֹ'.</p>"],[9522011495,"<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, נַפְתָּלִי אַיָּלָה שְׁלֻחָה הַנֹּתֵן אִמְרֵי שָׁפֶר. הֲרֵי נֶאֱמַר שֶׁהָעוֹלָם הָעֶלְיוֹן הוּא עוֹלָם שֶׁל זָכָר. כֵּיוָן שֶׁעוֹלֶה דָבָר מִכְּנֶסֶת יִשְׂרָאֵל וָמַעְלָה, הַכֹּל הוּא זָכָר. מִנַּיִן לָנוּ? מֵעוֹלָה. לָמָּה נִקְרֵאת עוֹלָה? מִשּׁוּם שֶׁעוֹלָה מֵעַל הַנְּקֵבָה, וּמִשּׁוּם כָּךְ (ויקרא א) עֹלָה זָכָר תָּמִים יַקְרִיבֶנּוּ וְגוֹ'.</p>\n<p>לָמָּה תָּמִים? וְכִי חֲתִיכוֹת חֲתִיכוֹת צָרִיךְ אוֹתוֹ שֶׁאוֹמֵר תָּמִים!? מַה זֶּה תָּמִים? אֶלָּא כַּכָּתוּב, הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. מָתַי תָּמִים? בְּשָׁעָה (במקום) שֶׁנִּמּוֹל, שֶׁהֲרֵי הַזָּכָר אֵינוֹ, וְלֹא נוֹדָע אֶלָּא רַק בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא תָמִים, וּמַהוּ? זוֹ אוֹת הַבְּרִית, שֶׁבָּהּ נוֹדָע הַזָּכָר מִן הַנְּקֵבָה, כַּכָּתוּב (שם י) אִישׁ צַדִּיק תָּמִים הָיָה. מִשּׁוּם כָּךְ זָכָר תָּמִים, שֶׁנּוֹדָע בּוֹ אֵיבָר זֶה וְלֹא יְסָרְסוּ אוֹתוֹ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (ויקרא ד) נְקֵבָה תְמִימָה? כָּךְ הוּא וַדַּאי. כְּמוֹ שֶׁנִּקְרָא צַדִּיק תָּמִים, כָּךְ נִקְרָא צֶדֶק תְּמִימָה, מִשּׁוּם שֶׁהַכֹּל נָטְלָה מִמֶּנּוּ. מִשּׁוּם כָּךְ עוֹלָה, שֶׁעוֹלָה מִן הַנְּקֵבָה לַזָּכָר, וּמִמָּקוֹם זֶה וָמַעְלָה הַכֹּל הוּא זָכָר, וּמִן הַנְּקֵבָה וָמַטָּה הַכֹּל הוּא נְקֵבָה, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>וְאִם תֹּאמַר, כָּךְ גַּם הַנְּקֵבָה שֶׁלְּמַעְלָה. אֶלָּא סִיּוּם הַגּוּף מַרְאֶה עַל כָּל הַגּוּף שֶׁהוּא זָכָר, רֹאשׁ הַגּוּף נְקֵבָה, עַד שֶׁיּוֹרֵד לַסִּיּוּם, וּכְשֶׁהַסִּיּוּם נִרְאֶה, הֲרֵי עוֹשֶׂה הַכֹּל זָכָר. אֲבָל כָּאן רֹאשׁ וָסוֹף נְקֵבָה, שֶׁהֲרֵי כָּל תִּקּוּן הַגּוּף נְקֵבָה.</p>\n<p>בֹּא רְאֵה, סוֹד עֶלְיוֹן אֶחָד יֵשׁ בְּדָבָר זֶה, שֶׁהֲרֵי רָאִינוּ שֶׁיַּעֲקֹב בֵּרַךְ אֶת יוֹסֵף בְּתוֹךְ אֶחָיו. כֵּיוָן שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אַרְבָּעָה דְגָלִים בַּשְּׁכִינָה, בִּשְׁנֵים עָשָׂר שְׁבָטִים לְהִתַּקֵּן בָּהֶם, גָּרַע מֵהֶם אֶת יוֹסֵף, וְשָׂם בִּמְקוֹמוֹ אֶת אֶפְרַיִם. מָה הַטַּעַם הִסְתַּלֵּק מֵהֶם יוֹסֵף? אִם תֹּאמַר מִשּׁוּם חֶטְאוֹ - לֹא כָּךְ, שֶׁהֲרֵי הוּא צַדִּיק.</p>\n<p>אֶלָּא סוֹד הַדָּבָר - יוֹסֵף הָיָה רֹשֶׁם שֶׁל זָכָר, שֶׁכָּתוּב בֵּן פֹּרָת יוֹסֵף בֵּן פֹּרָת עֲלֵי עָיִן, וְכָתוּב מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל, מִשָּׁם נִזּוֹנֵית אֶבֶן יִשְׂרָאֵל הַ את. אֶבֶן - זוֹ כְּנֶסֶת יִשְׂרָאֵל, וְעָלֶיהָ אָמַר דָּוִד (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וּמִשּׁוּם שֶׁיּוֹסֵף הוּא רֹשֶׁם שֶׁל זָכָר, נִקְרָא יוֹסֵף הַצַּדִּיק, שֶׁהֲרֵי הוּא וַדַּאי צַדִּיק, מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל.</p>\n<p>וּמִשּׁוּם שֶׁכָּל תִּקּוּנֵי הַשְּׁכִינָה הֵן נְקֵבוֹת, הִסְתַּלֵּק יוֹסֵף מִשָּׁם וְהִתְמַנָּה תַּחְתָּיו אֶפְרַיִם, וְהוּא נְקֵבָה לְתִקּוּנֶיהָ. וּמִשּׁוּם שֶׁהוּא כָּךְ, הִתְמַנָּה לְצַד מַעֲרָב, מָקוֹם שֶׁשּׁוֹרָה הַנְּקֵבָה, וְאוֹתוֹ רֹשֶׁם שֶׁהוּא זָכָר הִסְתַּלֵּק מִתִּקּוּנֶיהָ, מִשּׁוּם שֶׁהוּא עוֹלָם שֶׁל נְקֵבָה וְלֹא עוֹלָם שֶׁל זָכָר, וְכָל תִּקּוּנֶיהָ דּוֹרְשִׁים נְקֵבוֹת.</p>\n<p>וּמִשּׁוּם כָּךְ, יוֹסֵף שֶׁהוּא צַדִּיק, הִסְתַּלֵּק מִתִּקּוּנֶיהָ, וְהִתְמַנָּה אֶפְרַיִם תַּחְתָּיו. וְעַל כֵּן כָּל שְׁנֵים עָשָׂר הַשְּׁבָטִים הֵם תִּקּוּנִים שֶׁל שְׁכִינָה, וְכֻלָּם צְרִיכִים כְּמוֹ שֶׁלְּמַעְלָה, חוּץ מִדַּרְגַּת הַצַּדִּיק שֶׁהוּא עוֹשֶׂה כָּל הָאֵיבָרִים זָכָר, וְלֹא צָרִיךְ לְהַכְחִישׁ (אותו).</p>\n<p>נַפְתָּלִי אַיָּלָה שְׁלֻחָה הַנֹּתֵן אִמְרֵי שָׁפֶר, הַיְנוּ מַה שֶּׁכָּתוּב (שיר ד) וּמִדְבָּרֵךְ נָאוֶה. מִשּׁוּם שֶׁקּוֹל מַנְהִיג אֶת הַדִּבּוּר, וְאֵין קוֹל בְּלִי דִבּוּר. וְאוֹתוֹ הַקּוֹל נִשְׁלָח מִמָּקוֹם עָמֹק שֶׁלְּמַעְלָה, וְשָׁלוּחַ מִלְּפָנָיו לְהַנְהִיג הַדִּבּוּר, שֶׁאֵין קוֹל בְּלִי דִבּוּר, וְלֹא דִבּוּר בְּלִי קוֹל. וְזֶה כְּלָל שֶׁצָּרִיךְ אֶת הַפְּרָט, וּפְרָט שֶׁצָּרִיךְ אֶת הַכְּלָל, וְזֶה קוֹל שֶׁיּוֹצֵא מִדָּרוֹם וּמַנְהִיג אֶת הַמַּעֲרָב, יוֹרֵשׁ לִשְׁנֵי צְדָדִים. וְזֶהוּ שֶׁכָּתוּב (דברים לג) וּלְנַפְתָּלִי אָמַר וְגוֹ', יָם וְדָרוֹם יְרָשָׁה. לְמַעְלָה זָכָר, לְמַטָּה נְקֵבָה. מִשּׁוּם כָּךְ נַפְתָּלִי אַיָּלָה שְׁלֻחָה, נְקֵבָה לְמַטָּה. כְּמוֹ זֶה זָכָר לְמַעְלָה, שֶׁכָּתוּב הַנֹּתֵן אִמְרֵי שָׁפֶר. הַנֹּתֵן כָּתוּב, וְלֹא הַנּוֹתֶנֶת.</p>"],[9522011496,"<p>בֹּא רְאֵה, מַחֲשָׁבָה רֵאשִׁית הַכֹּל, וּמִשּׁוּם שֶׁהִיא מַחֲשָׁבָה, הִיא בִּפְנִים נִסְתֶּרֶת וְלֹא נוֹדַעַת, כַּאֲשֶׁר מִתְפַּשֶּׁטֶת מַחֲשָׁבָה זוֹ יוֹתֵר, בָּאָה לְמָקוֹם שֶׁשּׁוֹרָה הָרוּחַ, וּכְשֶׁמַּגִּיעָה לְאוֹתוֹ מָקוֹם נִקְרֵאת בִּינָ\"ה, וְזֶה לֹא נִסְתָּר כְּבַתְּחִלָּה. וְאַף עַל גַּב שֶׁהוּא נִסְתָּר, רוּחַ זוֹ מִתְפַּשֶּׁטֶת וּמוֹצִיאָה קוֹל כָּלוּל מֵאֵשׁ מַיִם וְרוּחַ, שֶׁהֵם צָפוֹן דָּרוֹם וּמִזְרָח. וְהַקּוֹל הַזֶּה כְּלָל שֶׁל כָּל שְׁאָר הַחֲיָלוֹת, וְקוֹל זֶה מַנְהִיג אֶת הַדִּבּוּר, וְזֶה נוֹתֵן דָּבָר מְתֻקָּן, מִשּׁוּם שֶׁקּוֹל נִשְׁלַח מִמְּקוֹם הָרוּחַ, וּבָא לְהַנְהִיג הַדִּבּוּר, לְהוֹצִיא דְבָרִים יְשָׁרִים.</p>\n<p>וּכְשֶׁתִּסְתַּכֵּל בַּדְּרָגוֹת, הוּא מַחֲשָׁבָה, הוּא בִּינָה, הוּא קוֹל, הוּא דִּבּוּר, וְהַכֹּל אֶחָד. וְהִיא הִיא הַמַּחֲשָׁבָה, רֵאשִׁית הַכֹּל, וְלֹא הָיָה פֵּרוּד, אֶלָּא הַכֹּל אֶחָד וְקֶשֶׁר אֶחָד, שֶׁהִיא מַחֲשָׁבָה מַמָּשׁ שֶׁנִּקְשְׁרָה בְּאַיִן וְלֹא נִפְרָד לְעוֹלָמִים, וְזֶה הוּא (זכריה יד) ה' אֶחָד וּשְׁמוֹ אֶחָד. וְעַל זֶה הַנֹּתֵן אִמְרֵי שָׁפֶר כָּתוּב, זֶה הַגּוּף.</p>"],[9522011497,"<p>סִיּוּם הַגּוּף, זֶה שֶׁכָּתוּב בֵּן פֹּרָת יוֹסֵף בֵּן פֹּרָת עֲלֵי עָיִן. לָמָּה פַּעֲמַיִם? אֶלָּא בֵּן פֹּרָת לְמַעְלָה, בֵּן פֹּרָת לְמַטָּה. וְלָמָּה אֵינוֹ בֵּן פֹּרָת לְמַטָּה בְּתִקּוּנֵי הַמַּלְכָּה? מִשּׁוּם שֶׁבָּנוֹת צָעֲדָה לִהְיוֹת עֲלֵי שׁוּר, שֶׁצְּרִיכִים בָּנוֹת לְתִקּוּנֶיהָ וְלֹא בָנִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְגוֹ'. רַבּוֹת בָּנוֹת עָשׂוּ חָיִל, אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים.</p>\n<p>בֹּא רְאֵה, מַלְכוּת הַקְּדוֹשָׁה לֹא מְקַבֶּלֶת מַלְכוּת קְדוֹשָׁה שְׁלֵמָה עַד שֶׁמִּתְחַבֶּרֶת בָּאָבוֹת, וּכְשֶׁמִּתְחַבֶּרֶת בָּאָבוֹת, נִבְנֶה בִּנְיָן שָׁלֵם מֵהָעוֹלָם הָעֶלְיוֹן, שֶׁהוּא עוֹלַם הַזָּכָר, וְעוֹלָם הָעֶלְיוֹן נִקְרָא שֶׁבַע שָׁנִים, כִּי כָל שֶׁבַע הַשָּׁנִים בּוֹ.</p>\n<p>וְסִימָן לַדָּבָר - (מלכים א ו) וַיִּבְנֵהוּ שֶׁבַע שָׁנִים, זֶה עוֹלָם הָעֶלְיוֹן, וְלֹא כָתוּב בְּשֶׁבַע שָׁנִים, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְלֹא כָתוּב בְּשֵׁשֶׁת, וְכָתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּאַבְרָהָם. וְאַבְרָהָם נִקְרָא שִׁבְעָה יָמִים, וּבוֹ נִבְנָה הָעוֹלָם הָעֶלְיוֹן (כמו זה ויבנהו שבע שנים), וְאֵלֶּה נִקְרָאִים עוֹלַם הַזָּכָר (ובו נבנה העולם שלמטה).</p>\n<p>כְּמוֹ זֶה לְמַטָּה יֵשׁ שֶׁבַע שָׁנִים, סוֹד הָעוֹלָם הַתַּחְתּוֹן, וְסוֹד זֶה שֶׁכָּתוּב (מלכים א ח) שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים אַרְבָּעָה עָשָׂר יוֹם. שֶׁכֵּיוָן שֶׁאָמַר שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים, לֹא יָדַעְנוּ שֶׁהֵם אַרְבָּעָה עָשָׂר? אֶלָּא לְהַרְאוֹת עוֹלָם עֶלְיוֹן וְעוֹלָם תַּחְתּוֹן, וְהֵם שִׁבְעַת יָמִים וְשִׁבְעַת יָמִים. אֵלּוּ זְכָרִים וְאֵלּוּ נְקֵבוֹת. אֵלּוּ הַנְּקֵבוֹת הָעוֹלָם הַזֶּה עֲלֵיהֶם, שֶׁכָּתוּב (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל, אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים שֶׁהֵם עָשׂוּ חַיִל, כַּכָּתוּב (במדבר ב) כָּל הַפְּקוּדִים לְמַחֲנֵה יְהוּדָה וְגוֹ', וְכֵן כֻּלָּם.</p>\n<p>וְאִם תֹּאמַר רַבּוֹת, וַהֲרֵי הֵם שְׁנֵים עָשָׂר וְלֹא יוֹתֵר, חוּץ מֵאוֹתוֹ הַחַיִל שֶׁעָשׂוּ, מַה זֶּה רַבּוֹת? אֶלָּא כְּמוֹ שֶׁכָּתוּב (בראשית יח) זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, כְּמוֹ גָדְלָה. וְכֵן רַבּוֹת גְּדוֹלוֹת, עֶלְיוֹנִים וּגְדוֹלִים עַל הַכֹּל, וְאֵלּוּ נִקְרָאִים (תהלים קד) חַיּוֹת גְּדלוֹת. עָשׂוּ חָיִל - אוֹתוֹ חַיִל שֶׁעָשׂוּ שֶׁסְּמוּכִים עֲלֵיהֶם נִקְרָאִים חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת, לְהִתְחַבֵּר כְּאֶחָד, לְתַקֵּן בָּהֶם אֶת הַמַּלְכָּה, לְשַׂמֵּחַ בָּהֶם עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (שם) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. מִשּׁוּם כָּךְ רַבּוֹת בָּנוֹת עָשׂוּ חָיִל. (ואת עלית על כלנה, כמו שנאמר (מלכים א ז) עמד על שני עשר בקר שלשה פנים צפונה ושלשה וגו', וכתוב והים עליהם מלמעלה, הינו ואת עלית על כלנה,)</p>\n<p>וְעַל זֶה בָּנוֹת צָעֲדָה עֲלֵי שׁוּר. בָּנוֹת צָעֲדָה!? צוֹעֲדוֹת הָיָה צָרִיךְ לִכְתֹּב! אֶלָּא אוֹתָהּ הָעַיִן שֶׁכְּתוּבָה לְמַעְלָה, וּמִיהוּ? עֵין מִשְׁפָּט, וְהוּא עוֹמֵד עֲלֵי עַיִן, וְהוּא עַיִן, צָעֲדָה וּפוֹסַעַת לָקַחַת בָּנוֹת לְתִקּוּנֶיהָ, וְזֶהוּ בָּנוֹת צָעֲדָה, וְלֹא בָנִים. בָּנוֹת צָעֲדָה, הִסְתַּכְּלָה לְתִקּוּנֶיהָ, וְלֹא בָנִים. וַיְמָרֲרוּהוּ וָרֹבּוּ - בְּהִסְתַּכְּלוּת שֶׁל אַהֲבָה אֵלָיו, כַּכָּתוּב (שיר ו) הָסֵבִּי עֵינַיִךְ מִנֶּגְדִּי שֶׁהֵם הִרְהִיבֻנִי. וְעַל זֶה וַיִּשְׂטְמֻהוּ בַּעֲלֵי חִצִּים.</p>\n<p>וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ, זוֹ קֶשֶׁת. מַה זֶּה קֶשֶׁת? זוֹ בַּת זוּגוֹ. בְּאֵיתָן - חֹזֶק הִלְבִּישָׁה עָלָיו, שֶׁלֹּא נֶחֱלַשׁ כֹּחָהּ, שֶׁהֲרֵי יָדְעָה שֶׁיּוֹסֵף לֹא יִסְטֶה בְּאוֹתָהּ דַּרְגָּה שֶׁל אוֹת הַבְּרִית שֶׁלּוֹ לְיָמִין וְלִשְׂמֹאל.</p>\n<p>וַיָּפֹזּוּ, מַה זֶּה וַיָּפֹזּוּ? אֶלָּא כְּמוֹ שֶׁכָּתוּב (תהלים יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפַּז רָב, וְכָתוּב (איוב כח) וּתְמוּרָתָהּ כְּלִי פָז. הִתְכַּבְּדוּ זְרוֹעוֹתָיו בְּמַרְגָּלִית עֶלְיוֹנָה. מִידֵי אֲבִיר יַעֲקֹב - מֵאוֹתָם שְׁנֵי צְדָדִים שֶׁהִתְחַזֵּק בָּהֶם יַעֲקֹב. מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל - מִשָּׁם נִזּוֹנֵית אוֹתָהּ אֶבֶן יְקָרָה, כְּמוֹ שֶׁאָמַרְנוּ. עוֹד, מֵאוֹתָם שְׁנֵים עָשָׂר צְדָדִים נִזּוֹנֵית אוֹתָהּ אֶבֶן יְקָרָה, שֶׁהֵם צָפוֹן וְדָרוֹם, וְהִיא נִתְּנָה בֵינֵיהֶם וְהִתְבָּרְכָה מֵהֶם, וְנִזּוֹנָה מֵהֶם עַל (דרגה) יְדֵי צַדִּיק.</p>\n<p>בֹּא רְאֵה, לְיוֹסֵף נוֹסְפָה בְּרָכָה אַחֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר מֵאֵל אָבִיךְ וְיַעְזְרֶךָּ וְגוֹ'. פָּסוּק זֶה קָשֶׁה. מֵאֵל אָבִיךְ וְיַעְזְרֶךָּ, אֵל אָבִיךְ יַעַזְרֶךָּ צָרִיךְ לִהְיוֹת! מַה זֶּה מֵאֵל אָבִיךְ וְאַחַר כָּךְ וְיַעְזְרֶךָּ? וְאֵת שַׁדַּי, וְאֵל שַׁדַּי צָרִיךְ לִהְיוֹת, כְּמוֹ שֶׁכָּתוּב (בראשית מג) וְאֵל שַׁדַּי יִתֵּן לָהֶם רַחֲמִים לִפְנֵי הָאִישׁ. וִיבָרֲכֶךָּ, יְבָרֶכְךְ צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא הוֹרִישׁוֹ מִלְמַעְלָה וּמַטָּה. הוֹרִישׁוּ מִלְּמַעְלָה, מֵאֵל אָבִיךְ, שֶׁהוּא יְרֻשָּׁה עֶלְיוֹנָה, מָקוֹם שֶׁנִּקְרָא שָׁמַיִם. וְיַעְזְרֶךָּ, כְּדֵי שֶׁלֹּא יַחֲלִיף מָקוֹם זֶה לְמָקוֹם אַחֵר, וְשֶׁסִּיּוּעוֹ יִהְיֶה מִמָּקוֹם זֶה וְלֹא מֵאַחֵר.</p>\n<p>וְאֵת שַׁדַּי, מַה זֶּה וְאֵת שַׁדַּי? אֶלָּא זוֹ דַּרְגָּה אַחֶרֶת תַּחְתּוֹנָה, שֶׁהֲרֵי שָׁנִינוּ, בְּכָל מָקוֹם אֶת ה' - זוֹ הַשְּׁכִינָה, כְּמוֹ (ישעיה ו) וָאֵרֶא אֶת ה', אֶת לְרַבּוֹת. וְאֶת - לְהַכְלִיל יוֹם בְּלַיְלָה וְלַיְלָה בְּיוֹם, כַּכָּתוּב וְאֵת שַׁדַּ\"י, שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת בְּרָכוֹת לְבָרֵךְ אֶת הָעוֹלָמוֹת.</p>\n<p>עוֹד, לָמָּה לֹא אָמַר וְאֵל שַׁדַּי, שֶׁהֲרֵי גַּם כֵּן מַשְׁמָע כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב וְאֵל שַׁדַּי יִתֵּן לָכֶם רַחֲמִים, הַכֹּל מָקוֹם אֶחָד הוּא, לָמָּה הִשְׁאִיר ל' וְכָתַב ת'? אֶלָּא זֶהוּ סוֹד, שֶׁכְּשֶׁאוֹתָם שְׁבִילִים יוֹצְאִים מִלְמַעְלָה, כְּלָל שֶׁל הַתּוֹרָה, מוֹרִישׁ אֶת הַשָּׁמַיִם, כְּמוֹ שֶׁנֶּאֱמַר אֵת הַשָּׁמַיִם - כְּלָל שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת. וּמִכָּאן יוֹצְאִים לַתּוֹרָה שֶׁבְּעַל פֶּה שֶׁנִּקְרֵאת אֶרֶץ, כְּמוֹ שֶׁאָמַרְנוּ וְאֵת הָאָרֶץ - כְּלָל שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת. וְהַשָּׁמַיִם כּוֹלְלִים הַכֹּל כְּאֶחָד, וְאָז מִתְעַטֶּרֶת הַלְּבָנָה בַּכֹּל וְיוֹשֶׁבֶת בִּשְׁלֵמוּת, וְהַבְּרָכוֹת שׁוֹפְעוֹת אָז מִשָּׁם, וְעַל זֶה וְאֵת שַׁדַּי.</p>\n<p>וִיבָרֲכֶךָּ, כְּדֵי שֶׁיִּהְיֶה לוֹ תָּמִיד קִיּוּם וְיוֹתֵר, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁיֵּשׁ בּוֹ וָא\"ו, יֵשׁ לוֹ תּוֹסֶפֶת וְקִיּוּם. עַד כָּאן כְּלָל, וְאַחַר כָּךְ עָשָׂה פְּרָט, שֶׁכָּתוּב בִּרְכֹת שָׁמַיִם וְגוֹ'.</p>\n<p>בִּרְכֹת אָבִיךְ גָּבְרוּ עַל בִּרְכֹת הוֹרַי. וַדַּאי שֶׁבִּרְכֹת אָבִיךְ גָּבְרוּ, שֶׁהֲרֵי יַעֲקֹב הוֹרִישׁ שֶׁבַח שֶׁל הַכֹּל יוֹתֵר מֵהָאָבוֹת, שֶׁהֲרֵי הוּא הָיָה שָׁלֵם בַּכֹּל, וְהַכֹּל נָתַן לְיוֹסֵף. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ רָאוּי, שֶׁהֲרֵי צַדִּיק נוֹטֵל הַכֹּל וְיוֹרֵשׁ הַכֹּל כְּאֶחָד, וְכָל הַבְּרָכוֹת שְׁרוּיוֹת בּוֹ. הוּא מוֹרִיק בְּרָכוֹת מֵהָרֹאשׁ לְמַעְלָה, וְכָל אֵיבְרֵי הַגּוּף כֻּלָּם נִתְקְנוּ לְהוֹרִיק בּוֹ בְּרָכוֹת, וְאָז נַעֲשָׂה נָהָר שֶׁיּוֹצֵא מֵעֵדֶן.</p>\n<p>מַה זֶּה מֵעֵדֶן? אֶלָּא בְּכָל שָׁעָה שֶׁכָּל הָאֵיבָרִים יוֹשְׁבִים בְּקֶשֶׁר אֶחָד, וְהֵם בְּעִדּוּן שֶׁל הִשְׁתּוֹקְקוּת מֵהָרֹאשׁ לְמַעְלָה וּלְמַטָּה, וְכֻלָּם מֵעִדּוּן וְהִשְׁתּוֹקְקוֹת שֶׁלָּהֶם מְרִיקִים בּוֹ, וְנַעֲשָׂה נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן וַדַּאי. עוֹד מֵעֵדֶן - מֵחָכְמָה עֶלְיוֹנָה שׁוֹפֵעַ הַכֹּל לְהִמָּשֵׁךְ, וְעוֹשֶׂה נָהָר, וְנִמְשָׁךְ עַד שֶׁמַּגִּיעַ לַדַּרְגָּה הַזּוֹ, וְאָז הַכֹּל בִּבְרָכוֹת, וְהַכֹּל אֶחָד.</p>\n<p>עֵד תַּאֲוַת גִּבְעֹת עוֹלָם, (זה עד) תְּשׁוּקַת אוֹתָן גִּבְעוֹת עוֹלָם, וּמִי הֵם? שְׁתֵּי נְקֵבוֹת, אַחַת לְמַעְלָה וְאַחַת לְמַטָּה, שֶׁכָּל אַחַת נִקְרֵאת עוֹלָם. וּתְשׁוּקַת כָּל אֵיבְרֵי הַגּוּף בְּאוֹתָן שְׁתֵּי אִמָּהוֹת. תְּשׁוּקָה לִינֹק מֵהָאֵם הָעֶלְיוֹנָה (בינה), וּתְשׁוּקָה לְהִקָּשֵׁר בָּאֵם הַתַּחְתּוֹנָה, וּתְשׁוּקַת הַכֹּל אֶחָד. מִשּׁוּם כָּךְ כֻּלָּם (כראוי). תִּהְיֶיןָ לְרֹאשׁ יוֹסֵף וְגוֹ', לְהִתְבָּרֵךְ אוֹתָהּ דַּרְגָּה שֶׁל צַדִּיק וְלִטֹּל הַכֹּל כָּרָאוּי.</p>\n<p>אַשְׁרֵי אוֹתָם שֶׁנִּקְרָאִים צַדִּיקִים, שֶׁהֲרֵי צַדִּיק לֹא נִקְרָא אֶלָּא מִי שֶׁשּׁוֹמֵר דַּרְגָּה זוֹ, אוֹת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ, אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. יָצְאוּ מִן הַמְּעָרָה. אָמַר רַבִּי שִׁמְעוֹן, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר, וְנֵלֵךְ בַּדֶּרֶךְ.</p>"],[9522011498,"<p>פָּתַח רַבִּי אֶלְעָזָר פָּסוּק אַחֲרָיו, בִּנְיָמִין זְאֵב יִטְרָף וְגוֹ'. בִּנְיָמִין זְאֵב יִטְרָף, לָמָּה זְאֵב? אֶלָּא מִשּׁוּם שֶׁכָּךְ נִרְשָׁם בַּכִּסֵּא, שֶׁהֲרֵי כָּל הַחַיּוֹת, קְטַנּוֹת וּגְדוֹלוֹת, רְשׁוּמוֹת שָׁם, כַּכָּתוּב (תהלים קד) חַיּוֹת קְטַנּוֹת עִם גְּדלוֹת, וְהַכִּסֵּא שֶׁעָשָׂה שְׁלֹמֹה כָּךְ נִרְשָׁם, כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>עוֹד זְאֵב יִטְרָף, שֶׁהֲרֵי הַמִּזְבֵּחַ הָיָה בְּחֶלְקוֹ, וּמִזְבֵּחַ הוּא זְאֵב. שֶׁאִם תֹּאמַר שֶׁבִּנְיָמִין הוּא זְאֵב - לֹא כָּךְ, אֶלָּא הַמִּזְבֵּחַ שֶׁהָיָה בְּחֶלְקוֹ הוּא זְאֵב, שֶׁהָיָה אוֹכֵל בָּשָׂר כָּל יוֹם, וּבִנְיָמִין הָיָה זָן אוֹתוֹ. מִשּׁוּם שֶׁהֲרֵי הָיָה בְּחֶלְקוֹ, כִּבְיָכוֹל הוּא מְפַרְנֵס וְזָן אֶת הַזְּאֵב הַזֶּה. עוֹד זְאֵב יִטְרָף - זְאֵב יָזוּן, וּמִיהוּ? אֵלֶּה בַּעֲלֵי יְרִיבוֹת שֶׁעוֹמְדִים לְמַעְלָה לְקַטְרֵג, וְכֻלָּם נֶהֱנוּ וְנִתְקְנוּ מֵהַקָּרְבָּן, וּמְעוֹרְרִים הִתְעוֹרְרוּת שֶׁלְּמַעְלָה.</p>\n<p>בַּבֹּקֶר יֹאכַל עַד וְלָעֶרֶב יְחַלֵּק שָׁלָל. מַה זֶּה בַּבֹּקֶר יְחַלֵּק עַד אֶלָּא? בַּבּקֶר, שֶׁאַבְרָהָם מִתְעוֹרֵר בָּעוֹלָם וְנִמְצֵאת שְׁעַת רָצוֹן, הַקָּרְבָּן עוֹשֶׂה הִתְעוֹרְרוּת וְנַחַת רוּחַ וְעוֹלָה עַד עַ\"ד, אוֹתוֹ מָקוֹם שֶׁכָּתוּב (דברים ל) וְשַׁבְתָּ עַד ה' אֱלֹהֶיךְ.</p>\n<p>עוֹד בַּבֹּקֶר, מַה זֶּה בַּבּקֶר? זֶה אַבְרָהָם, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. בִּזְמַן שֶׁנִּמְצָא רָצוֹן, בְּאוֹתָהּ שָׁעָה לֹא הָיָה אוֹכֵל קָרְבָּן אַחֵר, וּמֶה הָיָה אוֹכֵל? אוֹתוֹ מָקוֹם שֶׁנִּקְרָא עַ\"ד, וְהוּא כִּסֵּא עֶלְיוֹן, שֶׁהוּא עֲדֵי עַד, כַּכָּתוּב עֲדֵי עַד וְגוֹ'.</p>\n<p>וּזְמַן אֲכִילָה בַּבֹּקֶר שֶׁל עַ\"ד הוּא, וְהָעַ\"ד הַזֶּה (כך גם כן) לְמַעְלָה (כך נקרא), שֶׁכָּתוּב (ישעיה כו) בִּטְחוּ בַּה' עֲדֵי עַד. וּבַבֹּקֶר, הַיְנוּ קָרְבָּן לַה' וַדַּאי. יֹאכַל עַד, וְלֹא אַחֵר.</p>\n<p>עוֹלֶה עָשָׁן, וְהִתְעוֹרְרוּת הָאַהֲבָה נִקְשֶׁרֶת, וּמִתְעוֹרֶרֶת לְמַעְלָה וְעוֹמְדִים זֶה כְּנֶגֶד זֶה, וְאֵשׁ (ונר) דּוֹלֶקֶת וּמְאִירָה בַּהִתְעוֹרְרוּת הַזּוֹ שֶׁלְּמַטָּה, וְכֹהֵן מִתְעוֹרֵר, וּלְוִיִּם מְשַׁבְּחִים וּמַרְאִים שִׂמְחָה, וְאָז מִתְנַסֵּךְ הַיַּיִן לְהִתְקַשֵּׁר בַּמַּיִם, וְהַיַּיִן מֵאִיר וּמַרְאֶה שִׂמְחָה. מִשּׁוּם כָּךְ, יַיִן טוֹב לְמַטָּה לְהַרְאוֹת שִׂמְחָה לְיַיִן אַחֵר שֶׁלְּמַעְלָה, וְהַכֹּל מִתְעוֹרֵר לְקֶשֶׁר שְׂמֹאל בַּיָּמִין.</p>\n<p>וְלֶחֶם שֶׁהוּא סֹלֶת, מַלְכוּת שֶׁמְּעוֹרֶרֶת הִתְעוֹרְרוּת, לוֹקְחִים אוֹתָהּ שְׂמֹאל בַּיָּמִין, וּמְקַשְּׁרִים אוֹתָהּ בְּגוּף, וְאָז שׁוֹפֵעַ שֶׁמֶן עֶלְיוֹן, וְלוֹקֶטֶת אוֹתוֹ עַל יַד הַצַּדִּי\"ק. וְעַל זֶה צָרִיךְ לַעֲשׂוֹת הִתְעוֹרְרוּת שֶׁל סֹלֶת בְּשֶׁמֶן, וְנִקְשָׁר הַכֹּל כְּאֶחָד, וְאָז עִדּוּן וְנַחַת שֶׁל יִחוּד אֶחָד, וְלוֹקְטִים עִדּוּן וְנַחַת שֶׁל הַיִּחוּד כָּל אוֹתָם כְּתָרִים, וְנִקְשָׁרִים זֶה בָּזֶה, וְהַלְּבָנָה מְאִירָה, וְנִקְשֶׁרֶת בַּשֶּׁמֶשׁ, וְיוֹשֵׁב הַכֹּל בְּעִדּוּן.</p>\n<p>וְאָז קָרְבָּן לַה', וְלֹא לְאַחֵר, וְעַל זֶה בַּבֹּקֶר יֹאכַל עַד, וְלֹא לְאַחֵר (עד). יֹאכַל עַד וְיִתְעַדֵּן וְיִתְקַשֵּׁר בְּקִשְׁרוֹ בַּתְּחִלָּה. מָתַי? בַּבֹּקֶר, שֶׁצָּרִיךְ לְהִתְבָּרֵךְ הַשֵּׁם הַקָּדוֹשׁ בַּתְּחִלָּה, וְאַחַר כָּךְ יִתְבָּרְכוּ הָאֲחֵרִים.</p>\n<p>וְעַל כָּךְ אָסוּר לוֹ לָאָדָם לְבָרֵךְ אֶת חֲבֵרוֹ בַּבֹּקֶר עַד שֶׁיְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא צָרִיךְ לְהִתְבָּרֵךְ בָּרִאשׁוֹנָה, וְהַיְנוּ בַּבֹּקֶר יֹאכַל עַד, וְאַחַר יִתְבָּרְכוּ הָאֲחֵרִים. וְלָעֶרֶב יְחַלֵּק שָׁלָל, שֶׁהֲרֵי הַקָּרְבָּנוֹת שֶׁהָיוּ בַּבּקֶר, הַכֹּל נִקְרַב לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַהִתְעוֹרְרוּת עוֹלָה לְשָׁם. וּמִשּׁוּם שֶׁהוּא הִתְבָּרֵךְ, הָיָה קוֹשֵׁר קְשָׁרִים לְכָל שְׁאָר הַחֲיָלוֹת הָעֶלְיוֹנִים, וּמְחַלֵּק לָהֶם בְּרָכוֹת לְכָל אֶחָד וְאֶחָד כָּרָאוּי, וְנָאֶה לוֹ, וְהָעוֹלָמוֹת מִתְבַּשְּׂמִים, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וְהַיְנוּ סוֹד הַכָּתוּב (שיר ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי וְגוֹ', בַּתְּחִלָּה. אַחַר כָּךְ חִלֵּק לְכֻלָּם, וְאָמַר, אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים. מוֹרִיק בְּרָכוֹת לְכֻלָּם, וּמְחַלֵּק לָהֶם לְכָל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְלָכֵן וְלָעֶרֶב יְחַלֵּק שָׁלָל, שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ יִתְבָּרֵךְ בַּתְּחִלָּה, וְכָעֵת מְחַלֵּק בְּרָכוֹת לְכָל הָעוֹלָמוֹת. שֶׁלֹּא תֹאמַר שֶׁהַקָּרְבָּן נִקְרָב לָהֶם וְלֹא לְשׁוּם כֹּחַ אַחֵר, אֶלָּא הַכֹּל נִקְרָב לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וְהוּא מוֹרִיק בְּרָכוֹת וּמְחַלֵּק בְּרָכוֹת לְכָל הָעוֹלָמוֹת, וּמִשּׁוּם כָּךְ קָרְבָּן לַה', וְלֹא לְאַחֵר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּנִי, יָפֶה אָמַרְתָּ. עוֹד, הִתְעוֹרְרוּת אַחֶרֶת שֶׁל הַקָּרְבָּן, (הכל) כְּדֵי לִמְשֹׁךְ בְּרָכוֹת וּלְעוֹרֵר בְּרָכוֹת, שֶׁיִּתְבָּרְכוּ כָּל הָעוֹלָמוֹת. בַּתְּחִלָּה קָרְבָּן לַה', וְלֹא לְאַחֵר. עַכְשָׁו תַּקְרִיבוּ אֶת קָרְבַּנְכֶם, שֶׁיִּתְקַשְּׁרוּ כָּל הָעוֹלָמוֹת כְּאֶחָד, וְיִתְחַבְּרוּ וְיִתְבָּרְכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>"],[9522011499,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר פָּסוּק אַחֲרָיו, כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר וְגוֹ'. כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל!? הָיָה צָרִיךְ (לכתב) אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל, מַה זֶּה כָּל אֵלֶּה? אֶלָּא לְחַבֵּר (לחתם) אוֹתָם לְמָקוֹם שֶׁכָּל הַבְּרָכוֹת מוֹרִיקִים לְשָׁם שְׁנֵים עָשָׂר. שְׁנֵים עָשָׂר וַדַּאי, קְשָׁרִים שֶׁל תִּקּוּנֵי הַגְּבִירָה, וְהִיא מִתְחַבֶּרֶת עִמָּם. זֶהוּ שֶׁכָּתוּב שְׁנֵים עָשָׂר. וְזאת אֲשֶׁר דִּבֶּר לָהֶם אֲבִיהֶם וַיְבָרֶךְ אוֹתָם, שֶׁהֲריֵ בְּמָקוֹם זֶה הַדִּבּוּר שׁוֹרֶה.</p>\n<p>אֲשֶׁר דִּבֶּר, כָּאן קֶשֶׁר אֶחָד לְהִתְחַבֵּר מִלְּמַטָּה לְמַעְלָה, וּמִלְמַעְלָה לְמַטָּה. מִלְּמַטָּה בִּשְׁנֵים עָשָׂר הַשְּׁבָטִּים הַלָּלוּ, וְזֹאת הִתְחַבְּרָה עִמָּם. אֲשֶׁר דִּבֶּר, הֲרֵי חִבּוּר זָכָר וּנְקֵבָה קָשׁוּר לִשְׁנֵי צְדָדִים, מִלְּמַטָּה וּמִלְמַעְלָה. לַסּוֹף קָשַׁר אוֹתָם בַּמָּקוֹם שֶׁלְּמַעְלָה, זָכָר וּנְקֵבָה כְּאֶחָד, זֶהוּ שֶׁכָּתוּב אִישׁ אֲשֶׁר כְּבִרְכָתוֹ וְגוֹ'. מַה זֶּה כְּבִרְכָתוֹ? אֶלָּא כְּבִרְכַּת בַּת זוּגוֹ. אִישׁ אֲשֶׁר כְּבִרְכָתוֹ, שְׁנֵיהֶם כְּאֶחָד.</p>\n<p>פָּתַח וְאָמַר, (תהלים קכח) יְבָרֶכְךְ ה' מִצִּיּוֹן וּרְאֵה בְּטוּב יְרוּשָׁלם וְגוֹ'. יְבָרֶכְךְ ה' מִצִּיּוֹן, שֶׁמִּמֶּנּוּ יוֹצְאִים בְּרָכוֹת לְהַשְׁקוֹת אֶת הַגָּן, וְהוּא כּוֹלֵל כָּל הַבְּרָכוֹת וְנוֹתֵן לָהּ. וְאַחַר כָּךְ וּרְאֵה בְּטוּב יְרוּשָׁ לם, לְהַרְאוֹת שֶׁכָּל הַבְּרָכוֹת בָּאוֹת מִזָּכָר וּנְקֵבָה. כְּמוֹ זֶה (במדבר ו) יְבָרֶכְךְ ה' וְיִשְׁמְרֶךְ. יְבָרֶכְךְ ה' - מִזָּכָר, וְיִשְׁמְרֶךְ - מִנְּקֵבָה. יְבָרֶכְךְ ה' - מִזָּכוֹר, וְיִשְׁמְרֶךְ - מִשָּׁמוֹר, וְהַכֹּל דָּבָר אֶחָד, מִשּׁוּם שֶׁמִּשְּׁנֵיהֶם יוֹצְאוֹת בְּרָכוֹת לָעוֹלָמוֹת. וְעַל זֶה, אִישׁ אֲשֶׁר כְּבִרְכָתוֹ בֵּרַךְ אֹתָם.</p>"],[9522011500,"<p>רַבִּי יְהוּדָה פָּתַח פָּסוּק וְאָמַר, וַיְכַל יַעֲקֹב לְצַוּת אֶת בָּנָיו וְגוֹ'. וַיְכַל יַעֲקֹב לְצַוּת אֶת בָּנָיו, לְצַוּת? הָיָה צָרִיךְ (לכתב) לְבָרֵךְ! אֶלָּא שֶׁצִּוָּה אוֹתָם אֶל הַשְּׁכִינָה לְהִתְקַשֵּׁר אֵלֶיהָ. עוֹד, שֶׁצִּוָּה אוֹתָם עַל עִסְקֵי הַמְּעָרָה, שֶׁהִיא קְרוֹבָה לְגַן עֵדֶן, שֶׁשָּׁם קָבוּר אָדָם הָרִאשׁוֹן.</p>\n<p>בֹּא רְאֵה, אוֹתוֹ מָקוֹם נִקְרָא קִרְיַת אַרְבַּע. מָה הַטַּעַם? מִשּׁוּם שֶׁשָּׁם נִקְבְּרוּ אַרְבָּעָה זוּגוֹת: אָדָם וְחַוָּה, אַבְרָהָם וְשָׂרָה, יִצְחָק וְרִבְקָה, יַעֲקֹב וְלֵאָה. הֲרֵי יֵשׁ כָּאן קֻשְׁיָא, שֶׁשָּׁנִינוּ, הָאָבוֹת הֵם מֶרְכָּבָה קְדוֹשָׁה, וּמֶרְכָּבָה לֹא פָחוֹת מֵאַרְבָּעָה, וְשָׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חִבֵּר אֶת דָּוִד הַמֶּלֶךְ עִמָּהֶם וְנַעֲשׂוּ מֶרְכָּבָה שְׁלֵמָה, זֶהוּ שֶׁכָּתוּב (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים וְגוֹ', שֶׁדָּוִד הַמֶּלֶךְ הִתְחַבֵּר לִהְיוֹת מֶרְכָּבָה שְׁלֵמָה עִמָּהֶם. אִם כָּךְ, דָּוִד צָרִיךְ (להתקשר) לְהִקָּבֵר בְּתוֹךְ הָאָבוֹת, וְיִהְיֶה קִרְיַת אַרְבַּע עִמּוֹ, אָז מָה הַטַּעַם לֹא נִקְבַּר עִמָּהֶם?</p>\n<p>אֶלָּא, דָּוִד הַמֶּלֶךְ מָקוֹם מְתֻקָּן הָיָה לוֹ כָּרָאוּי, וּמִיהוּ? צִיּוֹן, לְחַבֵּר אוֹתוֹ כְּאֶחָד. וְאָדָם שֶׁנִּקְבַּר בְּתוֹךְ הָאָבוֹת, הֲרֵי הֵם נִקְבְּרוּ עִמּוֹ, מִשּׁוּם שֶׁהוּא הָיָה מֶלֶךְ רִאשׁוֹן, וְנֶעֶבְרָה מִמֶּנּוּ הַמַּלְכוּת וְנִתְּנָה לְדָוִד הַמֶּלֶךְ, וּמִיָּמָיו שֶׁל אָדָם הִתְקַיֵּם דָּוִד הַמֶּלֶךְ, שֶׁעַל אָדָם נִגְזְרוּ אֶלֶף שָׁנִים, וְהָעָבְרוּ מִמֶּנּוּ שִׁבְעִים שָׁנִים, יָמָיו שֶׁל דָּוִד הַמֶּלֶךְ, וְהוּא נָתַן אוֹתָם, וְהָאָבוֹת אֵיךְ יָקוּמוּ עַד שֶׁיָּבֹא דָוִד הַמֶּלֶךְ? אֶלָּא זָכָה לִמְקוֹמוֹ כָּרָאוּי לוֹ, מִשּׁוּם כָּךְ לֹא נִקְבַּר עִם הָאָבוֹת.</p>\n<p>זֹאת וְעוֹד, הָאָבוֹת שְׁרוּיִים בְּמָקוֹם שֶׁל זָכָר, וְדָוִד בְּמָקוֹם שֶׁל נְקֵבָה, וְהָאָבוֹת נִקְבְּרוּ עִמָּם הַנְּקֵבוֹת, וְדָוִד נִקְבַּר וְהִתְחַבֵּר בְּמָקוֹם שֶׁל זָכָר, דָּבָר כָּרָאוּי לוֹ.</p>"],[9522011501,"<p>וַיְּאסֹף רַגְלָיו אֶל הַמִּטָּה, מִשּׁוּם שֶׁהֲרֵי הוּא יוֹשֵׁב בְּמָקוֹם שֶׁל חַיִּים. כְּשֶׁרָצָה לְהִסְתַּלֵּק מֵהָעוֹלָם, הוֹרִיד רַגְלָיו אֶל הַמִּטָּה, וְהִתְכַּנֵּס וְהִסְתַּלֵּק מִן הָעוֹלָם. זֶהוּ שֶׁכָּתוּב וַיִּגְוַע וַיֵּאָסֶף אֶל עַמָּיו. פָּתַח וְאָמַר, (שם פב) נִכְסְפָה וְגַם כָּלְתָה נַפְשִׁי לְחַצְרוֹת ה'. דָּבָר זֶה הֲרֵי בֵּאֲרוּהוּ הַחֲבֵרִים.</p>\n<p>אֲבָל בֹּא רְאֵה, יֵשׁ מְדוֹרִים תַּחְתּוֹנִים וְיֵשׁ מְדוֹרִים עֶלְיוֹנִים. בָּעֶלְיוֹנִים לֹא (מדורים) שׁוֹרִים שָׁם, וּמִי הֵם? אוֹתָם בָּתִּים פְּנִימִיִּים וּבָתִּים חִיצוֹנִיִּים הֵם נִקְרָאִים חַצְרוֹת ה', מִשּׁוּם שֶׁהֵם עוֹמְדִים שָׁם בְּאַהֲבָה וּתְשׁוּקָה אֶל הַנְּקֵבָה. בּא רְאֵה, כְּשֶׁנְּשָׁמָה עוֹלָה, הַכֹּל מִתְעוֹרֵר לַנְּקֵבָה, שֶׁהֲרֵי הִיא אֲחוּזָה בִּתְשׁוּקָה שְׁלֵמָה וְנִקְשֶׁרֶת בּוֹ.</p>\n<p>יַעָקֹב לֹא מֵת, מִשּׁוּם כָּךְ לֹא נֶאֱמַר בּוֹ מָוֶת, אֶלָּא וַיִּגְוַע וַיֵּאָסֶף אֶל עַמָּיו. רְאֵה מַה כָּתוּב, וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, שֶׁהִתְכַּנֵּס הַשֶּׁמֶשׁ אֶל הַלְּבָנָה. הַשֶּׁמֶשׁ לֹא מֵת, אֶלָּא מִתְכַּנֵּס מִן הָעוֹלָם וְהוֹלֵךְ לַלְּבָנָה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהִתְכַּנֵּס יַעֲקֹב, הֵאִירָה הַלְּבָנָה, וּתְשׁוּקַת הַשֶּׁמֶשׁ הָעֶלְיוֹן הִתְעוֹרְרָה אֵלָיו, מִשּׁוּם שֶׁכַּאֲשֶׁר הַשֶּׁמֶשׁ עוֹלֶה, מִתְעוֹרֵר שֶׁמֶשׁ אַחֵר, וְנִדְבָּקִים זֶה בָּזֶה וְהַלְּבָנָה מְאִירָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, יָפֶה אָמַרְתָּ, אֲבָל הֲרֵי נִתְבָּאֵר שֶׁהָעֶלְיוֹן, עוֹלַם הַזָּכָר, נִקְשָׁר בַּתַּחְתּוֹן, שֶׁהוּא עוֹלַם הַנְּקֵבָה, וְהַתַּחְתּוֹן נִקְשָׁר לָעֶלְיוֹן, וְהַכֹּל זֶה כְּמוֹ זֶה.</p>\n<p>וַהֲרֵי נֶאֱמַר שְׁנֵי עוֹלָמוֹת הֵם, כַּכָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם. וְאַף עַל גַּב שֶׁשְּׁתֵּי נְקֵבוֹת הֵן - אֶחָד מְתֻקָּן בַּזָּכָר וְאֶחָד בַּנְּקֵבָה. זֶה שֶׁבַע (שבת), וְזֶה בַּת שֶׁבַע. זוֹ אֵם וְזוֹ אֵם. זוֹ נִקְרֵאת אֵם הַבָּנִים, וְזוֹ נִקְרֵאת אֵם שְׁלֹמֹה, כַּכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ'. בַּמֶּלֶךְ שְׁלֹמֹה - בַּמֶּלֶךְ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ, זוֹ אֵם שְׁלֹמֹה, כַּכָּתוּב (מלכים א יא) בַּת שֶׁבַע אֵם שְׁלֹמֹה.</p>\n<p>וְכָתוּב (שם ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה. חָכְמַת שְׁלֹמֹה - זוֹ אֵם שְׁלֹמֹה, שֶׁכָּתוּב (משלי לא) דִּבְרֵי לְמוּאֵל מֶלֶךְ מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ. דִּבְרֵי לְמוּאֵל מֶלֶךְ, פָּסוּק זֶה לֹא נוֹדָע מַהוּ הַסֵּתֶר שֶׁלּוֹ, אֶלָּא דִּבְרֵי לְמוּאֵל מֶלֶךְ - דְּבָרִים שֶׁנֶּאֶמְרוּ מִשּׁוּם אֵל שֶׁהוּא מֶלֶךְ. וּמִיהוּ זֶה? (תהלים ז) וְאֵל זֹעֵם בְּכָל יוֹם. וְאֵל שַׁדַּי, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>לְמוּאֵל, כְּמוֹ שֶׁנֶּאֱמַר (איוב מ) לְמוֹ פִי. לְמוּאֵל מֶלֶךְ, שֶׁהִיא בַּת שֶׁבַע. מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, כְּשֶׁהִתְגַּלָּה עָלָיו בְּגִבְעוֹן בַּחֲלוֹם הַלַּיְלָה.</p>\n<p>בֹּא רְאֵה, יַעֲקֹב הִתְכַּנֵּס לַלְּבָנָה וְעָשָׂה בָּהּ פֵּרוֹת לָעוֹלָם, וְאֵין לְךְ דּוֹר בָּעוֹלָם שֶׁאֵין בּוֹ פְּרִי שֶׁל יַעֲקֹב, מִשּׁוּם שֶׁהֲרֵי הוּא עוֹרֵר הִתְעוֹרְרוּת לְמַעְלָה, מִשּׁוּם שֶׁכָּתוּב וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, שֶׁהִיא מִטָּתוֹ שֶׁל יַעֲקֹב וַדַּאי.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל יַעֲקֹב, שֶׁהֲרֵי הִשְׁתַּלֵּם לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב (ירמיה ל) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם ה' וְגוֹ' כִּי אִתְּךְ אָנִי. כִּי אִתִּי אַתָּה לֹא נֶאֱמַר, אֶלָּא כִּי אִתְּךְ אָנִי, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522011502,"<p>רַבִּי יִצְחָק פָּתַח וְאָמַר, וַיָּבֹאוּ עַד גֹּרֶן הָאָטָד וְגוֹ', וְכָתוּב וַיַּרְא יוֹשֵׁב הָאָרֶץ הַכְּנַעֲנִי אֶת הָאֵבֶל בְּגֹרֶן הָאָטָד וְגוֹ'. בַּפְּסוּקִים הַלָּלוּ יֵשׁ לְהִתְבּוֹנֵן בָּהֶם, מָה אִכְפַּת לָנוּ שֶׁהֵם בָּאוּ עַד גֹּרֶן הָאָטָד? וּמָה הַטַּעַם כִּנּוּ אֲבֵלוּת זוֹ לְמִצְרַיִם, הֲרֵי צָרִיךְ הָיָה לִכְתֹּב אֵבֶל יִשְׂרָאֵל, מָה הַטַּעַם לְמִצְרַיִם?</p>\n<p>אֶלָּא כָּךְ אָמְרוּ, כָּל אוֹתוֹ זְמַן שֶׁהָיָה יַעֲקֹב בְּמִצְרַיִם, הִתְבָּרְכָה הָאָרֶץ בִּגְלָלוֹ, וְנִילוּס הָיָה יוֹצֵא וּמַשְׁקֶה אֶת הָאָרֶץ. וְעוֹד, שֶׁפָּסַק הָרָעָב בִּגְלַל יַעֲקֹב, וְעַל כָּךְ הַמִּצְרִים עָשׂוּ אֵבֶל, וְהִתְכַּנָּה עֲלֵיהֶם.</p>\n<p>פָּתַח וְאָמַר, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל מַה זֶּה יְמַלֵּל? יְדַבֵּר הָיָה צָרִיךְ לִכְתֹּב! וְאִם תֹּאמַר שֶׁזּוֹ דֶּרֶךְ הַכָּתוּב, שֶׁהֲרֵי הַפְּסוּקִים הֵם כָּךְ - לֹא, שֶׁכֻּלָּם בָּאִים לְהַרְאוֹת דָּבָר, אַף כָּאן בָּא לְהַרְאוֹת דָּבָר. מִי יְמַלֵּל (גבורות ה'), כַּכָּתוּב (דברים כג) וְקָטַפְתָּ מְלִילֹת. גְּבוּרוֹת ה', מִשּׁוּם שֶׁהֵם רַבִּים, שֶׁהֲרֵי כָּל גְּזֵרַת הַדִּין בָּאָה מִשָּׁם, וְלָכֵן מִי הוּא שֶׁיְּסַלֵּק וְיַעֲבִיר גְּזֵרָה אַחַת מֵאוֹתָן גְּבוּרוֹת שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>עוֹד, מִי יְמַלֵּל וִידַבֵּר, הַכֹּל אֶחָד. יְדַבֵּר, שֶׁהֲרֵי כַּמָּה וְכַמָּה גְבוּרוֹת הֵן שֶׁאֵין לָהֶם חֶשְׁבּוֹן, כַּמָּה בַּעֲלֵי דִינִים, כַּמָּה בַּעֲלֵי מָגִנִּים, כַּמָּה שׁוֹמְרֵי הַחֻקִּים, וְהַדִּבּוּר לֹא יָכוֹל לְדַבֵּר לָהֶם.</p>\n<p>וּבַמֶּה יְדוּעוֹת? כֻּלָּם בְּהַגָּדָה, שֶׁיֵּשׁ בָּהּ סוֹד הַחָכְמָה, שֶׁהֲרֵי בְּדִבּוּר וּבַאֲמִירָה לֹא יָכוֹל לְדַבֵּר לָהֶם וְלָדַעַת אוֹתָם, אֲבָל בְּהַגָּדָה הֵן יְדוּעוֹת, כַּכָּתוּב (תהלים קמה) דּוֹר לְדוֹר יְשַׁבַּח מַעֲשֶׂיךְ וּגְבוּרֹתֶיךְ יַגִּידוּ. בְּסוֹד זֶה יוֹדְעִים, אֲבָל גְּבוּרָתֶךְ, שֶׁהִיא גְּבוּרָה תַחְתּוֹנָה, יְדַבֵּרוּ, שֶׁכָּתוּב וּגְבוּרָתְךְ יְדַבֵּרוּ.</p>\n<p>יַשְׁמִיעַ כָּל תְּהִלָּתוֹ, שֶׁרַבִּים הֵם (הדרגות) הַדִּינִים שֶׁנּוֹדָעִים וּמְחֻבָּרִים בִּתְהִלָּה, וְכַמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת שֶׁמִּתְחַבְּרִים בָּהּ, כַּכָּתוּב (איוב כה) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו, וְעַל זֶה מִי יָכוֹל לְהַשְׁמִיעַ כָּל תְּהִלָּתוֹ?</p>\n<p>בֹּא רְאֵה, הַמִּצְרִים כֻּלָּם הָיוּ חֲכָמִים, וּמִצַּד הַגְּבוּרָה יָצְאוּ, כַּמָּה חֲיָלוֹת וְכַמָּה מַחֲנוֹת וְכַמָּה דְרָגוֹת עַל דְּרָגוֹת, עַד שֶׁמַּגִּיעִים לַדְּרָגוֹת הַתַּחְתּוֹנוֹת, וְהַמִּצְרִים הָיוּ מְכַשְּׁפִים וַחֲכָמִים בָּהֶם, וְיוֹדְעִים נִסְתְּרוֹת הָעוֹלָם, וְהִסְתַּכְּלוּ, שֶׁהֲרֵי שֶׁבִּזְמַן שֶׁיַּעֲקֹב קַיָּם בָּעוֹלָם, אֵין עַם שֶׁיִּשְׁלֹט עַל בָּנָיו, וְיָדְעוּ שֶׁהֲרֵי יִשְׁתַּעְבְּדוּ בְיִשְׂרָאֵל זְמַנִּים רַבִּים.</p>\n<p>כֵּיוָן שֶׁיַּעֲקֹב מֵת, שָׂמְחוּ. הִסְתַּכְּלוּ מַה יִּהְיֶה בַּסּוֹף, עַד שֶׁהִגִּיעוּ לְגֹרֶן הָאָטָד, שֶׁהוּא גְזֵרַת הַדִּין הַשּׁוֹלֵט. אָטָ\"ד בְּגִימַטְרִיָּא יָד, כְּמוֹ שֶׁנֶּאֱמַר (שמות יד) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ'. כֵּיוָן שֶׁהִגִּיעוּ לְמָקוֹם זֶה, רָאוּ הַגְּבוּרוֹת שֶׁיּוֹצְאוֹת מֵהָאָטָד הַזֶּה. וְלָמָּה נִקְרָא אָטָד? אֶלָּא מָה אָטָד יוֹצְאִים קוֹצִים לְצַד זֶה וּלְצַד זֶה, כָּךְ גַּם יָ\"ד יוֹצְאוֹת מִמֶּנָּה אֶצְבָּעוֹת לְצַד זֶה וּלְצַד זֶה, וְכָל אֶצְבַּע וְאֶצְבַּע עוֹלָה בְּכַמָּה גְבוּרוֹת, בְּכַמָּה דִינִים, בְּכַמָּה הַנְהָגוֹת, אָז וַיִּסְפְּדוּ שָׁם מִסְפֵּד גָּדוֹל וְכָבֵד מְאֹד עַל כֵּן קָרָא שְׁמָהּ אָבֵל מִצְרָיִם. וַדַּאי אֵבֶל כָּבֵד זֶה לְמִצְרַיִם, וְלֹא לְאַחֵר.</p>\n<p>רַבִּי שִׁמְעוֹן פֵּרַשׁ אֶת הַפָרָשָׁה. יָצְאוּ מִתּוֹךְ הַמְּעָרָה. אָמַר, רָאִיתִי שֶׁיּוֹם זֶה יִפֹּל בַּיִת בָּעִיר, וְיֵעָדְרוּ שְׁנֵי (בני) רוֹמָאִים מְקַטְרְגִים. אִם אֲנִי בָּעִיר, לֹא יִפֹּל הַבַּיִת. חָזְרוּ לְתוֹךְ הַמְּעָרָה וְיָשְׁבוּ.</p>"],[9522011503,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (ישעיה י) צַהֲלִי קוֹלֵךְ בַּת גַּלִּים וְגוֹ'. צַהֲלִי קוֹלֵךְ, פָּסוּק זֶה נֶאֱמַר לִכְנֶסֶת יִשְׂרָאֵל, מִשּׁוּם שֶׁהִיא מְשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּקוֹל מְשֻׁבָּח, וְעַל כָּךְ צַהֲלִי קוֹלֵךְ. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁרוֹצֶה לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּקוֹל, צָרִיךְ לוֹ קוֹל נָעִים שֶׁיֶּעֱרַב לָאֲחֵרִים שֶׁשּׁוֹמְעִים אוֹתוֹ, וְאִם לֹא - לֹא יָקוּם לְהָרִים קוֹל.</p>\n<p>בֹּא רְאֵה, לְוִיִּם שֶׁבָּאוּ מִצַּד זֶה, שֶׁכָּתוּב (במדבר ח) וּמִבֶּן חֲמִשִּׁים שָׁנָה יָשׁוּב מִצְּבָא הָעֲבדָה. מָה הַטַּעַם? מִשּׁוּם שֶׁקּוֹלוֹ (דרגתו, ואם) נָמוּךְ, וְלֹא יֶעֱרַב לָאָזְנַיִם כִּשְׁאָר חֲבֵרָיו, אָז מַעֲבִירִים מִצְּבָא הָעֲבוֹדָה הַזֶּה (מהחילים) שֶׁל מַעְלָה, שֶׁעוֹמְדִים לְנַגֵּן לָעֲבוֹדָה הַזּוֹ וּלְכַבֵּד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי.</p>\n<p>הַחֲיָלוֹת שֶׁלְּמַעְלָה, חֲיָלוֹת וּמַחֲנוֹת כְּנֶגֶד הַתַּחְתּוֹנִים, לְשַׁבֵּחַ אֶת הַשֵּׁם הַקָּדוֹשׁ וּלְזַמֵּר לָהֶם, וּמִשּׁוּם כָּךְ יָשׁוּב מִצְּבָא הָעֲבֹדָה. וּמִשּׁוּם שֶׁכְּנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אָמַר הַכָּתוּב צַהֲלִי קוֹלֵךְ בַּת גַּלִּים, בַּת הָאָבוֹת.</p>\n<p>עוֹד בַּת גַּלִּים - הָעוֹלָם הַבָּא נִקְרָא גַּלִּים, מִשּׁוּם שֶׁהַכֹּל עוֹמֵד בּוֹ, וְנִכְלָל בּוֹ תִּלֵּי תִלִּים, וְיוֹצֵא מִמֶּנּוּ לַכֹּל. עוֹד בַּת גַּלִּים - כַּכָּתוּב (שיר ד) גַּל נָעוּל, וְכָל אוֹתָם גַּלִּים וּמַעְיָנוֹת, כֻּלָּם יוֹצְאִים מֵהָעוֹלָם הַבָּא, וּכְנֶסֶת יִשְׂרָאֵל הִיא בַּת גַּלִּים.</p>\n<p>בֹּא רְאֵה, פָּסוּק זֶה קָשֶׁה. בַּתְּחִלָּה כָּתוּב צַהֲלִי קוֹלֵךְ, שֶׁהוּא כְּדֵי לְזַמֵּר וּלְהָרִים קוֹל, וְאַחַר כָּךְ כָּתוּב הַקְשִׁיבִי. אִם כָּךְ, אָז לָמָּה צַהֲלִי קוֹלֵךְ, כֵּיוָן שֶׁכָּתוּב הַקְשִׁיבִי? אֶלָּא צַהֲלִי כְּדֵי לְשַׁבֵּחַ וּלְזַמֵּר. בֹּא רְאֵה, אִם יִשְׂרָאֵל מַתְחִילִים לְשַׁבֵּחַ וּלְזַמֵּר לַקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז כָּתוּב הַקְשִׁיבִי, מָה הַטַּעַם? בִּשְׁבִיל שֶׁיִּשְׂרָאֵל מְשַׁבְּחִים וּמְזַמְּרִים בִּשְׁבִילָהּ לַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה כָּתוּב צַהֲלִי קוֹלֵךְ, וְכָתוּב הַקְשִׁיבִי.</p>\n<p>לַיְשָׁה - מִשּׁוּם שֶׁבָּאָה מִצַּד הַגְּבוּרָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי ל) לַיִשׁ גִּבּוֹר בַּבְּהֵמָה. וְלַיְשָׁה זוֹ גְּבוּרָה, לִשְׁבֹּר כֹּחוֹת וָחֳזָקִים. עֲנִיָּה עֲנָתוֹת - מִשּׁוּם שֶׁהִיא אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה (עליה), עֲנִיָּה וַדַּאי, אֵין לָהּ לַלְּבָנָה אוֹר מִשֶּׁל עַצְמָהּ, אֶלָּא רַק מַה שֶּׁנּוֹתֵן לָהּ הַשֶּׁמֶשׁ.</p>\n<p>עָנָתוֹת הוּא שָׂדֶה, כְּפָר אֶחָד, וְשׁוֹרִים בּוֹ כֹּהֲנִים עֲנִיִּים שֶׁמְּחַזְּרִים עַל הַפְּתָחִים (של הלוים), וְאֵין מִי שֶׁיַּשְׁגִּיחַ בָּהֶם, מִשּׁוּם שֶׁכָּל אוֹתָם בְּנֵי אוֹתוֹ כְּפָר (קלים), בְּזוּיִים הָיוּ בְּעֵינֵי הָעָם, וּבֵיתָם יוֹתֵר רֵיק מִכָּל הָעָם, פְּרָט לְמַה שֶּׁנּוֹתְנִים לָהֶם, כְּמוֹ עֲנִיִּים (קלים) בְּזוּיֵי עַם. מִשּׁוּם כָּךְ לַלְּבָנָה אֵין אוֹר מִשֶּׁל עַצְמָהּ, אֶלָּא בְּשָׁעָה שֶׁמִּתְחַבֵּר עִמָּהּ הַשֶּׁמֶשׁ הִיא מְאִירָה.</p>\n<p>בֹּא רְאֵה, שֶׁכָּתוּב (מלכים א ב) וּלְאֶבְיָתָר הַכֹּהֵן אָמַר הַמֶּלֶךְ עֲנָתֹת לֵךְ עַל שָׂדֶיךְ כִּי אִישׁ מָוֶת אָתָּה. וְכִי עַל שֶׁהִזְמִין אֶת אֲדוֹנִיּהָוּ נִקְרָא אִישׁ מָוֶת? אֶלָּא מִשּׁוּם שֶׁהָיָה מִמָּקוֹם עָנִי, שֶׁנִּדְבְּקָה בּוֹ הַלְּבָנָה, שֶׁהִיא עֲנִיָּה עֲנָתוֹת.</p>\n<p>וְאִם תֹּאמַר, (שם) וְכִי הִתְעַנִּיתָ בְּכֹל אֲשֶׁר הִתְעַנָּה אָבִי, מִשּׁוּם כָּךְ צַדִּיק שֶׁלֹּא הָרַג אוֹתוֹ? אֶלָּא אֶבְיָתָר, מִשּׁוּם שֶׁהָיָה מִמָּקוֹם עָנִי, זָכָה בּוֹ דָּוִד עַד שֶׁלֹּא עָלָה לַמַּלְכוּת, כְּשֶׁהָיָה אוֹרֵב לוֹ לְשָׁאוּל, וְהָיָה דַרְכּוֹ כְּעָנִי, (אחר כך) כְּמוֹ זֶה אֶבְיָתָר. וְלִזְמַן שֶׁשָּׁלַט שְׁלֹמֹה, עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּת, וְהָיְתָה בְּחֶדְוָה שֶׁל עֹשֶׁר, שֶׁהַכֹּל הָיָה לוֹ, לֹא זָכָה בְּאֶבְיָתָר.</p>\n<p>וַדַּאי שְׂדֵה עֲנָתוֹת סוֹד הַדָּבָר הָיָה, וְיִרְמְיָה שֶׁקָּנָה אוֹתוֹ, הַכֹּל הָיָה בִּשְׁבִיל לָרֶשֶׁת סוֹד עֶלְיוֹן. בּא רְאֵה, כְּשֶׁשּׁוֹלֶטֶת הַלְּבָנָה, הִיא נִקְרֵאת שְׂדֵה תַפּוּחִים. כְּשֶׁהִיא בְּעֹנִי, שְׂדֵה עֲנָתוֹת. מִשּׁוּם כָּךְ תִּשְׁבַּחַת שֶׁלְּמַטָּה עוֹשָׂה לָהּ עֹשֶׁר וּשְׁלֵמוּת.</p>\n<p>כְּמוֹ שֶׁדָּוִד, כָּל יָמָיו הִשְׁתַּדֵּל לַעֲשׂוֹת לָהּ שְׁלֵמוּת וּלְנַגֵּן מִינֵי זֶמֶר לְזַמֵּר וּלְשַׁבֵּחַ לְמַטָּה, וּכְשֶׁדָּוִד הִסְתַּלֵּק מֵהָעוֹלָם, הִשְׁאִיר אוֹתָהּ בִּשְׁלֵמוּת, וּשְׁלֹמֹה לָקַח אוֹתָהּ בְּעֹשֶׁר, בִּשְׁלֵמוּת, שֶׁהֲרֵי הַלְּבָנָה יָצְאָה מֵהָעֹנִי וְנִכְנְסָה לָעֹשֶׁר, שֶׁבָּעֹשֶׁר הַזֶּה שָׁלַט עַל כָּל מַלְכֵי הָאָרֶץ.</p>"],[9522011504,"<p>וְעַל זֶה, (שם י) אֵין כֶּסֶף (לא) נֶחְשָׁב בִּימֵי שְׁלֹמֹה. אֶלָּא הַכֹּל זָהָב, שֶׁהִתְרַבָּה הַזָּהָב, וּבְאוֹתוֹ הַזְּמַן כָּתוּב (איוב כח) וְעַפְרֹת זָהָב לוֹ, שֶׁהֲרֵי עָפָר שֶׁלְּמַעְלָה הָיָה מִסְתַּכֵּל בּוֹ הַשֶּׁמֶשׁ, וּבַהִסְתַּכְּלוּת שֶׁל הַשֶּׁמֶשׁ וְתָקְפּוֹ, הֶעָפָר נַעֲשֶׂה וּמִתְרַבֶּה הַזָּהָב.</p>\n<p>בֹּא רְאֵה, מִן הֶהָרִים שֶׁכֹּחַ הַשֶּׁמֶשׁ מֵאִיר שָׁם, עֲפַר הָאָרֶץ שֶׁבֵּין הֶהָרִים כֻּלָּם עוֹשִׂים זָהָב, וְאִלְמָלֵא חַיּוֹת רָעוֹת שֶׁרַבּוֹת שָׁם, לֹא הָיוּ אֲנָשִׁים עֲנִיִּים, מִשּׁוּם שֶׁתֹּקֶף הַשֶּׁמֶשׁ מַרְבֶּה אֶת הַזָּהָב.</p>\n<p>מִשּׁוּם כָּךְ בִּימֵי שְׁלֹמֹה אֵין כֶּסֶף נֶחְשָׁב לִמְאוּמָה, שֶׁהֲרֵי תֹּקֶף הַשֶּׁמֶשׁ מִסְתַּכֵּל בֶּעָפָר וּמַרְבֶּה אֶת הַזָּהָב. וְעוֹד, שֶׁאוֹתוֹ עָפָר הוּא צַד הַדִּין. כְּשֶׁמִּסְתַּכֵּל בּוֹ הַשֶּׁמֶשׁ, נוֹטֵל תֹּקֶף וּמִתְרַבֶּה זָהָב. כֵּיוָן שֶׁהִסְתַּכֵּל שְׁלֹמֹה בָּהּ, שִׁבַּח וְהִכְרִיז וְאָמַר, (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְגוֹ'.</p>\n<p>וְעַל זֶה שְׁלֹמֹה לֹא הִצְטָרֵךְ לְנַגֵּן כְּמוֹ דָוִד, אֶלָּא שִׁירָה שֶׁהִיא אַהֲבָה שֶׁל עֹשֶׁר, שֶׁהִיא אוֹר וְאַהֲבָה שֶׁכָּל הַתִּשְׁבָּחוֹת שֶׁל הָעוֹלָם הָיוּ בָהּ, הַשֶּׁבַח שֶׁל הַגְּבִירָה כְּשֶׁיּוֹשֶׁבֶת בַּכִּסֵּא כְּנֶגֶד הַמֶּלֶךְ הוּא אָמַר.</p>\n<p>כָּתוּב (מלכים א י) וַיִּתֵּן הַמֶּלֶךְ אֶת הַכֶּסֶף בִּירוּשָׁ לם כַּאֲבָנִים, מִשּׁוּם שֶׁהַכֹּל הָיָה זָהָב, וְהֶעָפָר נִקְשָׁר בַּשְּׂמֹאל בְּצַד הָאַהֲבָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, וְהַשֶּׁמֶשׁ נִדְבָּק עִמָּהּ וְלֹא זָז מִמֶּנָּה.</p>\n<p>שְׁלֹמֹה טָעָה בָּזֶה, שֶׁהֲרֵי רָאָה שֶׁהַלְּבָנָה קָרְבָה לַשֶּׁמֶשׁ, וְהַיָּמִין מְחַבֶּקֶת, וְהַשְּׂמֹאל תַּחַת הָרֹאשׁ. כֵּיוָן שֶׁהִתְקָרְבוּ זֶה לָזוֹ, אָמַר, הֲרֵי הִתְקָרְבוּ כְּאֶחָד, יָמִין מַה כָּאן עוֹשָׂה, שֶׁהֲרֵי יָמִין אֵינָהּ אֶלָּא כְּדֵי לְקָרֵב? כֵּיוָן שֶׁקָּרְבוּ זֶה בָּזֶה, לָמָּה צָרִיךְ? מִיָּד אֵין כֶּסֶף (לא) נֶחְשָׁב בִּימֵי שְׁלֹמֹה.</p>\n<p>אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתָּה דָּחִיתָ אֶת הַיָּמִין - חַיֶּיךְ, אַתָּה תִּצְטָרֵךְ לְחֶסֶד בְּנֵי אָדָם וְלֹא תִמְצָא. מִיָּד סָטָה הַשֶּׁמֶשׁ מִכְּנֶגֶד הַלְּבָנָה, וְהַלְּבָנָה הִתְחִילָה לְהֵחָשֵׁךְ, וְהָיָה שְׁלֹמֹה מְחַזֵּר עַל הַפְּתָחִים וְאוֹמֵר (קהלת א) אֲנִי קֹהֶלֶת, וְלֹא הָיָה מִי שֶׁיַּעֲשֶׂה עִמּוֹ חֶסֶד. מָה הַטַּעַם? מִשּׁוּם שֶׁדָּחָה אֶת הַיָּמִין וְלֹא הֶחְשִׁיב אוֹתוֹ, זֶהוּ שֶׁכָּתוּב (מלכים א י) אֵין כֶּסֶף (לא) נֶחְשָׁב בִּימֵי שְׁלֹמֹה לִמְאוּמָה.</p>\n<p>וְלָכֵן כָּל הַמַּרְבֶּה תִשְׁבָּחוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא, מַרְבֶּה שָׁלוֹם לְמַעְלָה, מִשּׁוּם כָּךְ (ישעיה י) הַקְשִׁיבִי לַיְשָׁה. כָּתוּב (איוב ד) לַיִשׁ אֹבֵד מִבְּלִי טֶרֶף וְגוֹ'. לַיִשׁ - הַיְנוּ לַיְשָׁה, כַּכָּתוּב חֹק חֻקָּה. אֹבֵד - כַּכָּתוּב (ישעיה כז) וּבָאוּ הָאֹבְדִים. מִבְּלִי טֶרֶף - מִשּׁוּם שֶׁהִיא בִּקְשָׁה (סבה) עָלֶיהָ לָתֵת, כַּכָּתוּב (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ.</p>\n<p>וּבְנֵי לָבִיא יִתְפָּרָדוּ - מִשּׁוּם שֶׁכָּל הַחֲיָלִים, כְּשֶׁהִיא נוֹתֶנֶת לָהֶם טֶרֶף, כֻּלָּם מִתְחַבְּרִים כְּאֶחָד וְיוֹנְקִים כְּאֶחָד. וּכְשֶׁהִיא יוֹשֶׁבֶת מִבְּלִי טֶרֶף, שֶׁהַגָּלוּת גּוֹרֵם, וַדַּאי בְּנֵי לָבִיא יִתְפָּרָדוּ, כֻּלָּם נִפְרָדִים לְכַמָּה צְדָדִים וּדְרָכִים כְּדֵי לִמְצֹא לַעֲשׂוֹת דִּין. וְלָכֵן כְּשֶׁהַקָּרְבָּן נַעֲשֶׂה, הַכֹּל מְתֻקָּנִים וּמִתְקָרְבִים כְּאֶחָד, כְּמוֹ שֶׁאָמַרְנוּ. עַכְשָׁו שֶׁקָּרְבָּן לֹא נַעֲשֶׂה, וַדַּאי שֶׁבְּנֵי לָבִיא יִתְפָּרָדוּ, וּמִשּׁוּם כָּךְ אֵין לָנוּ יוֹם שֶׁלֹּא נִמְצָא בּוֹ דִּין, שֶׁהֲרֵי לֹא מִתְעוֹרְרִים עֶלְיוֹנִים וְתַחְתּוֹנִים בִּשְׁלֵמוּת עֶלְיוֹנָה כְּמוֹ שֶׁאָמַ רְנוּ.</p>\n<p>בֹּא רְאֵה, עַכְשָׁו תְּפִלַּת הָאָדָם מְעוֹרֶרֶת שְׁלֵמוּת לְמַעְלָה וּלְמַטָּה, וּבַבְּרָכָה שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְלָכֵן בַּתְּפִלָּה שֶׁל יִשְׂרָאֵל מִתְבָּרְכִים הָעוֹלָמוֹת. מִי שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא - יִתְבָּרֵךְ. מִי שֶׁלֹּא מְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא - לֹא מִתְבָּרֵךְ. זֶהוּ שֶׁכָּתוּב (שמואל א ב) כִּי מְכַבְּדַי אֲכַבֵּד וּבֹזַי יֵקָלּוּ.</p>"],[9522011505,"<p>רַב הַמְנוּנָא הַזָּקֵן לֹא נָתַן כּוֹס שֶׁל בְּרָכָה לְאָדָם אַחֵר לְבָרֵךְ, (שרצה לטל) אֶלָּא הוּא הִקְדִּים וְנָטַל אוֹתוֹ (בימין ובשמאל) בִּשְׁתֵּי יָדָיו וּמְבָרֵךְ. וַהֲרֵי אָמַרְנוּ שֶׁצָּרִיךְ לִטֹּל אוֹתוֹ בְּיָמִין (ולא בשמאל) וּבִשְׂמֹאל, וְאַף עַל גַּב שֶׁכֻּלָּם הִתְעוֹרְרוּ בוֹ - יָפֶה הוּא. אֲבָל כּוֹס שֶׁל בְּרָכָה כָּךְ צָרִיךְ כּוֹס, שֶׁכָּתוּב (תהלים קטז) כּוֹס יְשׁוּעוֹת אֶשָּׂא, שֶׁהֲרֵי בְּכוֹס זוֹ שׁוֹפְעוֹת הַבְּרָכוֹת מֵאוֹתָן יְשׁוּעוֹת שֶׁלְּמַעְלָה, וְהוּא נוֹטֵל אוֹתָם וְכוֹנֵס אוֹתָם אֵלָיו, וְשָׁם נִשְׁמָר (להם) יַיִן הָעֶלְיוֹן וּמִתְכַּנֵּס בְּאוֹתוֹ כּוֹס, וּצְרִיכִים לְבָרֵךְ אוֹתוֹ בְּיָמִין (ובשמאל) וְלֹא בִשְׂמֹאל, וְהַיַּיִן שֶׁהוּא כָּנוּס בַּכּוֹס הַ את, שֶׁיִּתְבָּרְכוּ כְּאֶחָד, וּצְרִיכִים לְבָרֵךְ אֶת הַשֻּׁלְחָן שֶׁלֹּא יִהְיֶה רֵיק מִלֶּחֶם וְיַיִן, הַכֹּל (אחד) כְּאֶחָד.</p>\n<p>בֹּא רְאֵה, כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת כּוֹס שֶׁל בְּרָכָה, וְכֵיוָן שֶׁהִיא כּוֹס שֶׁל בְּרָכָה, צָרִיךְ יָמִין וּשְׂמֹאל (וצריך) לִטֹּל אוֹתָהּ, וְאוֹתָהּ כּוֹס נִתֶּנֶת בֵּין יָמִין לִשְׂמֹאל, וּצְרִיכָה לְהִתְמַלֵּא יַיִן בִּשְׁבִיל יֵין הַתּוֹרָה שֶׁיּוֹצֵא מִן הָעוֹלָם הַבָּא.</p>\n<p>וּבֹא רְאֵה, כּוֹס שֶׁל בְּרָכָה, (כאן) בָּזֶה הִתְגַּלּוּ דְבָרִים עֶלְיוֹנִים כָּאן שֶׁאָנוּ בַּמְּעָרָה, אוֹמֵר כָּאן נִתְגַּלָּה סוֹד הַמֶּרְכָּבָה הַקְּדוֹשָׁה, כּוֹס שֶׁל בְּרָכָה צָרִיךְ לְקַבְּלָהּ בְּיָמִין וּבִשְׂמֹאל, זֶה צָפוֹן וְדָרוֹם, וְכוֹס שֶׁל בְּרָכָה שֶׁיִּהְיֶה נוֹטֵל בְּרָכָה מֵהֶם. מִי זוֹ כּוֹס שֶׁל בְּרָכָה? זוֹ (שיר ג) מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, שֶׁצָּרִיךְ שֶׁתִּנָּתֵן בֵּין צָפוֹן וְדָרוֹם, וְצָרִיךְ לְהַנִּיחָהּ בְּיָמִין, וְהַגּוּף שֶׁיִּתְתַּקֵּן עִמָּהֶם, וְיַשְׁגִּיחַ בְּאוֹתָהּ כּוֹס שֶׁל בְּרָכָה לְבָרֵךְ אוֹתָהּ בְּאַרְבַּע בְּרָכוֹת, מִשּׁוּם שֶׁכָּתוּב (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךְ בָּהּ וְגוֹ'. נִמְצָא בְּכוֹס שֶׁל בְּרָכָה סוֹד הָאֱמוּנָה, צָפוֹן וְדָרוֹם וּמִזְרָח וּמַעֲרָב, הֲרֵי מֶרְכָּבָה קְדוֹשָׁה כָּרָאוּי לוֹ.</p>\n<p>וְשֻׁלְחָן בְּלֶחֶם, כְּדֵי שֶׁיִּתְבָּרֵךְ אוֹתוֹ לֶחֶם שֶׁלְּמַטָּה וְיִתְבָּרֵךְ לֶחֶם עֹנִי, וְיִהְיֶה לֶחֶם עֹנֶג, וַהֲרֵי בֵּאַרְנוּ. וְיִמָּצֵא שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, לְמַעְלָה וּלְמַטָּה, לְמַעְלָה (באותו לחם של ברכה). וְכוֹס שֶׁל בְּרָכָה, לְחַבֵּר דָּוִד הַמֶּלֶךְ בָּאָבוֹת, וְיִתְבָּרֵךְ לְמַטָּה, שֶׁיִּתְבָּרֵךְ (והשלחן בלחם משום שיתברך מכל הצדדים, מלמעלה ומלמטה למעלה בסוד כוס של ברכה, שיתחבר דוד המלך באבות ויתברך למטה, שיתברך לחם עני ויהיה לחם ענג, והרי בארנו, ויתברך) שֻׁלְחָנוֹ שֶׁל הָאָדָם, שֶׁיִּמָּצֵא בוֹ מָזוֹן תָּמִיד.</p>"],[9522011506,"<p>קָמוּ כֻלָּם וְנָשְׁקוּ יָדוֹ. אָמְרוּ, בָּרוּךְ הָרַחֲמָן שֶׁנִּכְנַסְנוּ לְכָאן וְשָׁמַעְנוּ דְבָרִים אֵלּוּ. יָצְאוּ מִן הַמְּעָרָה וְהָלְכוּ. כְּשֶׁנִּכְנְסוּ לָעִיר, רָאוּ קְבוּצַת אֲנָשִׁים שֶׁמֵּתוּ, שֶׁנָּפַל עֲלֵיהֶם בַּיִת. יָשְׁבוּ, וְרָאוּ שֶׁסּוֹפְדִים לְאוֹתָם שֶׁמֵּתוּ עִם אוֹתָם הָרוֹמָאִים.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, וַיָּבֹאוּ עַד גֹּרֶן הָאָטָד, מַה זֶּה גֹּרֶן הָאָטָד? אֶלָּא כָּאן רָמוּז שִׁלְטוֹן מִצְרַיִם שֶׁיָּעֳבַר. גֹּרֶן הָאָטָד - זֶה מְמֻנֵּה הַשִּׁלְטוֹן שֶׁל מִצְרַיִם שֶׁיָּעֲבַר מִלִּפְנֵי שִׁלְטוֹן יִשְׂרָאֵל, שֶׁהֲרֵי רָאוּ (גרן), כְּמוֹ שֶׁנֶּאֱמַר (מלכים א כב) מְלֻבָּשִׁים בְּגָדִים בְּגֹרֶן. וְעַל זֶה וַיִּסְפְּדוּ שָׁם מִסְפֵּד גָּדוֹל וְכָבֵד מְאֹד וְגוֹ'.</p>\n<p>עַל כֵּן קָרָא שְׁמָהּ אָבֵל מִצְרָיִם עַד הַיּוֹם הַזֶּה, שֶׁוַּדַּאי הָיָה מִמִּצְרַיִם. אַף כָּאן לֹא שֶׁל יְהוּדִים הֵם אֵלֶּה בּוֹכִים, אַף עַל גַּב שֶׁמֵּתוּ בוֹ יְהוּדִים, וְאֵלֶּה יְהוּדִים, שֶׁאִלְמָלֵא הָיוּ יְהוּדִים לֹא מֵתוּ, וְכֵיוָן שֶׁמֵּתוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַפֵּר עַל עֲווֹנוֹתֵיהֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה, שֶׁיַּעֲקֹב, אַף עַל גַּב שֶׁיָּצְאָה נִשְׁמָתוֹ בְּמִצְרַיִם, לֹא יָצְאָה בְּרָשׁוּת אַחֶרֶת, מָה הַטַּעַם? כְּמוֹ שֶׁנִּתְבָּאֵר, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם לֹא הָיְתָה מִטָּה שְׁלֵמָה כְּמוֹ מִטָּתוֹ שֶׁל יַעֲקֹב. בְּשָׁעָה שֶׁהָיָה עוֹלֶה מִן הָעוֹלָם, נִשְׁמָתוֹ מִיָּד נִקְשְׁרָה לִמְקוֹמָהּ, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522011507,"<p>בֹּא רְאֵה, כְּשֶׁהָיָה יַעֲקֹב נִכְנָס לַמְּעָרָה, נִמְצְאוּ בַּמְּעָרָה כָּל הָרֵיחוֹת שֶׁל גַּן עֵדֶן, וְהַמְּעָרָה הֶעֶלְתָה אוֹר, וְנֵר אֶחָד דּוֹלֵק. וּכְשֶׁנִּכְנְסוּ הָאָבוֹת לְיַעֲקֹב לְמִצְרַיִם לְהִמָּצֵא עִמּוֹ, עָלָה אוֹר הַנֵּר. כֵּיוָן שֶׁנִּכְנַס יַעֲקֹב לַמְּעָרָה, חָזַר הַנֵּר לִמְקוֹמוֹ, וְאָז הִשְׁתַּלְּמָה הַמְּעָרָה מִכָּל מַה שֶּׁצָּרִיךְ.</p>\n<p>וְעַד יְמֵי הָעוֹלָם לֹא קִבְּלָה הַמְּעָרָה אִישׁ אַחֵר וְלֹא תְקַבֵּל, וּנְשָׁמוֹת שֶׁזּוֹכוֹת עוֹבְרוֹת לִפְנֵיהֶם בְּבֵית הַמְּעָרָה, כְּדֵי שֶׁיִּתְעוֹרְרוּ וְיִרְאוּ אֶת הַזֶּרַע שֶׁהִשְׁאִירוּ בָּעוֹלָם, וְיִשְׂמְחוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר רַבִּי אַבָּא, חֲנִיטָה שֶׁל יַעֲקֹב מַה הִיא? אָמַר לוֹ, לֵךְ שְׁאַל אֶת הָרוֹפֵא.</p>\n<p>בֹּא רְאֵה, כָּתוּב וַיְצַו יוֹסֵף אֶת עֲבָדָיו אֶת הָרֹפְאִים לַחֲנֹט אֶת אָבִיו וַיַּחַנְטוּ הָרֹפְאִים אֶת יִשְׂרָאֵל. הֲתַעֲלֶה עַל דַּעְתְּךְ שֶׁחֲנִיטָה זוֹ הָיְתָה כְּמוֹ שֶׁל שְׁאָר בְּנֵי אָדָם? אִם תֹּאמַר שֶׁבִּשְׁבִיל הַדֶּרֶךְ הוּא שֶׁעָשׂוּ, הֲרֵי כָּתוּב וַיָּמָת יוֹסֵף בֶּן וְגוֹ' וַיִּישֶׂם בָּאָרוֹן בְּמִצְרָיִם, הֲרֵי לֹא הָלְכוּ עִמּוֹ בַּדֶּרֶךְ, שֶׁהֲרֵי שָׁם נִקְבַּר, וְכָתוּב וַיַּחַנְטוּ אֹתוֹ?</p>\n<p>אֶלָּא הֵם דַּרְכֵי הַמְּלָכִים, כְּדֵי לְהַעֲמִיד אֶת גּוּפָם חוֹנְטִים אוֹתָם בְּשֶׁמֶן מִשְׁחָה, עֶלְיוֹן עַל כָּל הַשְּׁמָנִים, מְעֹרָב בִּבְשָׂמִים, וְשׁוֹאֲבִים אוֹתוֹ לַגּוּף יוֹם אַחַר יוֹם בְּאוֹתוֹ שֶׁמֶן טוֹב אַרְבָּעִים יוֹם, שֶׁכָּתוּב וַיִּמְלְאוּ לוֹ אַרְבָּעִים יוֹם כִּי כֵּן יִמְלְאוּ יְמֵי הַחֲנֻטִים. אַחַר שֶׁזֶּה הֻשְׁלַם, עוֹמֵד הַגּוּף שָׁלֵם זְמַן רַב.</p>\n<p>מִשּׁוּם שֶׁכָּל אוֹתָהּ אֶרֶץ כְּנַעַן וְאֶרֶץ מִצְרַיִם מְכַלּוֹת וּמַרְקִיבוֹת אֶת הַגּוּף בִּזְמַן קָצָר מִכָּל שְׁאָר הָאֲרָצוֹת, וּבִשְׁבִיל לְקַיֵּם אֶת הַגּוּף עוֹשִׂים אֶת זֶה, וְעוֹשִׂים חֲנִיטָה זוֹ מִבִּפְנִים וּמִבַּחוּץ. מִתּוֹךְ שֶׁשָּׂמִים אוֹתוֹ שֶׁמֶן עַל הַטַּבּוּר, הוּא נִשְׁאָב לִפְנִים מִן הַטַּבּוּר, וְנִשְׁאָב לְמֵעָיו, וּמַעֲמִיד אֶת הַגּוּף מִבִּפְנִים וּמִבַּחוּץ זְמַן רַב.</p>"],[9522011508,"<p>וְיַעָקֹב כָּךְ הָיָה בְּקִיּוּם הַגּוּף, וְכָךְ צָרִיךְ, שֶׁגּוּף הָאָבוֹת הוּא, וְהָיָה בְּקִיּוּם בַּגּוּף וָנֶפֶשׁ. כְּמוֹ זֶה לְיוֹסֵף שֶׁהוּא דֻּגְמַת הַגּוּף, וְהוּא בְּקִיּוּם שֶׁל גּוּף וָנֶפֶשׁ. בְּקִיּוּם הַגּוּף, שֶׁכָּתוּב וַיַּחַנְטוּ אֹתוֹ. וּבְקִיּוּם הַנֶּפֶשׁ, שֶׁכָּתוּב וַיִּישֶׂם בָּאָרוֹן בְּמִצְרָיִם.</p>\n<p>וְשָׁנִינוּ, לְשֵׁם מָה שְׁנֵי יוֹדִי\"ם? אֶלָּא יוֹסֵף שָׁמַר אֶת הַבְּרִית לְמַטָּה, וְשָׁמְרוּ אוֹתָהּ הַבְּרִית שֶׁלְּמַעְלָה. כְּשֶׁהִסְתַּלֵּק מֵהָעוֹלָם, הוּשַׂם בִּשְׁנֵי אֲרוֹנוֹת, (מקום) בָּאָרוֹן לְמַטָּה וּבָאָרוֹן לְמַעְלָה. אָרוֹן שֶׁלְּמַעְלָה מַהוּ? אֶלָּא, כְּמוֹ שֶׁנֶּאֱמַר (יהושע ג) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ, שֶׁאָרוֹן שֶׁלְּמַעְלָה נִקְרָא אֲרוֹן הַבְּרִית, שֶׁהֲרֵי לֹא יוֹרֵשׁ אוֹתוֹ אֶלָּא מִי שֶׁשָּׁמַר בְּרִית, וּמִשּׁוּם שֶׁיּוֹסֵף שָׁמַר אֶת הַבְּרִית, הוּשַׂם בִּשְׁנֵי אֲרוֹנוֹת.</p>\n<p>וַיִּישֶׂם בָּאָרוֹן בְּמִצְרָיִם, כָּךְ זֶה וַדַּאי. וְהַפָּסוּק מוֹכִיחַ סוֹד אַחֵר, שֶׁאַף עַל גַּב שֶׁיָּצְאָה נִשְׁמָתוֹ בְּרָשׁוּת אַחֶרֶת, נִקְשַׁר בַּשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב וַיִּישֶׂם בָּאָרוֹן, לְמַעְלָה וּלְמַטָּה, מִשּׁוּם שֶׁהָיָה צַדִּיק, שֶׁכָּל צַדִּיק יוֹרֵשׁ אֶרֶץ הַקְּדוֹשָׁה הָעֶלְיוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011509,"<p>וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב אִישׁ וּבֵיתוֹ בָּאוּ (שמות א) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזהַר הָרָקִיעַ וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד (דניאל יב). וְהַמַּשְׂכִּלִים - אֵלּוּ הֵם שֶׁמִּסְתַּכְּלִים בְּסוֹד הַחָכְמָה (נ\"א יזהרו, שנוצצים בסוד החכמה). יַזְהִרוּ - מְאִירִים וְנוֹצְצִים בְּזִיו הַחָכְמָה הָעֶלְיוֹנָה. כְּזֹהַר - אוֹר וְהִתְנוֹצְצוּת שֶׁמֵּאִיר שֶׁיּוֹצֵא מֵעֵדֶן. וְזֶה סוֹד נִסְתָּר שֶׁנִּקְרָא הָרָקִיעַ, בּוֹ עוֹמְדִים כּוֹכָבִים וּמַזָּלוֹת, שֶׁמֶשׁ וּלְבָנָה, וְכָל אוֹתָם מְאוֹרוֹת שֶׁל אוֹר.</p>\n<p>זֹהַר הָרָקִיעַ הַזֶּה מֵאִיר בְּאוֹר עַל הַגָּן. וְעֵץ הַחַיִּים עוֹמֵד בְּאֶמְצַע הַגָּן, שֶׁעֲנָפָיו מְכַסִּים (עליה) (על) כָּל אוֹתָם דְּיוֹקְנָאוֹת וְעֵצִים וּבְשָׂמִים שֶׁבַּגָּן בְּכֵלִים כְּשֵׁרִים. וּמִסְתּוֹפְפִים תַּחְתָּיו כָּל חַיּוֹת הַשָּׂדֶה, וְכָל צִפֳּרֵי הַשָּׁמַיִם דָּרִים תַּחַת אוֹתָם הָעֲנָפִים.</p>\n<p>זֹהַר פְּרִי הָאִילָן נוֹתֵן חַיִּים לַכֹּל, קִיּוּמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. הַצַּד הָאַחֵר אֵינוֹ שָׁרוּי בּוֹ, אֶלָּא רַק צַד הַקְּדֻשָּׁה. אַשְׁרֵי חֶלְקָם שֶׁל אֵלֶּה שֶׁטּוֹעֲמִים מִמֶּנּוּ, הֵם עוֹמְדִים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. אֵלֶּה נִקְרָאִים מַשְׂכִּילִים וְצַדִּיקִים וְזוֹכִים בָּעוֹלָם הַזֶּה, וְחַיִּים לָעוֹלָם הַבָּא.</p>\n<p>זֹהַר הָעֵץ הַזֶּה זָקוּף לְמַעְלָה לְמַעְלָה. חֲמֵשׁ מֵאוֹת פַּרְסָאוֹת הִלּוּכוֹ, הוּא שִׁשִּׁים רִבּוֹא בְּהִתְפַּשְּׁטוּתוֹ. בָּעֵץ הַזֶּה קַיָּם זֹהַר אֶחָד שֶׁכָּל הַגְּוָנִים קַיָּמִים בּוֹ הֵם גְּוָנִים שֶׁעוֹלִים וְיוֹרְדִים, לֹא מִתְיַשְּׁבִים בְּמָקוֹם אַחֵר פְּרָט לְאוֹתוֹ הָאִילָן.</p>\n<p>כְּשֶׁיּוֹצְאִים מִמֶּנּוּ לְהֵרָאוֹת בְּתוֹךְ זֹהַר שֶׁלֹּא מֵאִיר, מִתְיַשְּׁבִים וְלֹא מִתְיַשְּׁבִים, עוֹמְדִים וְלֹא עוֹמְדִים, מִשּׁוּם שֶׁלֹּא מִתְיַשְּׁבִים בְּמָקוֹם אַחֵר. מֵעֵץ זֶה יוֹצְאִים שְׁנֵים עָשָׂר שְׁבָטִים שֶׁמְּתֻחָמִים בּוֹ, וְהֵם יוֹרְדִים בַּזֹּהַר הַזֶּה שֶׁלֹּא מֵאִיר לְתוֹךְ גָּלוּת מִצְרַיִם בְּכַמָּה מַחֲנוֹת עֶלְיוֹנִים. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל וְגוֹ'.</p>"],[9522011510,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) הָיֹה הָיָה דְבַר ה'. הָיֹה הָיָה פַּעֲמַיִם לְשֵׁם מָה? וְעוֹד יֵשׁ לִשְׁאֹל, אִם יְחֶזְקֵאל הַנָּבִיא נֶאֱמָן הָיָה, לָמָּה גִּלָּה כָּל מַה שֶּׁרָאָה? מִי שֶׁהַמֶּלֶךְ מַכְנִיס אוֹתוֹ לְהֵיכָלוֹ, יֵשׁ לוֹ לְגַלּוֹת סוֹדוֹת שֶׁרָאָה? אֶלָּא וַדַּאי שֶׁיְּחֶזְקֵאל הָיָה נָבִיא נֶאֱמָן, וְכָל מַה שֶּׁרָאָה הוּא רָאָה בֶּאֱמוּנָה, וּבִרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא גִּלָּה כָּל מַה שֶּׁגִּלָּה, וְהַכֹּל הֻצְרַךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, מִי שֶׁרָגִיל לִסְבֹּל צַעַר, אַף עַל גַּב שֶׁבָּא לְפִי שָׁעָה צַעַר, סוֹבֵל מַשָּׂאוֹ וְלֹא חוֹשֵׁשׁ. אֲבָל מִי שֶׁלֹּא רָגִיל בְּצַעַר, וְכָל יָמָיו הָיָה בְּתַפְנוּקִים וְעִדּוּנִים, וּבָא לוֹ צַעַר - זֶהוּ צַעַר שָׁלֵם, וְעַל זֶה צָרִיךְ לִבְכּוֹת.</p>\n<p>כָּךָ יִשְׂרָאֵל, כְּשֶׁיָּרְדוּ לְמִצְרַיִם הָיוּ רְגִילִים בְּצַעַר, שֶׁהֲרֵי כָּל יְמֵי אוֹתוֹ אֲבִיהֶם הַצַּדִּיק הָיוּ בְצַעַר, וְלָכֵן סָבְלוּ אֶת הַגָּלוּת כָּרָאוּי. אֲבָל גָּלוּת בָּבֶל הַהִיא הָיְתָה צַעַר שָׁלֵם, אוֹתוֹ הַצַּעַר שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים בָּכוּ עָלָיו.</p>\n<p>עָלְיוֹנִים, שֶׁכָּתוּב (ישעיה לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה וְגוֹ'. תַּחְתּוֹנִים, שֶׁכָּתוּב (תהלים קלז) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ וְגוֹ', וְכֻלָּם בָּכוּ עַל גָּלוּת בָּבֶל. מָה הַטַּעַם? כִּי הָיוּ בְּתַפְנוּקֵי מְלָכִים, שֶׁכָּתוּב (איכה ד) בְּנֵי צִיּוֹן הַיְקָרִים וְגוֹ'.</p>\n<p>(ששנינו, אמר רבי יצחק, מהו שכתוב (ירמיה ט) על ההרים אשא בכי ונהי? אלא אלה הם הרים רמים של העולמים. ומי הם אותם הרים רמים? אלו בני ציון היקרים המסלאים בפז.) וְעַכְשָׁו הָיוּ יוֹרְדִים לַגָּלוּת עִם רֵחַיִם עַל צַוָּארָם, וִידֵיהֶם מְהֻדָּקוֹת לְאָחוֹר. וְכַאֲשֶׁר (נכנסו) לְגָלוּת בָּבֶל, חָשְׁבוּ שֶׁאֵין לָהֶם קִיּוּם לְעוֹלָמִים, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עָזַב אוֹתָם, וְלֹא יַשְׁגִּיחַ בָּהֶם לְעוֹלָמִים.</p>\n<p>וְשָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתָהּ שָׁעָה קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הַפָּמַלְיָא שֶׁלּוֹ, וְכָל הַמֶּרְכָּבוֹת הַקְּדוֹשׁוֹת, וְכָל חֵילוֹתָיו וּמַחֲנוֹתָיו וּגְדוֹלָיו וְכָל חֵיל הַשָּׁמַיִם, וְאָמַר לָהֶם: מָה אַתֶּם עוֹשִׂים כָּאן? וּמַה בָּנַי אֲהוּבַי בְּגָלוּת בָּבֶל, וְאַתֶּם כָּאן? קוּמוּ רְדוּ כֻּלְּכֶם לְבָבֶל, וַאֲנִי עִמָּכֶם. זֶהוּ שֶׁכָּתוּב (ישעיה מג) כֹּה אָמַר ה' לְמַעַנְכֶם שִׁלַּחְתִּי בָבֶלָה וְגוֹ'. לְמַעַנְכֶם שִׁלַּחְתִּי בָבֶלָה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהוֹרַדְתִּי בָרִיחִים כֻּלָּם - אֵלֶּה כָּל הַמֶּרְכָּבוֹת וְהַמַּחֲנוֹת הָעֶלְיוֹנִים.</p>\n<p>כְּשֶׁיָּרְדוּ לְבָבֶל, נִפְתְּחוּ הַשָּׁמַיִם, וְשָׁרְתָה נְבוּאָה קְדוֹשָׁה עַל יְחֶזְקֵאל, וְרָאָה כָּל מַה שֶּׁרָאָה, וְאָמַר לָהֶם לְיִשְׂרָאֵל: הֲרֵי אֲדוֹנְכֶם כָּאן, וְכָל חֵילוֹת הַשָּׁמַיִם וּמַרְכְּבוֹתָיו שֶׁבָּאוּ לָדוּר בֵּינֵיכֶם. לֹא הֶאֱמִינוּ לוֹ, עַד שֶׁהִצְטָרֵךְ לְגַלּוֹת כָּל מַה שֶּׁרָאָה, וָאֵרֶא כָּךְ, וָאֵרֶא כָּךְ. וְאִם גִּלָּה יוֹתֵר - כָּל מַה שֶּׁגִּלָּה הֻצְרַךְ. כֵּיוָן שֶׁרָאוּ כָּךְ יִשְׂרָאֵל, שָׂמְחוּ. וּכְשֶׁשָּׁמְעוּ דְבָרִים מִפִּי יְחֶזְקֵאל, לֹא חָשְׁשׁוּ עַל גָּלוּתָם כְּלָל, שֶׁהֲרֵי יָדְעוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא עָזַב אוֹתָם, וְכָל מַה שֶּׁגִּלָּה - גִּלָּה בִּרְשׁוּת.</p>\n<p>וְשָׁנִינוּ, בְּכָל מָקוֹם שֶׁגָּלוּ יִשְׂרָאֵל, שָׁם הַשְּׁכִינָה גָּלְתָה עִמָּהֶם. וְכָאן בְּגָלוּת מִצְרַיִם מַה כָּתוּב? וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל וְגוֹ'. כֵּיוָן שֶׁכָּתוּב בְּנֵי יִשְׂרָאֵל, מַה זֶּה אֵת יַעֲקֹב? הַבָּאִים אִתּוֹ הִצְטָרֵךְ לוֹמַר! אֶלָּא, אֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל, הֵם אוֹתָם מֶרְכָּבוֹת וּמַחֲנוֹת עֶלְיוֹנִים שֶׁיָּרְדוּ עִם יַעֲקֹב עִם הַשְּׁכִינָה לְגָלוּת מִצְרַיִם.</p>"],[9522011511,"<p>וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב אִישׁ וּבֵיתוֹ בָּאוּ. רַבִּי חִיָּיא פָּתַח, (שיר ד) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי מִלְּבָנוֹן תָּבוֹאִי תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה מֵרֹאשׁ שְׂנִיר וְחֶרְמוֹן מִמְּעֹנוֹת אֲרָיוֹת מֵהַרְרֵי נְמֵרִים. פָּסוּק זֶה נֶאֱמַר עַל כְּנֶסֶת יִשְׂרָאֵל. בְּשָׁעָה שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם וְקָרְבוּ לְהַר סִינַי לְקַבֵל תּוֹרָה, אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אִתִּי מִלְּבָנוֹן - מֵאוֹתוֹ עִדּוּן הָעֶלְיוֹן בָּאָה. כַּלָּה - שְׁלֵמָה, כְּמוֹ הַלְּבָנָה כְּשֶׁמִּשְׁתַּלֶּמֶת מֵהַשֶּׁמֶשׁ בְּכָל אוֹר וְהִתְנוֹצְצוּת. אִתִּי מִלְּבָנוֹן תָּבוֹאִי - כְּדֵי שֶׁיְּקַבְּלוּ בָנַיִךְ תּוֹרָה.</p>\n<p>תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה. תָּשׁוּרִי - כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ט) וּתְשׁוּרָה אֵין לְהָבִיא. תְּקַבְּלִי תִקְרֹבֶת עַל בָּנַיִךְ. מֵרֹאשׁ אֲמָנָה - מֵהָרֵאשִׁית, כְּשֶׁנִּכְנְסוּ לָאֱמוּנָה הָעֶלְיוֹנָה וְאָמְרוּ (שמות כד) כֹּל אֲשֶׁר דִּבֶּר ה' נַעֲשֶׂה וְנִשְׁמָע, וְהָיוּ בְּמִשְׁקָל אֶחָד כְּמַלְאָכִים עֶלְיוֹנִים, שֶׁכָּךְ כָּתוּב בָּהֶם, (תהלים קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ. אָז קִבְּלָה כְּנֶסֶת יִשְׂרָאֵל תְּשׁוּרָה.</p>\n<p>מֵרֹאשׁ שְׂנִיר וְחֶרְמוֹן - זֶה הַר סִינַי, שֶׁקָּרְבוּ אֵלָיו וְהִתְיַצְּבוּ תַחְתָּיו, שֶׁכָּתוּב (שמות יט) וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר. מִמְּעֹנוֹת אֲרָיוֹת - אֵלּוּ בְּנֵי שֵׂעִיר שֶׁהִזְמִינָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַבֵּל תּוֹרָה וְלֹא רָצוּ לְקַבְּלָהּ. מֵהַרְרֵי נְמֵרִים - אֵלּוּ בְּנֵי יִשְׁמָעֵאל, שֶׁכָּתוּב (דברים לג) ה' מִסִּינַי בָּא וְזָרַח מִשֵּׂעִיר לָמוֹ הוֹפִיעַ מֵהַר פָּארָן וְאָתָה מֵרִבֲבֹת קֹדֶשׁ.</p>\n<p>מַה זֶּה וְאָתָה מֵרִבֲבת קֹדֶשׁ? שֶׁשָּׁנִינוּ, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת תּוֹרָה לְיִשְׂרָאֵל, בָּאוּ מַחֲנוֹת שֶׁל מַלְאָכִים עֶלְיוֹנִים. פָּתְחוּ וְאָמְרוּ, (תהלים ח) ה' אֲדנֵנוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ אֲשֶׁר תְּנָה הוֹדְךְ עַל הַשָּׁמָיִם, וְרָצוּ שֶׁתּוֹרָה תִנָּתֵן לָהֶם.</p>\n<p>אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי יֵשׁ בָּכֶם מָוֶת? שֶׁכָּתוּב (במדבר יט) אָדָם כִּי יָמוּת בְּאֹהֶל. (דברים כא) וְכִי יִהְיֶה בְאִישׁ חֵטְא מִשְׁפַּט מָוֶת וְהוּמָת. יֵשׁ בֵּינֵיכֶם חֵטְא? וְכִי אַתֶּם צְרִיכִים דִּינִים? יֵשׁ בֵּינֵיהֶם גָּזֵל אוֹ גְנֵבָה? שֶׁכָּתוּב (שמות כ) לֹא תִגְנֹב. יֵשׁ בֵּינֵיכֶם נָשִׁים? שֶׁכָּתוּב לֹא תִנְאָף. יֵשׁ בֵּינֵיכֶם שֶׁקֶר? שֶׁכָּתוּב לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר. יֵשׁ בֵּינֵיכֶם חֶמְדָּה? שֶׁכָּתוּב לֹא תַחְמֹד. אָז לְשֵׁם מָה אַתֶּם רוֹצִים תּוֹרָה? מִיָּד פָּתְחוּ וְאָמְרוּ, (תהלים ח) ה' אדננו מה אדיר שמך בכל הארץ. ואלו אשר תנה הודך על השמים לא כתוב. ועל כך ואתה מרבבת קדש, אז מימינו אש דת למו.</p>\n<p>רַבִּי יוֹסֵי בֵּאֵר פָּסוּק זֶה כְּשֶׁיָּרְדָה שְׁכִינָה לְגָלוּת מִצְרַיִם, וְרַבִּי שִׁמְעוֹן אָמַר, פָּסוּק זֶה עַל סוֹד יִחוּד הָאֱמוּנָה נֶאֱמַר. אִתִּי מִלְּבָנוֹן כַּלָּה, הַקּוֹל אָמַר לַדִּבּוּר אִתִּי, מִשּׁוּם שֶׁהֲרֵי קוֹל בָּא לַדִּבּוּר, וּמַנְהִיגוֹ עִמּוֹ לִהְיוֹת כְּאֶחָד בְּלִי פֵרוּד כְּלָל, מִשּׁוּם שֶׁקּוֹל הוּא כְּלָל, דִּבּוּר הוּא פְּרָט, וְלָכֵן כְּלָל הִצְטָרֵךְ לַפְּרָט, וּפְרָט הִצְטָרֵךְ לַכְּלָל, שֶׁהֲרֵי אֵין קוֹל בְּלִי דִבּוּר, וְאֵין דִּבּוּר בְּלִי קוֹל. וְעַל זֶה אִתִּי מִלְּבָנוֹן כַּלָּה וְגוֹ', שֶׁעִקַּר שְׁנֵיהֶם בָּאִים מִלְּבָנוֹן.</p>\n<p>תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה - זֶהוּ גָרוֹן שֶׁמִּשָּׁם יוֹצֵאת רוּחַ לְהַשְׁלִים לַכֹּל, (כלה) מִסּוֹד הַלְּבָנוֹן הַנִּסְתָּר וְהַגָּנוּז. מֵרֹאשׁ שְׂנִיר וְחֶרְמוֹן - זוֹהִי לָשׁוֹן רֹאשׁ וְאֶמְצַע, שֶׁחוֹתֶכֶת אֶת הַדִּבּוּר. מִמְּעֹנוֹת אֲרָיוֹת - אֵלֶּה הֵם שִׁנַּיִם. מֵהַרְרֵי נְמֵרִים - אֵלֶּה הֵם שְׂפָתַיִם, הַשְּׁלֵמוּת שֶׁבָּהֶם נִשְׁלָם הַדִּבּוּר.</p>"],[9522011512,"<p>וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל. רַבִּי חִיָּיא פָּתַח, (משלי כג) אַל תִּלְחַם אֶת לֶחֶם רַע עַיִן וְאַל תִּתְאָו לְמַטְעַמֹּתָיו. אַל תִּלְחַם אֶת לֶחֶם רַע עַיִן - מִשּׁוּם שֶׁלֶּחֶם אוֹ הֲנָאָה מֵאוֹתוֹ אִישׁ שֶׁהוּא רַע עַיִן, אֵינוֹ כְּדַאי לֶאֱכֹל וְלֵהָנוֹת מִמֶּנּוּ. שֶׁאִלּוּ כְּשֶׁיָּרְדוּ יִשְׂרָאֵל לְמִצְרַיִם לֹא טָעֲמוּ לֶחֶם שֶׁל הַמִּצְרַיִם, לֹא הָיוּ נִשְׁאָרִים בַּגָּלוּת, וְלֹא הָיוּ מְצִיקִים לָהֶם הַמִּצְרִים.</p>\n<p>אָמַר לוֹ רַבִּי יִצְחָק, וַהֲרֵי נִגְזְרָה גְזֵרָה? אָמַר לוֹ, הַכֹּל הוּא כָּרָאוּי, שֶׁהֲרֵי לֹא נִגְזַר דַּוְקָא בְּמִצְרַיִם, שֶׁהֲרֵי לֹא כָתוּב כִּי גֵר יִהְיֶה זַרְעֲךְ בְּאֶרֶץ מִצְרַיִם, אֶלָּא (בראשית טו) בְּאֶרֶץ לֹא לָהֶם, וַאֲפִלּוּ בְּאֶרֶץ אַחֶרֶת.</p>\n<p>אָמַר רַבִּי יִצְחָק, מִי שֶׁהוּא בַּעַל נֶפֶשׁ, (לא יאכל עם אדם) שֶׁמַּאֲכָלוֹ יוֹתֵר מֵאֲשֶׁר שְׁאָר בְּנֵי אָדָם, אוֹ מִי שֶׁהוֹלֵךְ אַחַר מֵעָיו, אִם יִפְגֹּשׁ בְּאוֹתוֹ רַע עַיִן, יִשְׁחַט עַצְמוֹ וְלֹא יֹאכַל מִלַּחְמוֹ, שֶׁאֵין לֶחֶם רַע בָּעוֹלָם חוּץ מֵאוֹתוֹ לֶחֶם שֶׁל בַּעַל עַיִן הָרָע. מַה כָּתוּב? כִּי לֹא יוּכְלוּן הַמִּצְרִים לֶאֱכֹל אֶת הָעִבְרִים לֶחֶם כִּי תוֹעֵבָה הִיא לְמִצְרָיִם. הֲרֵי לְךְ לֶחֶם שֶׁל רַע עַיִן.</p>"],[9522011513,"<p>שְׁלשָה הֵם שֶׁדּוֹחִים שְׁכִינָה מִן הָעוֹלָם וְגוֹרְמִים שֶׁדִּיּוּרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יִהְיֶה בָּעוֹלָם וּבְנֵי אָדָם צוֹוְחִים וְלֹא נִשְׁמָע קוֹלָם, וְאֵלֶּה הֵם: מִי שֶׁשּׁוֹכֵב עִם נִדָּה, מִשּׁוּם שֶׁאֵין טֻמְאָה חֲזָקָה בָּעוֹלָם חוּץ מִטֻּמְאַת הַנִּדָּה, וְטֻמְאַת הַנִּדָּה קָשָׁה מִכָּל טֻמְאָה בָּעוֹלָם. הוּא נִטְמָא, וְכָל הַמִּתְקָרְבִים אֵלָיו נִטְמָאִים עִמּוֹ. בְּכָל מָקוֹם שֶׁהוֹלְכִים, נִדְחֵית שְׁכִינָה מִלִּפְנֵיהֶם.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁגּוֹרֵם צָרוֹת רָעוֹת עַל עַצְמוֹ וְעַל אוֹתוֹ זֶרַע שֶׁיּוֹלִיד. שֶׁכֵּיוָן שֶׁיִּקְרַב אָדָם לְנִדָּה, אוֹתָהּ טֻמְאָה קוֹפֶצֶת עָלָיו וְנִשְׁאֶרֶת בְּכָל אֵיבָרָיו, אוֹתוֹ זֶרַע שֶׁיּוֹלִיד בְּאוֹתָהּ שָׁעָה, (טמאים) מוֹשְׁכִים עָלָיו רוּחַ טֻמְאָה, וְכָל יָמָיו יִהְיֶה בְטֻמְאָה, שֶׁהֲרֵי הַבִּנְיָן וְהַיְסוֹד שֶׁלּוֹ הוּא בְּטֻמְאָה רַבָּה וְתַקִּיפָה מִכָּל טֻמְאָה שֶׁבָּעוֹלָם, שֶׁמִּיָּד שֶׁקָּרֵב אָדָם לְנִדָּה, אוֹתָהּ טֻמְאָה קוֹפֶצֶת עָלָיו, שֶׁכָּתוּב (ויקרא ט) וּתְהִי נִדָּתָהּ עָלָיו.</p>\n<p>מִי שֶׁשּׁוֹכֵב עִם בַּת אֵל נֵכָר, שֶׁמַּכְנִיס בְּרִית קֹדֶשׁ וְאוֹת הַבְּרִית לְרָשׁוּת אַחֶרֶת, שֶׁכָּתוּב וּבָעַל בַּת אֵל נֵכָר, וְשָׁנִינוּ שֶׁאֵין קִנְאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא חוּץ מִקִּנְאָה שֶׁל בְּרִית קֹדֶשׁ, שֶׁהִיא בְּרִית שֶׁל הַשֵּׁם הַקָּדוֹשׁ וְסוֹד הָאֱמוּנָה. מַה כָּתוּב? (במדבר כה) וַיָּחֶל הָעָם לִזְנוֹת אֶל בְּנוֹת מוֹאָב. מִיָּד - וַיִּחַר אַף ה' בְּיִשְׂרָאֵל.</p>\n<p>רָאשֵׁי הָעָם שֶׁיּוֹדְעִים וְלֹא מוֹחִים בִּידֵיהֶם, נֶעֱנָשִׁים בַּתְּחִלָּה, שֶׁכָּתוּב קַח אֶת כָּל רָאשֵׁי הָעָם וְהוֹקַע אוֹתָם לַה' נֶגֶד הַשָּׁמֶשׁ. רַבִּי אַבָּא אָמַר, מַה זֶּה נֶגֶד הַשָּׁמֶשׁ? נֶגֶד הַבְּרִית שֶׁנִּקְרֵאת שֶׁמֶשׁ, וְעָלֶיהָ נֶאֱמַר (תהלים פד) כִּי שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים. שֶׁמֶשׁ וּמָגֵן - זוֹ בְּרִית קֹדֶשׁ. מַה שֶּׁמֶשׁ זוֹרֵחַ וּמֵאִיר לָעוֹלָם, אַף כָּךְ בְּרִית קֹדֶשׁ זוֹרֵחַ וּמֵאִיר אֶת גּוּף הָאָדָם. מָגֵן - מַה מָּגֵן הוּא כְּדֵי לְהָגֵן עַל הָאָדָם, אַף כָּךְ בְּרִית קֹדֶשׁ מְגִנָּה עַל הָאָדָם, וּמִי שֶׁשּׁוֹמֵר אוֹתָהּ, אֵין נֶזֶק בָּעוֹלָם שֶׁיּוּכַל לִקְרַב אֵלָיו, וְזֶהוּ נֶגֶד הַשָּׁמֶשׁ.</p>\n<p>רָאשֵׁי הָעָם יִתָּפְסוּ בְּכָל דּוֹר וָדוֹר בְּחֵטְא זֶה, אִם יוֹדְעִים וְלֹא מְקַנְּאִים לוֹ, מִשּׁוּם שֶׁחוֹבָה זוֹ עֲלֵיהֶם לְקַנֵּא לַקָּדוֹשׁ בָּרוּךְ הוּא בַּבְּרִית הַ את, מִי שֶׁמַּכְנִיס קְדֻשָּׁה זוֹ לְרָשׁוּת אַחֶרֶת, עָלָיו כָּתוּב (שמות כ) לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי. לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם כִּי אָנֹכִי ה' אֱלֹהֶיךְ אֵל קַנָּא. וְהַכֹּל קִנְאָה אַחַת. וְלָכֵן נִדְחֵית שְׁכִינָה מִלְּפָנָיו. מִי שֶׁמְּשַׁקֵּר בִּבְרִית קֹדֶשׁ שֶׁחֲתוּמָה בִּבְשַׂר הָאָדָם, כְּאִלּוּ מְשַׁקֵּר בְּשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא. מִי שֶׁמְּשַׁקֵּר בְּחוֹתַם הַמֶּלֶךְ, מְשַׁקֵּר בַּמֶּלֶךְ, וְאֵין לוֹ חֵלֶק בֵּאלֹהֵי יִשְׂרָאֵל אִם לֹא בְּכֹחַ תְּשׁוּבָה מַתְמֶדֶת (יתרה).</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (שמואל א יב) וַיִּשְׁכְּחוּ אֶת ה' אֱלֹהֵיהֶם וְגוֹ'. וַיַּעַזְבוּ אֶת ה'. מַה זֶּה וַיִּשְׁכְּחוּ וַיַּעַזְבוּ? שֶׁדָּחוּ מֵהֶם בְּרִית קֹדֶשׁ, שֶׁמָּלוּ וְלֹא פָרְעוּ, עַד שֶׁבָּאָה דְבוֹרָה וְנִדְּבָה בָּזֶה אֶת כָּל יִשְׂרָאֵל, כְּמוֹ שֶׁכָּתוּב (שופטים ה) בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם בָּרְכוּ ה'.</p>\n<p>מִי שֶׁהוֹרֵג בְּנוֹ, אוֹתוֹ עֻבָּר שֶׁאִשְׁתּוֹ הִתְעַבְּרָה, וְגוֹרֵם לְהָרְגוֹ בְּמֵעֶיהָ, שֶׁסּוֹתֵר בִּנְיָנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֻמָּנוּת שֶׁלּוֹ. יֵשׁ מִי שֶׁהוֹרֵג אָדָם, וְזֶה הוֹרֵג בְּנוֹ.</p>\n<p>שָׁלש רָעוֹת עוֹשֶׂה שֶׁכָּל הָעוֹלָם לֹא יָכוֹל לִסְבֹּל, וְעַל זֶה הָעוֹלָם מִתְמוֹגֵג לְאַט לְאַט, וְלֹא יָדוּעַ לָמָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִסְתַּלֵּק מֵהָעוֹלָם, וְחֶרֶב וְרָעָב וּמָוֶת בָּאִים עַל הָעוֹלָם, וְאֵלֶּה הֵם: הוֹרֵג בְּנוֹ, סוֹתֵר בִּנְיַן הַמֶּלֶךְ. וְדוֹחֶה אֶת הַשְּׁכִינָה, שֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וְלֹא מוֹצֵאת מְנוּחָה, וְעַל (זה) אֵלּוּ רוּחַ (רוחות) הַקֹּדֶשׁ (עושה) בּוֹכָה, וְהָעוֹלָם נִדּוֹן בְּכָל הַדִּינִים הַלָּלוּ. אוֹי לְאוֹתוֹ הָאִישׁ, אוֹי לוֹ! טוֹב לוֹ שֶׁלֹּא נִבְרָא בָּעוֹלָם!</p>\n<p>אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁאַף עַל גַּב שֶׁהָיוּ בְּגָלוּת מִצְרַיִם, נִשְׁמְרוּ מִכָּל שְׁלֹשֶׁת אֵלֶּה - מִנִּדָּה, מִבַּת אֵל נֵכָר, וּמֵהֶרֶג שֶׁל זַרְעָם, וְהִשְׁתַּדְּלוּ בְּפַרְהֶסְיָא בִּפְרִיָּה וּרְבִיָּה. שֶׁאַף עַל גַּב שֶׁנִּגְזְרָה הַגְּזֵרָה כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ, לֹא נִמְצָא בֵינֵיהֶם מִי שֶׁהוֹרֵג עֻבָּר בִּמְעֵי אִשָּׁה, כָּל שֶׁכֵּן אַחַר כָּךְ. וּבִזְכוּת זוֹ יָצְאוּ יִשְׂרָאֵל מֵהַגָּלוּת.</p>\n<p>מִנִּדָּה - שֶׁשָּׁנָה רַבִּי חִיָּיא, מַה שֶּׁכָּתוּב (שמות לח) וַיַּעַשׂ אֵת הַכִּיּוֹר נְחֹשֶׁת וְאֵת כַּנּוֹ נְחֹשֶׁת בְּמַרְאֹת הַצֹבְאֹת. מִפְּנֵי מָה זָכוּ נָשִׁים לָזֶה? מִשּׁוּם שֶׁשָּׁמְרוּ עַצְמָן בְּגָלוּת מִצְרַיִם, שֶׁלְּאַחַר שֶׁנִּטְהֲרוּ הָיוּ בָאוֹת מְקֻשָּׁטוֹת, וּמִסְתַּכְּלוֹת בַּמַּרְאָה בְּבַעְלֵיהֶן, וּמְעוֹרְרוֹת אוֹתָם לִפְרִיָּה וּרְבִיָּה.</p>\n<p>מִבַּת אֵל נֵכָר - שֶׁכָּתוּב יָצְאוּ כָּל צִבְאוֹת ה' וְגוֹ', וְכָתוּב (תהלים קכב) שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל. עֵדוּת לְיִשְׂרָאֵל וַדַּאי. וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל. שִׁבְטֵי בְּנֵי יִשְׂרָאֵל. דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב וְהוּא בֶּן אִישׁ מִצְרִי? הֲרֵי וַדַּאי אֶחָד הָיָה, וּפִרְסְמוֹ הַכָּתוּב, שֶׁכָּתוּב (ויקרא כד) וְהוּא בֶּן אִישׁ מִצְרִי וְגוֹ', וְשֵׁם אִמּוֹ שְׁלֹמִית בַּת דִּבְרִי לְמַטֵּה דָן. פְּרִיָּה וּרְבִיָּה - שֶׁכָּתוּב וּבְנֵי יִשְׂרָאֵל פָּרוּ וַיִּשְׁרְצוּ וַיִּרְבּוּ וְגוֹ'. וּמִכָּל אֵלֶּה נִשְׁמְרוּ יִשְׂרָאֵל. בְּנֵי יִשְׂרָאֵל נִכְנְסוּ - בְּנֵי יִשְׂרָאֵל יָצְאוּ. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל וְגוֹ'.</p>"],[9522011514,"<p>וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל. רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי אֶלְעָזָר לְרַבִּי יוֹסֵי, פְּתַח פִּיךְ וְיָאִירוּ דְבָרֶיךְ. אָמַר לוֹ, נוֹחַ לִפְנֵי מַר שֶׁאֶשְׁאַל דָּבָר אֶחָד שֶׁקָּשֶׁה לִי? הֲרֵי שָׁמַעְתִּי מֵהַמְּנוֹרָה הַקְּדוֹשָׁה שֶׁהָיָה אוֹמֵר, וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל - יִשְׂרָאֵל סָבָא, כָּל אוֹתָם חֲיָלוֹת וּמַחֲנוֹת שֶׁהָיוּ יוֹרְדִים לַגָּלוּת עִם יַעֲקֹב, שֶׁכָּתוּב אֵת יַעֲקֹב. מַה זֶּה שֶׁכָּתוּב אִישׁ וּבֵיתוֹ בָּאוּ? אָמַר לוֹ, וַדַּאי זֶה כָּךְ, אֶלָּא הֲרֵי שָׁנִינוּ, כָּל הַמְקַבֵּל מֵאַחֵר, הוּא בַּיִת לְאוֹתוֹ שֶׁנָּתַן, וְעַל זֶה אִישׁ וּבֵיתוֹ בָּאוּ.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (מלכים א ט) וַיְהִי כְּכַלּוֹת שְׁלֹמֹה לִבְנוֹת אֶת בֵּית ה' וְאֶת בֵּית הַמֶּלֶךְ וְגוֹ'. וְכִי כֵּיוָן שֶׁאָמַר אֶת בֵּית ה', מַה זֶּה וְאֶת בֵּית הַמֶּלֶךְ? אִם בִּשְׁבִיל שְׁלֹמֹה זֶה נֶאֱמַר - לֹא כָּךְ! אֶלָּא בֵּית ה' זֶה בֵּית הַמִּקְדָּשׁ, וְאֶת בֵּית הַמֶּלֶךְ זֶה קֹדֶשׁ הַקְּדָשִׁים.</p>\n<p>בֵּית ה' שֶׁהוּא בֵּית הַמִּקְדָּשׁ, כְּמוֹ עֲזָרוֹת וּלְשָׁכוֹת וּבֵית הָאוּלָם וְהַדְּבִיר, זֶה בֵּית הַמִּקְדָּשׁ, וַדַּאי נִקְרָא בֵּית ה'. בֵּית הַמֶּלֶךְ - זֶה קֹדֶשׁ הַקְּדָשִׁים, שֶׁהוּא הַפְּנִימִי שֶׁל הַכֹּל, הַמֶּלֶךְ סְתָם. מֶלֶךְ זֶה, אַף עַל גַּב שֶׁהוּא מֶלֶךְ עֶלְיוֹן, הוּא נְקֵבָה אֶל נְקֻדָּה הָעֶלְיוֹנָה, נִסְתֶּרֶת הַכֹּל. וְאַף עַל גַּב שֶׁהוּא נְקֵבָה, הוּא זָכָר לַמֶּלֶךְ שֶׁלְּמַטָּה, וְלָכֵן הַכֹּל כְּמוֹ זֶה וְעַל זֶה, תַּחְתּוֹנִים, בְּסוֹד זֶה כָּתוּב בָּהֶם אִישׁ וּבֵיתוֹ בָּאוּ.</p>\n<p>וְאֵלֶּה שְׁמוֹת. רַבִּי (אלעזר) יוֹסֵי פָּתַח וְאָמַר (שיר ד) גַּן נָעוּל אֲחֹתִי כַלָּה גַּל נָעוּל מַעְיָן חָתוּם. גַּן נָעוּל - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא גַּן נָעוּל. שֶׁאָמַר רַבִּי אֶלְעָזָר, מָה הַגָּן הַזֶּה צָרִיךְ לִשְׁמֹר, לַעְדֹּר וּלְהַשְׁקוֹת וְלִזְמֹר - כָּךְ כְּנֶסֶת יִשְׂרָאֵל צְרִיכָה לַעְדֹּר וְלִשְׁמֹר וּלְהַשְׁקוֹת וְלִזְמֹר, וְנִקְרֵאת גַּן, וְנִקְרֵאת כֶּרֶם. מָה הַכֶּרֶם הַזֶּה צָרִיךְ לַעְדֹּר וּלְהַשְׁקוֹת וְלִזְמֹר וְלַחְפֹּר - כָּךְ יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (ישעיה ה) כִּי כֶרֶם ה' צְבָאוֹת בֵּית יִשְׂרָאֵל, וְכָתוּב וַיְעַזְּקֵהוּ וַיְסַקְּלֵהוּ וְגוֹ'.</p>"],[9522011515,"<p>אָמַר רַבִּי שִׁמְעוֹן, אָנוּ פּוֹקְחִים עֵינֵינוּ רוֹאִים, גַּלְגַּלֵּי מֶרְכָּבָה הַקְּדוֹשָׁה נוֹסְעִים בְּמַסְעוֹתֵיהֶם, וְקוֹל שִׁירָה מְבֻשֶּׂמֶת לָאָזְנַיִם, יָפֶה לַלֵּב, עוֹלָה וְיוֹרֶדֶת, הוֹלֶכֶת וְלֹא נוֹסַעַת, מִזְדַּעְזְעִים אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, וּפוֹתְחִים בְּשִׁירָה מִלְּמַטָּה לְמַעְלָה.</p>\n<p>לְקוֹל הַנְּעִימוּת הַזּוֹ עוֹמְדִים מִי שֶׁעוֹמְדִים, וּמִתְכַּנְּסִים בְּהִתְכַּנְּסוּת לְצַד הַיָּמִין, אַרְבַּע מֵאוֹת וַחֲמִשִּׁים אֶלֶף בַּעֲלֵי עֵינַיִם. רוֹאִים וְלֹא רוֹאִים. עוֹמְדִים בְּקִיּוּמָם. שְׁנֵי צְדָדִים אֲחֵרִים מִתְלַבְּנִים (מתהפכים) בִּשְׁבִילָם, וּלְצַד שְׂמֹאל מָאתַיִם וַחֲמִשִּׁים אֶלֶף.</p>\n<p>אוֹתָם בַּעֲלֵי יְבָבָה מְיַבְּבִים וּמְיַלְּלִים מִמְּקוֹם בֵּית מוֹשָׁבָם, פּוֹתְחִים בְּדִין וּמְסַיְּמִים בְּדִין. מְיַבְּבִים שֵׁנִית, וְדִין יוֹשֵׁב, וּסְפָרִים נִפְתָּחִים. בְּאוֹתָהּ שָׁעָה עוֹלֶה בַּעַל הַדִּין שֶׁעוֹמֵד עֲלֵיהֶם, וְיוֹשֵׁב עַל כִּסֵּא דִין, וְשִׁירָה שׁוֹכֶכֶת עַד שֶׁלֹּא יִסְתַּיֵּם הַדִּין.</p>\n<p>סוֹבְבִים בַּעֲלֵי הָעֵינַיִם שֶׁלְּצַד יָמִין, וְעִמָּם שְׁמוֹנָה עָשָׂר אֶלֶף תּוֹקְעִים, וְלֹא מְיַבְּבִים וְלֹא מְיַלְּלִים (ס\"א לא מיללין ולא מיבבין) וּפוֹתְחִים בְּשִׁירָה. מִזְדַּעְזְעִים מָאתַיִם וַחֲמִשִּׁים אֶלֶף בַּעֲלֵי יְבָבָה.</p>\n<p>תּוֹקֵעַ שֵׁנִית וְלֹא מְיַבְּבִים (ולא מיבבים ולא מיללים). נוֹסֵעַ הַפַּטְרוֹן מֵאוֹתוֹ כִסֵּא וְיוֹשֵׁב בְּכִסֵּא הַוַּתְּרָנוּת. בְּאוֹתוֹ זְמַן הָיָה (הוא) מַזְכִּיר שֵׁם קָדוֹשׁ עֶלְיוֹן וְגָדוֹל, שֶׁבְּאוֹתוֹ שֵׁם יֵשׁ חַיִּים לַכֹּל.</p>\n<p>פָּתַח וְאָמַר פַּעַם אַחַת יוֹ\"ד הֵ\"א וָי\"ו הֵ\"א (יו\"ד ה\"א וא\"ו ה\"א), כְּמוֹ שֶׁנֶּאֱמַר (שמות לד) וַיִּקְרָא בְשֵׁם ה'. פּוֹתְחִים כְּבַתְּחִלָּה בַּעֲלֵי גַלְגַּלִּים קְדוֹשִׁים, וְאֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, וְאוֹמְרִים שִׁירָה, מְשַׁבְּחִים וְאוֹמְרִים, בָּרוּךְ כְּבוֹד ה' מִמְּקוֹם בֵּית שְׁכִינָתוֹ.</p>\n<p>בָּא אוֹתוֹ הַגָּן, שֶׁהָיְתָה (שהיא) שְׁמוּרָה בְּמָאתַיִם וַחֲמִשִּׁים עוֹלָמוֹת, הִיא שְׁכִינָה נִכְבָּדָה בְּזִיוָהּ, שֶׁיּוֹצֵאת מִזִּיו לְזִיו, וְזִיוָהּ שׁוֹפֵעַ מִמֶּנָּה לְאַרְבָּעָה צְדָדִים רָאשִׁיִּים לָרִאשׁוֹנִים (לקיום). מֵאוֹתוֹ זִיו יוֹצֵא (נמשך) לְכָל אוֹתָם לְמַטָּה, וְהִיא נִקְרֵאת גַּן עֵדֶן.</p>\n<p>פָּתַח שֵׁנִית אוֹתוֹ זָקֵן, הַפַּטְרוֹן שֶׁל הַכֹּל, וּמַזְכִּיר שְׁמוֹ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, וְכֻלָּם פּוֹתְחִים בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים. מִי רָאָה כָּל הַתַּקִּיפִים הַלָּלוּ, רָמִים שֶׁל רָמִים, תַּקִּיפִים שֶׁל תַּקִּיפִים, מֶרְכָּבוֹת קְדוֹשִׁים, וְשָׁמַיִם וְכָל חֵילֵיהֶם, מִזְדַּעְזְעִים וּמִתְחַלְחֲלִים בְּאֵימָה רַבָּה, מְשַׁבְּחִים אֶת הַשֵּׁם הַקָּדוֹשׁ וְאוֹמְרִים שִׁירָה. אַשְׁרֵיהֶם נִשְׁמוֹת הַצַּדִּיקִים שֶׁהֵם בְּאוֹתוֹ הָעִדּוּן וְיוֹדְעִים אֶת זֶה, עַל זֶה נֶאֱמַר (ירמיה י) מִי לֹא יִירָאֲךְ מֶלֶךְ הַגּוֹיִם כִּי לְךְ יָאָתָה וְגוֹ'.</p>"],[9522011516,"<p>אָמַר רַבִּי שִׁמְעוֹן, כְּשֶׁיָּרְדָה שְׁכִינָה לְמִצְרַיִם, יָרְדָה חַיָּה אַחַת שֶׁשְּׁמָהּ יִשְׂרָאֵל בִּדְיוֹקַן אוֹתוֹ הַזָּקֵן, וְאַרְבָּעִים וּשְׁנַיִם שַׁמָּשִׁים קְדוֹשִׁים עִמּוֹ, וְכָל אֶחָד וְאֶחָד אוֹת קְדוֹשָׁה עִמּוֹ מֵהַשֵּׁם הַקָּדוֹשׁ, וְכֻלָּם יָרְדוּ עִם יַעֲקֹב לְמִצְרַיִם. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב. אָמַר רַבִּי יִצְחָק, מִמַּשְׁמָע שֶׁאָמַר בְּנֵי יִשְׂרָאֵל, וְאַחַר כָּךְ אֵת יַעֲקֹב, וְלֹא נֶאֱמַר אִתּוֹ.</p>\n<p>שָׁאַל רַבִּי יְהוּדָה אֶת רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן, (אמר לו) כֵּיוָן שֶׁשָּׁמַעְתָּ מֵאָבִיךְ אֶת פָּרָשַׁת וְאֵלֶּה שְׁמוֹת בְּסוֹד עֶלְיוֹן, מַה זֶּה שֶׁאָמַר אִישׁ וּבֵיתוֹ בָּאוּ? אָמַר לוֹ, אוֹתָהּ מִלָּה שֶׁהָיָה אוֹמֵר אַבָּא, אֵלּוּ הֵם מַלְאָכִים עֶלְיוֹנִים, שֶׁהֵם מֵעַל הַתַּחְתּוֹנִים מֵהֶם. זֶהוּ שֶׁכָּתוּב אִישׁ וּבֵיתוֹ בָּאוּ. וְכָךְ אָמַר אַבָּא, כָּל אוֹתָם מַלְאָכִים שֶׁבְּדַרְגָּה עֶלְיוֹנָה, נִקְרָאִים גְּבָרִים זְכָרִים, וְאוֹתָם שֶׁבְּדַרְגָּה תַחְתּוֹנָה מֵהֶם, נִקְרָאִים (נקבות) בַּיִת, שֶׁאִשָּׁה נְקֵבָה שֶׁמְּקַבֶּלֶת מִן הַזָּכָר.</p>\n<p>רַבִּי יִצְחָק הָיָה עוֹמֵד לִפְנֵי רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן. אָמַר לוֹ, שְׁכִינָה יָרְדָה עִם יַעֲקֹב לְמִצְרַיִם? אָמַר לוֹ, וָלֹא? וַהֲרֵי כָּתוּב (בראשית מו) אָנֹכִי אֵרֵד עִמְּךְ. אָמַר לוֹ, בֹּא תִרְאֶה, שְׁכִינָה יָרְדָה לְמִצְרַיִם אֵת יַעֲקֹב, וְשֵׁשׁ מֵאוֹת אֶלֶף מֶרְכָּבוֹת קְדוֹשׁוֹת (אחרות) עִמָּהּ, וְהַיְנוּ מַה שֶּׁכָּתוּב כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי. שָׁנִינוּ, שֵׁשׁ מֵאוֹת אֶלֶף מֶרְכָּבוֹת קְדוֹשׁוֹת יָרְדוּ עִם יַעֲקֹב לְמִצְרַיִם, וְכֻלָּם עָלוּ מִשָּׁם כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. זֶהוּ שֶׁכָּתוּב (שמות יב) וַיִּסְעוּ בְנֵי יִשְׂרָאֵל מֵרַעְמְסֵס סֻכֹּתָה כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי וְגוֹ'. שֵׁשׁ מֵאוֹת לֹא נֶאֱמַר, אֶלָּא כְּשֵׁשׁ מֵאוֹת. כְּמוֹ שֶׁיָּצְאוּ אֵלֶּה, כָּךְ יָצְאוּ אֵלֶּה.</p>\n<p>וּבֹא רְאֵה סוֹד הַדָּבָר, בִּזְמַן שֶׁיָּצְאוּ הַמֶּרְכָּבוֹת הַקְּדוֹשׁוֹת הַלָּלוּ וְהַמַּחֲנוֹת הַקְּדוֹשִׁים, רָאוּ יִשְׂרָאֵל וְיָדְעוּ שֶׁהֵם מִתְעַכְּבִים בִּשְׁבִילָם, וְכָל הַחִפָּזוֹן שֶׁעָשׂוּ יִשְׂרָאֵל הָיָה בִּגְלָלָם, וְהַיְנוּ שֶׁכָּתוּב וְלֹא יָכְלוּ לְהִתְמַהְמֵהַּ, הָיָה לוֹ לוֹמַר וְלֹא רָצוּ לְהִתְמַהְמֵהַּ, אֲבָל לֹא כָתוּב אֶלָּא וְלֹא יָכְלוּ. וְנוֹדְעוּ (אז נודע) מַמָּשׁ, שֶׁכָּל בְּנֵי יִשְׂרָאֵל הָיוּ בְּנֵי יִשְׂרָאֵל שֶׁל הָרָקִיעַ, וְהַיְנוּ מַה שֶּׁכָּתוּב בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב, וְעַל זֶה לֹא נֶאֱמַר וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אִתּוֹ, אֶלָּא וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב. הַבָּאִים מִצְרָיְמָה בָּרִאשׁוֹנָה, וְעִם מִי? אֵת יַעֲקֹב.</p>\n<p>אָמַר רִבִּי יְהוּדָה, (נ\"א רבי יצחק) (נ\"א רבי יוסי) קל וחמר, ומה כשנצל יעקב מלבן כתוב (בראשית לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים - כְּשֶׁיָּרַד לַגָּלוּת וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה, אֵינוֹ דִין שֶׁהוֹאִיל וְהַפַּטְרוֹן יוֹרֵד, שֶׁיֵּרְדוּ גַּם שַׁמָּשָׁיו עִמּוֹ? הַיְנוּ שֶׁכָּתוּב הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב. רַבִּי יַעֲקֹב מִכְּפַר חָנָן אָמַר מִשְּׁמוֹ שֶׁל רַבִּי אַבָּא, מִי הֵם בְּנֵי יִשְׂרָאֵל שֶׁל כָּאן? אוֹתָם שֶׁנִּקְרְאוּ בְּנֵי יִשְׂרָאֵל מַמָּשׁ.</p>\n<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים מו) לְכוּ חֲזוּ מִפְעֲלוֹת יְיָ אֲשֶׁר שָׂם שַׁמּוֹת בָּאָרֶץ, אַל תִּקְרֵי שַׁמּוֹת אֶלָּא שֵׁמוֹת. וְהוֹלֵךְ זֶה כָּזֶה, שֶׁאָמַר רַבִּי חִיָּיא, כְּמוֹ בָּרָקִיעַ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ. בָּרָקִיעַ יֵשׁ שֵׁמוֹת קְדוֹשִׁים, וּבָאָרֶץ יֵשׁ שֵׁמוֹת קְדוֹשִׁים.</p>\n<p>אָמַר רִבִּי יְהוּדָה (נ\"א רבי יוסי), באותו יום שירד יעקב למצרים, ירדו עמו ששים רבוא מלאכים עליונים. רבי יהודה פתח, הנה מטתו שלשלמה ששים גבורים סביב וגו', שלטונים שחקוקים במפתח, סובבים במקומו השלטונים בשביעי, וחקוקים בששי. זהו שכתוב ששים גבורים סביב לה.</p>\n<p>הִנֵּה מִטָּתוֹ - זוֹהִי שְׁכִינָה. שֶׁלִּשְׁלֹמֹה - הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ - אֵלּוּ הֵם שִׁשִּׁים רִבּוֹא מַלְאָכִים עֶלְיוֹנִים, שֶׁהֵם מֵחֵיל הַשְּׁכִינָה שֶׁיָּרְדָה עִם יַעֲקֹב לְמִצְרַיִם. מִגִּבּוֹרֵי יִשְׂרָאֵל - יִשְׂרָאֵל שֶׁלְּמַעְלָה. זֶהוּ שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל וְגוֹ', אִישׁ וּבֵיתוֹ בָּאוּ - הֵם וּמִנְהֲגֵיהֶם.</p>\n<p>רַבִּי חִיָּיא הָיָה הוֹלֵךְ מֵאוּשָׁא לְלוֹד, וְהָיָה רוֹכֵב עַל חֲמוֹר, וְהָיָה רַבִּי יוֹסֵי עִמּוֹ. יָרַד רַבִּי חִיָּיא וְתָפַס יְדֵי רַבִּי יוֹסֵי. אָמַר לוֹ, אִם בְּנֵי הָעוֹלָם הָיוּ יוֹדְעִים כְּבוֹדוֹ הָרַב שֶׁל יַעֲקֹב בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה, הָיוּ מְלַחֲכִים אֶת הֶעָפָר שָׁלֹשׁ פַּרְסָאוֹת קָרוֹב לְקִבְרוֹ, שֶׁכָּךְ מְפָרְשִׁים מוֹרֵינוּ גְּדוֹלֵי עוֹלָם בַּעֲלֵי הַמִּשְׁנָה, כָּתוּב (שמות ח) וַיֵּצֵא מֹשֶׁה לִקְרַאת חֹתְנוֹ, אַהֲרֹן רָאָה שֶׁמֹּשֶׁה יוֹצֵא, וְיָצָא עִמּוֹ, וְאֶלְעָזָר וּנְשִׂיאִים וּזְקֵנִים יָצְאוּ עִמּוֹ, רָאשֵׁי אָבוֹת וּקְרוּאֵי הָעֵדָה, וְכָל יִשְׂרָאל יָצְאוּ עִמָּם. נִמְצָא שֶׁכָּל יִשְׂרָאֵל כֻּלָּם יָצְאוּ לִקְרַאת יִתְרוֹ. מִי רָאָה אֶת מֹשֶׁה יוֹצֵא וְלֹא יֵצֵא? אֶת אַהֲרֹן וְהַגְּדוֹלִים שֶׁיּוֹצְאִים וְהוּא לֹא יֵצֵא? נִמְצָא שֶׁבִּגְלַל מֹשֶׁה יָצְאוּ כֻלָּם. וּמָה אִם בִּשְׁבִיל מֹשֶׁה כָּךְ - בִּשְׁבִיל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁאָמַר אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>עֵד שֶׁהָיוּ הוֹלְכִים, פָּגַשׁ בָּהֶם רַבִּי אַבָּא. אָמַר רַבִּי יוֹסֵי, הֲרֵי שְׁכִינָה כָּאן, שֶׁאֶחָד מִבַּעֲלֵי הַמִּשְׁנָה עִמָּנוּ. אָמַר רַבִּי אַבָּא, בַּמֶּה עֲסַקְתֶּם? אָמַר רַבִּי יוֹסֵי, בַּפָּסוּק הַזֶּה שֶׁכָּתוּב אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה וְגוֹ'. כְּשֶׁיָּרַד יַעֲקֹב לְמִצְרַיִם, שֶׁכָּתוּב וְאֵלֶּה שְׁמוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מִצְרָיְמָה, אַתָּה לָמֵד שֶׁכֻּלָּם יָרְדוּ עִם יַעֲקֹב לְמִצְרַיִם.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, וְזֶה הָיָה לְחוּד? פָּתַח וְאָמַר, (יחזקאל א) הָיֹה הָיָה דְבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִּים עַל נְהַר כְּבָר. שָׁלֹשׁ קֻשְׁיוֹת כָּאן, אֶחָד - שֶׁשָּׁנִינוּ שֶׁאֵין שְׁכִינָה שׁוֹרָה בְּחוּץ לָאָרֶץ, וְאַחַת - שֶׁלֹּא הָיָה נֶאֱמָן כְּמֹשֶׁה, שֶׁכָּתוּב בּוֹ (במדבר יב) בְּכָל בֵּיתִי נֶאֱמָן הוּא, וְהוּא גִּלָּה וּפִרְסֵם אֶת כָּל גִּנְזֵי הַמֶּלֶךְ, וְאַחַת - שֶׁנִּרְאֶה כְּמִי שֶׁלֹּא שָׁלֵם בְּדַעְתּוֹ.</p>\n<p>אֶלָּא כָּךְ הִסַּקְנוּ בְּמִשְׁנָתֵנוּ, חַס וְחָלִילָה, שֶׁהֲרֵי יְחֶזְקֵאל הָיָה נָבִיא שָׁלֵם, וּבִרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא גִּלָּה כָּל מַה שֶּׁגִּלָּה, וְהַכֹּל הוּא הִצְטָרֵךְ לְגַלּוֹת וּלְפַרְסֵם, עַל כָּל אֶחָד פִּי שְׁנַיִם מִמַּה שֶּׁגִּלָּה. שֶׁכָּךְ שָׁנִינוּ, מִי שֶׁרָגִיל לִסְבֹּל צַעַר וְכוּ', וְהַכֹּל הִצְטָרֵךְ, וּמֵעוֹלָמִים לֹא עָזַב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל בַּגָּלוּת, עַד שֶׁהָיָה בָּא לָדוּר בִּמְדוֹרוֹ עִמָּהֶם, כָּל שֶׁכֵּן בְּיַעֲקֹב שֶׁהָיָה יוֹרֵד לַגָּלוּת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ וּקְדוֹשִׁים עֶלְיוֹנִים (ותחתונים) וּמֶרְכָּבוֹת, שֶׁכֻּלָּם יָרְדוּ עִם יַעֲקֹב. זֶהוּ שֶׁכָּתוּב הַבָּאִים מִצְרָיְמָה אֵת יַעֲקֹב.</p>\n<p>דָּבָר אַחֵר, רַבִּי אַבָּא פָּתַח וְאָמַר, (שיר ד) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי מִלְּבָנוֹן תָּבוֹאִי. בֹּא וּרְאֶה, אוֹי לָהֶם לִבְנֵי אָדָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בִּכְבוֹד אֲדוֹנָם, שֶׁלָּמַדְנוּ, אָמַר רַבִּי יִצְחָק, בְּכָל יוֹם וָיוֹם יוֹצֵאת בַּת קוֹל מֵהַר חוֹרֵב וְאוֹמֶרֶת: אוֹי לָהֶם לַבְּרִיּוֹת מֵעֲבוֹדַת רִבּוֹנָם! אוֹי לָהֶם לַבְּרִיּוֹת מֵעֶלְבּוֹנָהּ שֶׁל תּוֹרָה! שֶׁאָמַר רַבִּי יְהוּדָה, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה וּמְסַגֵּל מַעֲשִׂים טוֹבִים, יוֹרֵשׁ עוֹלָם שָׁלֵם. וְכָל מִי שֶׁלֹּא מִשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה וְלֹא עוֹשֶׂה מַעֲשִׂים טוֹבִים, לֹא יוֹרֵשׁ לֹא זֶה וְלֹא זֶה. וַהֲרֵי שָׁנִינוּ, יֵשׁ מִי שֶׁיּוֹרֵשׁ עוֹלָמוֹ כְּפִי מְקוֹמוֹ וּכְפִי מַה שֶּׁרָאוּי לוֹ. אָמַר רַבִּי יִצְחָק, לֹא שָׁנִינוּ אֶלָּא בְּמִי שֶׁאֵין לוֹ מַעֲשִׂים טוֹבִים כְּלָל.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִלְמָלֵא הָיוּ יוֹדְעִים בְּנֵי אָדָם אֶת הָאַהֲבָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אֶת יִשְׂרָאֵל, הָיוּ שׁוֹאֲגִים כְּמוֹ כְפִיר לִרְדּף אַחֲרָיו. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁיָּרַד יַעֲקֹב לְמִצְרַיִם, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לְפָמַלְיָה שֶׁלּוֹ וְאָמַר לָהֶם: כֻּלְּכֶם רְדוּ לְמִצְרַיִם, וַאֲנִי אֵרֵד עִמָּכֶם. אָמְרָה שְׁכִינָה: רִבּוֹן הָעוֹלָם, יֵשׁ צְבָאוֹת בְּלִי מֶלֶךְ? אָמַר לָהּ: אִתִּי מִלְּבָנוֹן כַּלָּה. מִלְּבָנוֹן - מִמְּקוֹם הָעֵדֶן, שֶׁמְּלֻבָּן בְּכָל מַעֲשָׂיו. כַּלָּה - זוֹ שְׁכִינָה, שֶׁהִיא כְּמוֹ כַלָּה בְּחֻפָּה. וְהוֹלֵךְ זֶה כְּמוֹ זֶה, שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (במדבר ז) וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה? כָּתוּב כַּלַּת, בַּיּוֹם שֶׁנִּכְנְסָה כַּלָּה לַחֻפָּה, וּשְׁכִינָה זוֹ הַכַּלָּה.</p>\n<p>אִתִּי מִלְּבָנוֹן כַּלָּה - מִמְּקוֹם בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה. תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה - מֵרֹאשׁ שֶׁל מִי? מֵרָאשֵׁיהֶם שֶׁל בְּנֵי הָאֱמוּנָה, וּמִי הֵם? יַעֲקֹב וּבָנָיו. מֵרֹאשׁ שְׂנִיר וְחֶרְמוֹן - שֶׁהֵם עֲתִידִים לְקַבֵּל אֶת הַתּוֹרָה שֶׁלִּי מֵהַר חֶרְמוֹן, וּלְהָגֵן עֲלֵיהֶם בְּגָלוּתָם. מִמְּעֹנוֹת אֲרָיוֹת - אֵלּוּ הֵם עַמִּים עוֹבְדֵי עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, (נ\"א בני אדם של אמונה) שדומים לאריות ונמרים, שמענים אותם בכל עבודה קשה.</p>\n<p>רַבִּי אַבָּא אָמַר, אִתִּי מִלְּבָנוֹן כַּלָּה וְגוֹ', וְכִי מִלְּבָנוֹן בָּאָה, וַהֲלֹא לִלְבָנוֹן עוֹלָה? אֶלָּא, אָמַר רַבִּי אַבָּא, בְּשָׁעָה שֶׁיָּרְדָה שְׁכִינָה לְמִצְרַיִם, יָרְדוּ עִמָּהּ שִׁשִּׁים רִבּוֹא שֶׁל מַלְאֲכֵי הַשָּׁרֵת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרִאשׁוֹנָה. זֶהוּ שֶׁכָּתוּב וַיַּעֲבֹר מַלְכָּם לִפְנֵיהֶם וַה' בְּרֹאשָׁם.</p>\n<p>רַבִּי יִצְחָק אָמַר, אִתִּי מִלְּבָנוֹן כַּלָּה - זוֹהִי שְׁכִינָה. אִתִּי מִלְּבָנוֹן תָּבוֹאִי - מִמְּקוֹם בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה. תָּשׁוּרִי מֵרֹאשׁ אֲמָנָה - מִמְּקוֹם בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה וּמִמְּקוֹם בֵּית הַמִּקְדָּשׁ שֶׁלְּמַטָּה. שֶׁאָמַר רַבִּי יְהוּדָה, מֵעוֹלָם לֹא זָזָה שְׁכִינָה מִכֹּתֶל הַמַּעֲרָבִי שֶׁל בֵּית הַמִּקְדָּשׁ, שֶׁכָּתוּב (שיר ב) הִנֵּה זֶה עוֹמֵד אַחַת כָּתְלֵנוּ, וְהוּא רֹאשׁ אֲמָנָה לְכָל הָעוֹלָם. מֵרֹאשׁ שְׂנִיר וְחֶרְמוֹן - מִמָּקוֹם שֶׁהַתּוֹרָה יָצְאָה לָעוֹלָם, וְלָמָּה? לְהָגֵן עַל יִשְׂרָאֵל. מִמְּעֹנוֹת אֲרָיוֹת - אֵלּוּ עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. רַבִּי יוּדָן אוֹמֵר, מִמְּעֹנוֹת אֲרָיוֹת - אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁעוֹסְקִים בַּתּוֹרָה בִּמְעוֹנוֹת הַמִּדְרָשׁוֹת וּבְבָתֵּי כְנֵסִיּוֹת, שֶׁהֵם אֲרָיוֹת וּנְמֵרִים בַּתּוֹרָה.</p>"],[9522011517,"<p>רַבִּי חִיָּיא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן, אָמַר לוֹ, מָה רָאֲתָה הַתּוֹרָה לִמְנוֹת אֶת בְּנֵי יַעֲקֹב, שֶׁהֵם שְׁנֵים עָשָׂר בַּתְּחִלָּה, וְאַחַר כָּךְ שִׁבְעִים, שֶׁכָּתוּב כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה שִׁבְעִים. וּמָה הַטַּעַם שִׁבְעִים וְלֹא יוֹתֵר? אָמַר לוֹ, כְּנֶגֶד שִׁבְעִים אֻמּוֹת שֶׁהֵם בָּעוֹלָם, וְהֵם הָיוּ אֻמָּה יְחִידָה כְּנֶגֶד כֻּלָּם.</p>\n<p>וְעוֹד אָמַר לוֹ, בּא רְאֵה, מַפְתְּחוֹת שֶׁמְּאִירִים (שרים) עֲנָפִים יוֹשְׁבִים בְּמַסְעֵיהֶם (בצלם), מְמֻנִּים עַל שִׁבְעִים עַמִּים, יוֹצְאִים מִתְּרֵיסַר חֲקִיקוֹת וְקִשּׁוּרִים שֶׁמִּסְתּוֹבְבִים בְּמַסְעוֹתֵיהֶם בְּמִשְׁקָל לְאַרְבַּע רוּחוֹת הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (דברים לב) יַצֵּב גְּבֻלֹת עַמִּים לְמִסְפַּר בְּנֵי יִשְׂרָאֵל. וְהַיְנוּ שֶׁכָּתוּב (זכריה ב) כִּי כְּאַרְבַּע רוּחוֹת הַשָּׁמַיִם פֵּרַשְׂתִּי אֶתְכֶם, לְהַרְאוֹת שֶׁהֵם עוֹמְדִים בִּשְׁבִיל יִשְׂרָאֵל. בְּאַרְבַּע לֹא נֶאֱמַר, אֶלָּא כְּאַרְבַּע. כְּמוֹ שֶׁאִי אֶפְשָׁר לָעוֹלָם בְּלִי אַרְבַּע רוּחוֹת, כָּךְ אִי אֶפְשָׁר לָעוֹלָם בְּלִי יִשְׂרָאֵל.</p>"],[9522011518,"<p>וַיָּקָם מֶלֶךְ חָדָשׁ. רַבִּי אַבָּא פָּתַח, (ישעיה לב) אַשְׁרֵיכֶם זֹרְעֵי עַל כָּל מָיִם מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וְקֵרַב אוֹתָם אֵלָיו, שֶׁכָּתוּב (דברים יד) וּבְךְ בָּחַר ה' לִהְיוֹת לוֹ לְעַם סְגֻלָּה וְגוֹ', וְכָתוּב כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. יִשְׂרָאֵל נִדְבָּקִים בַּקָּדוֹשׁ- בָּרוּךְ- הוּא, שֶׁכָּתוּב וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>וְלָכֵן זַכָּאִים הֵם לְפָנָיו, מִשּׁוּם שֶׁהֵם זוֹרְעִים עַל כָּל מַיִם. מַה זֶּה עַל כָּל מָיִם? שֶׁזּוֹרְעִים לִצְדָקָה, וּמִי שֶׁזּוֹרֵעַ לִצְדָקָה, כָּתוּב בּוֹ (תהלים נז) (זהו שכתוב כי גדל עד שמים. על כל מים, זהו שכתוב) (שם קח) כי גדול מעל שמים חסדך. מעל שמים, על כל מים הוא היה, ומי הוא מעל שמים? זה עולם הבא, וישראל זורעים על כל מים.</p>\n<p>בְּסִפְרוֹ שֶׁל רַב יֵיבָא סָבָא כָּךְ אָמַר, כָּתוּב (דניאל ד) בִּגְזֵרַת מַלְאָכִים דָּבָר, וּמַאֲמַר קְדוֹשִׁים שְׁאֵלָה. כָּל דִּינֵי הָעוֹלָם הַזֶּה וְכָל הַגְּזֵרוֹת וְכָל הַבַּקָּשׁוֹת, כֻּלָּם עוֹמְדִים בְּהֵיכָל אֶחָד שֶׁשָּׁם שִׁבְעִים וּשְׁנַיִם סַנְהֶדְרִין מְעַיְּנִים בְּדִינֵי הָעוֹלָם, וְאוֹתוֹ הֵיכָל נִקְרָא הֵיכַל הַזְּכוּת, מִשּׁוּם שֶׁכְּשֶׁדָּנִים דִּין, מְהַפְּכִים בִּזְכוּת הָאָדָם בָּרִאשׁוֹנָה.</p>\n<p>מַה שֶּׁאֵין כֵּן בְּדַרְגַּת אוֹתוֹ הַצַּד הָאַחֵר, שֶׁשָּׁם הוּא מָקוֹם שֶׁנִּקְרָא חוֹבָ\"ה, מִשּׁוּם שֶׁכָּל מַעֲשֵׂי אוֹתוֹ הַמָּקוֹם שֶׁל נָחָשׁ אֵשֶׁת זְנוּנִים אֵינוֹ אֶלָּא לְהַפֵּךְ בְּחֶטְאוֹ שֶׁל הָאָדָם, וּלְהַלְשִׁין עֶבֶד לַאֲדוֹנוֹ.</p>\n<p>אוֹתָם שֶׁל הֵיכַל הַזְּכוּת נִקְרָאִים מַיִם מְתוּקִים, מַיִם צְלוּלִים. אוֹתָם שֶׁל הֵיכַל הַחוֹבָה נִקְרָאִים מַיִם מְרִירִים, (במדבר ה) מֵי הַמָּרִים הַמְאָרַרִים. בְּאוֹתוֹ הֵיכַל הַזְּכוּת לֹא עוֹמְדִים שְׁלֹשֶׁת אֵלֶּה: בָּנִים, חַיִּים וּמְזוֹנוֹת. וְלֹא בְּאוֹתוֹ מָקוֹם שֶׁל חוֹבָה, וְלֹא בְּמַיִם מְתוּקִים וּצְלוּלִים, וְלֹא בְּמַיִם מְרִירִים מְאֹ רָרִים.</p>\n<p>וְעַל זֶה יִשְׂרָאֵל זוֹרְעִים עַל כָּל מַיִם, זֶרַע קָדוֹשׁ שֶׁהוֹלִידוּ עַל כָּל מַיִם הוּא, שֶׁהֲרֵי לֹא נָכוֹן זֶרַע שֶׁלָּהֶם אֶלָּא לְמַעְלָה. וְלָכֵן פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, בָּנִים חַיִּים וּמְזוֹנוֹת אֵין הַדָּבָר תָּלוּי בִּזְכוּת, אֶלָּא הַדָּבָר תָּלוּי בַּמַּזָּל הַקָּדוֹשׁ, וּמָקוֹם זֶה הוּא עַל כָּל מַיִם.</p>\n<p>מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר, שֶׁאֵין לָהֶם בְּאוֹתוֹ צַד הָרַע כְּלוּם, וְשׁוֹלְחִים מֵהֶם כָּל הַחֲלָקִים הָרָעִים, וְנִדְבָּקִים בְּאוֹתוֹ הַצַּד הַטּוֹב שֶׁל כָּל הַקְּדֻשּׁוֹת הָעֶלְיוֹנוֹת. שׁוֹר וַחֲמוֹר כַּאֲשֶׁר הֵם מִזְדַּוְּגִים כְּאֶחָד, הֵם שְׁנֵי פְגָעִים רָעִים לָעוֹלָם. שׁוֹר הוּא צַד הַדִּין הַקָּשֶׁה, וְהוּא נִדְבָּק בְּצַד הַקְּדֻשָּׁה. הַחֲמוֹר, כְּשֶׁמִּזְדַּוֵּג עִמּוֹ, שֶׁהוּא מִצַּד הָאַחֵר, הֵם שְׁנֵי פְגָעִים רָעִים לָעוֹלָם.</p>\n<p>וְעַל זֶה שִׁמְעוֹן הָיָה תֹּקֶף הַדִּין הַקָּשֶׁה, וּכְשֶׁמִּזְדַּוֵּג עִם לֵוִי כְּאֶחָד, לֹא יָכוֹל הָעוֹלָם לִסְבֹּל, וּמִשּׁוּם כָּךְ (דברים כב) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו. וְעַל זֶה שָׁלַח יַעֲקֹב לְעֵשָׂו דָּבָר זֶה, שֶׁכָּתוּב (בראשית לב) וַיְהִי לִי שׁוֹר וַחֲמוֹר. וְאִם יַעֲקֹב לֹא הִנְמִיךְ עַצְמוֹ, פַּחַד רַב הָיָה נוֹפֵל עַל עֵשָׂו.</p>"],[9522011519,"<p>וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרָיִם. בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא כָּךְ נֶאֱמַר, מַהוּ שֶּׁכָּתוּב וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם? בֹּא וּרְאֵה, כָּל עַמֵּי הָעוֹלָם וְכָל מַלְכֵי הָעוֹלָם לֹא הִתְחַזְּקוּ בְּשִׁלְטוֹנָם אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל. מִצְרַיִם לֹא הָיוּ שׁוֹלְטִים עַל הָעוֹלָם עַד שֶׁבָּאוּ יִשְׂרָאֵל וְנִכְנְסוּ שָׁם לַגָּלוּת, אָז הִתְחַזְּקוּ עַל שְׁאָר עַמֵּי הָעוֹלָם. בָּבֶל לֹא הִתְחַזְּקוּ עַל כָּל עַמֵּי הָעוֹלָם אֶלָּא בִּשְׁבִיל שֶׁיִּשְׂרָאֵל יִהְיוּ בַּגָּלוּת שֶׁלָּהֶם. אֱדוֹם לֹא הִתְחַזְּקוּ עַל כָּל עַמֵּי הָעוֹלָם אֶלָּא מִשּׁוּם שֶׁיִּשְׂרָאֵל יִהְיוּ בַּגָּלוּת שֶׁלָּהֶם. שֶׁהֲרֵי עַמִּים אֵלּוּ הָיוּ בְּשִׁפְלוּת בִּשְׁאָר הָעַמִּים, וּנְמוּכִים הָיוּ מִכֻּלָּם, וּבִגְלַל יִשְׂרָאֵל הִתְחַזְּקוּ.</p>\n<p>מִצְרַיִם - שֶׁכָּתוּב (שמות כ) מִבֵּית עֲבָדִים. עֲבָדִים מַמָּשׁ נִקְרְאוּ, שֶׁהֲרֵי מִצְרַיִם הָיוּ בַּשִּׁפְלוּת שֶׁל שְׁאָר הָעַמִּים. בָּבֶל - שֶׁכָּתוּב (ישעיה כג) הֵן אֶרֶץ כַּשְׂדִּים זֶה הָעָם לֹא הָיָה. אֱדוֹם - שֶׁכָּתוּב (עובדיה א) הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד.</p>\n<p>וְכֻלָּם לֹא נָטְלוּ תֹקֶף אֶלָּא בִּגְלַל יִשְׂרָאֵל. שֶׁכְּשֶׁיִּשְׂרָאֵל בַּגָּלוּת שֶׁלָּהֶם, מִיָּד מִתְחַזְּקִים עַל כָּל שְׁאָר הָעַמִּים שֶׁבָּעוֹלָם, מָה הַטַּעַם? מִשּׁוּם שֶׁיִּשְׂרָאֵל הֵם לְבַדָּם כְּנֶגֶד כָּל עַמֵּי הָעוֹלָם. כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל לְגָלוּת מִצְרַיִם, מִיָּד הָיְתָה קִימָה לְמִצְרַיִם, וְהִתְחַזֵּק שִׁלְטוֹנָם מֵעַל כָּל שְׁאָר הָעַמִּים, שֶׁכָּתוּב וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרָיִם. וַיָּקָם - קִימָה הָיְתָה לָהֶם, שֶׁהִתְחַזֵּק וְקָם אוֹתוֹ מְמֻנֶּה הַשִּׁלְטוֹן שֶׁל מִצְרֻיִם, וְנִתְּנוּ לוֹ תֹּקֶף וְשִׁלְטוֹן עַל כָּל מְמֻנֵּי שְׁאָר הָעַמִּים, שֶׁהֲרֵי בָּרִאשׁוֹנָה יֵשׁ שִׁלְטוֹן לְאוֹתוֹ הַמְמֻנֶּה שֶׁלְּמַעְלָה, וְאַחַר כָּךְ לָעָם שֶׁלּוֹ שֶׁלְּמַטָּה. וּמִשּׁוּם כָּךְ וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם. זֶהוּ הַמְמֻנֶּה שֶׁלָּהֶם, חָדָשׁ הָיָה, שֶׁעַד הַיּוֹם הַזֶּה לֹא הָיָה לוֹ שִׁלְטוֹן עַל שְׁאָר הָעַמִּים, וְעַכְשָׁו הוּקַם לִשְׁלֹט עַל כָּל שְׁאָר עַמֵּי הָעוֹלָם, וְאָז הִתְקַיֵּם (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ, תַּחַת עֶבֶד כִּי יִמְלוֹךְ.</p>\n<p>רַבִּי חִיָּיא אָמַר, שְׁלֹשִׁים יוֹם עַד שֶׁלֹּא יָבֹא תֹקֶף לָעָם בָּאָרֶץ, אוֹ עַד שֶׁלֹּא יָבֹא שֶׁבֶר לָעָם בָּאָרֶץ, מַכְרִיזִים בָּעוֹלָם עַל אוֹתוֹ הַדָּבָר, וְלִפְעָמִים שֶׁנִּמְסָר הַדָּבָר בְּפִי הַתִּינוֹקוֹת, וְלִפְעָמִים לְאוֹתָם בְּנֵי אָדָם חַסְרֵי דַעַת, וְלִפְעָמִים נִמְסָר אוֹתוֹ הַדָּבָר בְּפִי הָעוֹפוֹת, וּמַכְרִיזִים בָּעוֹלָם, וְאֵין מִי שֶׁיַּשְׁגִּיחַ בָּהֶם. כְּשֶׁהָעָם הֵם צַדִּיקִים, נִמְסָר אוֹתוֹ דָבָר לְאוֹתָם רָאשִׁים צַדִּיקִים שֶׁל הָעוֹלָם כְּדֵי שֶׁיּוֹדִיעוּ לָהֶם וְיָשׁוּבוּ לְרִבּוֹנָם, וּכְשֶׁאֵינָם צַדִּיקִים, זֶה כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב יוֹם אֶחָד עַל שַׁעַר לוֹד, וְהָיָה יוֹשֵׁב עִמּוֹ רַבִּי אַבָּא וְרַבִּי יְהוּדָה וְרַבִּי יוֹסֵי. אָמַר רַבִּי יוֹסֵי, אֹמַר לָכֶם מַה שֶּׁרָאִיתִי הַיּוֹם הַזֶּה בַּבּקֶר קַמְתִּי בָּאוֹר, רָאִיתִי עוֹף אֶחָד שֶׁהָיָה טָס וְעוֹלֶה לְמַעְלָה שָׁלֹשׁ פְּעָמִים, וּמַנְמִיךְ פַּעַם אַחַת, וְהָיָה אוֹמֵר: עֶלְיוֹנִים עֶלְיוֹנִים, בְּיוֹם זֶה פוֹרְחִים (דקיקים) הָרְקִיעִים (לימין) שְׁלֹשָׁה מְמֻנִּים זְקוּפִים מוֹשְׁלִים עַל הָאָרֶץ, אֶחָד יוֹשֵׁב שֶׁלֹּא יוֹשֵׁב, הֶעֱבִירוּ אוֹתוֹ בְּאֵשׁ דּוֹלֶקֶת, מַעֲבִירִים אֶת קִיּוּמוֹ, מַעֲבִירִים אֶת שִׁלְטוֹנוֹ. שְׁלֹשָׁה תוֹמְכִים שַׁלִּיטִים עֵלְיוֹנִים עוֹמְדִים עַל הָעוֹלָם.</p>\n<p>זָרַקְֹתִּי לְאוֹתוֹ עוֹף רֶגֶב עָפָר, וְאָמַרְתִּי לוֹ: עוֹף עוֹף, אֱמֹר לִי שְׁלֹשָׁה שֶׁעוֹמְדִים מְמֻנִּים וְאֶחָד שֶׁהֶעֱבִירוּ שִׁלְטוֹנוֹ מִי הֵם. זָרַק לִי שְׁלֹשָׁה חִצִּים מִכְּנַף יְמִינוֹ, וְזֶה אֶחָד מִשְּׂמֹאל (ומכנף שמאל אחד), וְלֹא יָדַעְתִּי לְמָה הוּא רוֹמֵז.</p>\n<p>לָקַח אוֹתָם רַבִּי אֶלְעָזָר, הוֹרִיד אוֹתָם לִנְחִירָיו, וְיָצָא דָם מִנְּחִירָיו. אָמַר, וַדַּאי שְׁלֹשָׁה שַׁלִּיטֵי עַמִּים עוֹמְדִים בְּרוֹמִי בָּאָרֶץ וַעֲתִידִים לַעֲשׂוֹת גְּזֵרוֹת רָעוֹת לְיִשְׂרָאֵל מִצַּד הָרוֹמָאִים. לָקַח אוֹתוֹ חֵץ מִכְּנַף שְׂמֹאל, הֵרִיחַ, וְיָצְאָה אֵשׁ שְׁחוֹרָה מִמֶּנּוּ. אָמַר, שִׁלְטוֹן הַמִּצְרִים הֶעֱבִירוּ, וְעָתִיד לַעֲבֹר מֶלֶךְ אֶחָד שֶׁל הָרוֹמָאִים בְּכָל הָאָרֶץ (מצרים), וּלְמַנּוֹת בְּמִצְרַיִם שָׂרֵי מִלְחָמָה גְּדוֹלִים, וְסוֹתֵר בִּנְיָן וּבוֹנֶה אֶת הַסְּתוּרִים. (ועתיד מלך אחד מאותם השלשה שאמרנו לשלט בה, וסותר בנינים ובונה בה בנינים) זָרַק אוֹתָם רַבִּי אֶלְעָזָר לָאָרֶץ. נָפְלוּ שְׁלֹשֶׁת אֵלֶּה עַל הָאֶחָד שֶׁמִּצַּד שְׂמֹאל.</p>\n<p>עַד שֶׁהָיוּ יוֹשְׁבִים, עָבַר תִּינוֹק אֶחָד וְהָיָה קוֹרֵא, (ישעיה יט) מַשָּׂא מִצְרָיִם הִנֵּה ה' רֹכֵב עַל עָב קַל וּבָא מִצְרַיִם. עָבַר חֲבֵרוֹ הַשֵּׁנִי וְאָמַר, וְאֶרֶץ מִצְרַיִם תִּהְיֶה שְׁמָמָה. עָבַר חֲבֵרוֹ הַשְּׁלִישִׁי וְאָמַר, וְאָבְדָה חָכְמַת מִצְרַיִם. רָאוּ שֶׁאוֹתוֹ חֵץ שֶׁל כְּנַף שְׂמֹאל נִשְׂרָף, וּשְׁלֹשֶׁת הָאֲחֵרִים שֶׁהָיוּ עָלָיו לֹא נִשְׂרְפוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, מַה שֶּׁאָמַר הָעוֹף וְהַתִּינוֹקוֹת, הַכֹּל דָּבָר אֶחָד, וְהַכֹּל הוּא נְבוּאָה עֶלְיוֹנָה, (והכל הוא בסוד החכמה) וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַרְאוֹת לָנוּ נִסְתָּרוֹת עֶלְיוֹנוֹת שֶׁהוּא עוֹשֶׂה. זֶהוּ שֶׁכָּתוּב (עמוס ג) כִּי לֹא יַעֲשֶׂה ה' אֱלֹהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים.</p>\n<p>וַעָדִיפִים חֲכָמִים מִנְּבִיאִים בְּכָל זְמַן, שֶׁהֲרֵי עַל הַנְּבִיאִים לִפְעָמִים שׁוֹרָה רוּחַ הַקֹּדֶשׁ וְלִפְעָמִים לֹא, וּמֵהַחֲכָמִים לֹא זָזָה רוּחַ הַקֹּדֶשׁ אֲפִלּוּ רֶגַע אֶחָד (קטן), שֶׁיּוֹדְעִים מַה שֶּׁלְּמַעְלָה וּלְמַטָּה, וְלֹא רָצוּ לְגַלּוֹת. אָמַר רַבִּי יוֹסֵי (יהודה), הַכֹּל זֶה חָכְמָה, וְחָכְמַת רַבִּי אֶלְעָזָר יְתֵרָה מִכֻּלָּם. רַבִּי אַבָּא אָמַר, אִלְמָלֵא לֹא הָיוּ חֲכָמִים, לֹא הָיוּ יוֹדְעִים בְּנֵי אָדָם מַהִי תּוֹרָה וּמָה הַמִּצְווֹת שֶׁל רִבּוֹן הָעוֹלָם, בְּלִי הֶבְדֵּל בֵּין רוּחַ בְּנֵי אָדָם לְרוּחַ הַבְּהֵמָה.</p>\n<p>אָמַר רַבִּי יִצְחָק, כְּשֶׁמֵּבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין עַל הָעָם, בָּרִאשׁוֹנָה הוּא עוֹשֶׂה דִין בְּאוֹתוֹ הַמְמֻנֶּה עֲלֵיהֶם לְמַעְלָה, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>בְּאֵיזְהִ דִין נִדּוֹן אוֹתוֹ הַמְמֻנֶּה שֶׁלְּמַעְלָה? מַעֲבִירִים אוֹתוֹ בְּאוֹתוֹ נְהַר דִּינוּר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְאָז מַעֲבִירִים אֶת אוֹתוֹ שִׁלְטוֹן שֶׁלּוֹ, וּמִיָּד מַכְרִיזִים עָלָיו בָּרָקִיעַ: שִׁלְטוֹנוֹ שֶׁל הַמְמֻנֶּה פְּלוֹנִי הָעֳבַר מִמֶּנּוּ. עַד שֶׁמַּגִּיעַ אוֹתוֹ קוֹל לְכָל אוֹתָם הָרְקִיעִים, עַד שֶׁמַּגִּיעַ לְאוֹתָם שֶׁשּׁוֹלְטִים בָּעוֹלָם הַזֶּה, וְיוֹצֵא קוֹל וּמַכְרִיז בְּכָל הָעוֹלָם, עַד שֶׁמַּגִּיעַ לָעוֹפוֹת וְלַתִּינוֹקוֹת וּלְאוֹתָם הַטִּפְּשִׁים שֶׁל בְּנֵי אָדָם שֶׁאֵין בָּהֶם דֵּעָה.</p>\n<p>וַיָּקָם מֶלֶךְ חָדָשׁ. רַבִּי חִיָּיא אָמַר, מֶלֶךְ חָדָשׁ - חָדָשׁ מַמָּשׁ הָיָה. רַבִּי יוֹסֵי אָמַר, שֶׁהָיָה מְחַדֵּשׁ גְּזֵרוֹת שֶׁלֹּא חִדֵּשׁ מֶלֶךְ אַחֵר מִקֹּדֶם לָכֵן. אֲשֶׁר לֹא יָדַע אֶת יוֹסֵף - כָּל אוֹתוֹ טוֹב שֶׁעָשָׂה יוֹסֵף בְּאֶרֶץ מִצְרַיִם, שֶׁכָּתוּב (בראשית מז) וַיָּבֵא יוֹסֵף אֶת הַכֶּסֶף בֵּיתָה פַרְעֹה, וְקִיֵּם אוֹתָם בִּשְׁנֵי הָרָעָב, כָּל זֶה לֹא זָכַר, וְעָשָׂה עַצְמוֹ שֶׁלֹּא יוֹדֵעַ אוֹתוֹ.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה הָיוּ יוֹשְׁבִים וְעוֹסְקִים בַּתּוֹרָה לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם, וְשָׁנִינוּ שֶׁהוּא קָם מֵעַצְמוֹ, מַה שֶּׁהָיָה שָׁפָל - קָם, וְלֹא רָאוּי הָיָה לִמְלֹךְ, וּבְעֹשֶׁר הוּא קָם. אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל כָּךְ הוּא, כְּמוֹ אֲחַשְׁוֵרוֹשׁ שֶׁלֹּא הָיָה רָאוּי לִמְלֹךְ, וְקָם מֵעַצְמוֹ, וְקָם בְּעֹשֶׁר, וְרָצָה לְהַאֲבִיד אֶת יִשְׂרָאֵל מִן הָעוֹלָם, אַף כָּאן זֶה לֹא רָאוּי לִמְלוּכָה, וְעָמַד מֵעַצְמוֹ, וְרָצָה לְהַאֲבִיד אֶת יִשְׂרָאֵל מִן הָעוֹלָם, שֶׁכָּתוּב וַיֹּאמֶר אֶל עַמּוֹ וְגוֹ', הָבָה נִּתְחַכְּמָה לוֹ וְגוֹ'. וּכְשֶׁהָיָה עוֹמֵד מֶלֶךְ לְמַעְלָה - עוֹמֵד מֶלֶךְ לְמַטָּה.</p>"],[9522011520,"<p>רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים מִטְּבֶרְיָה לְצִפּוֹרִי. עַד שֶׁהָיוּ הוֹלְכִים, פָּגַע בָּהֶם יְהוּדִי אֶחָד. פָּתַח וְאָמַר, (ישעיה יט) מַשָּׂא מִצְרָיִם הִנֵּה ה' רֹכֵב עַל עָב קַל וּבָא מִצְרַיִם וְנָעוּ אֱלִילֵי מִצְרַיִם מִפָּנָיו. בֹּא רְאֵה, כָּל מַלְכֵי הָעוֹלָם וְכָל עַמֵּי הָעוֹלָם לֹא נֶחְשָׁבִים לִכְלוּם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דניאל ד) וְכָל דַּיָּרֵי הָאָרֶץ כְּלֹא חֲשׁוּבִים, וְכִרְצוֹנוֹ עוֹשֶׂה בְּחֵיל הַשָּׁמַיִם. וְכָאן בְּמִצְרַיִם, אַף עַל גַּב שֶׁכָּל אוֹתָן הַגְּבוּרוֹת וּזְרוֹעַ רָמָה גִּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, מַה כָּתוּב? הִנֵּה ה' רֹכֵב עַל עָב קַל וּבָא מִצְרַיִם. מַה שּׁוֹנֶה בְּכָל עַמֵּי הָעוֹלָם שֶׁלֹּא הָיָה כָּךְ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא גָּזַר גְּזֵרָה וְנֶעֶשְׂתָה, וְכָאן הוּא בָּא, שֶׁכָּתוּב וּבָא מִצְרַיִם, וְכָתוּב (שמות יב) וְעָבַרְתִּי בְּאֶרֶץ מִצְרַיִם וְגוֹ' אֲנִי ה'?</p>\n<p>אֶלָּא מִשּׁוּם שֶׁהַמֶּלֶךְ הָיָה בָּא לְהוֹצִיא אֶת הַגְּבִירָה שֶׁהָיְתָה שָׁם, וּבִשְׁבִיל כְּבוֹד הַגְּבִירָה הָיָה בָּא. וְעַל כָּךְ הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָהּ, וּבָא אֵלֶיהָ לַהֲקִימָהּ וְלָתֵת לָהּ יָד וְלִזְקֹף אוֹתָהּ, כְּמוֹ שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בְּסוֹף גָּלוּת אֱדוֹם.</p>\n<p>אָמַר רַבִּי יֵיסָא, אִם כָּךְ שֶׁבִּשְׁבִיל הַגְּבִירָה זֶה הָיָה, הֲרֵי בְּגָלוּת בָּבֶל הָיְתָה שָׁם הַגְּבִירָה, וְלָמָּה לֹא הָיָה כָּךְ? אָמַר לוֹ, הֲרֵי שָׁנִינוּ שֶׁהַחֵטְא גָּרַם, שֶׁנָּשְׂאוּ נָשִׁים נָכְרִיּוֹת וְהִכְנִיסוּ אוֹת בְּרִית קֹדֶשׁ לְרָשׁוּת אַחֶרֶת, וְלָכֵן נֶאֶבְדוּ מֵהֶם הַנִּסִּים וְהָאוֹתוֹת שֶׁרְאוּיִים הָיוּ לְהֵעָשׂוֹת לָהֶם, מַה שֶּׁלֹּא הָיָה כָּךְ בְּגָלוּת מִצְרַיִם, שֶׁכֻּלָּם הָיוּ שִׁבְטֵי יָהּ, בְּנֵי יִשְׂרָאֵל נִכְנְסוּ, וּבְנֵי יִשְׂרָאֵל יָצְאוּ.</p>\n<p>בְּגָלוּת אֱדוֹם רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְכַּבֵּד בָּעוֹלָם וְלָבֹא הוּא לְהָקִים אֶת הַגְּבִירָה וּלְנַעֵר אוֹתָהּ מֵהֶעָפָר. אוֹי לְמִי שֶׁיִּמָּצֵא שָׁם לְפָנָיו בְּשָׁעָה שֶׁיֹּאמַר (ישעיה נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלם הִתְפַּתְּחִי מוֹסְרֵי צַוָּארֵךְ. מִי הוּא הַמֶּלֶךְ וְהָעָם שֶׁיַּעֲמֹד לְפָנָיו?</p>\n<p>וְנָעוּ אֱלִילֵי מִצְרַיִם מִפָּנָיו. אֱלִילֵי מִצְרַיִם, לֹא עַל עֵצִים וַאֲבָנִים נֶאֱמַר, אֶלָּא עַל כָּל אוֹתָם דְּרָגוֹת מְמֻנּוֹת הָעֶלְיוֹנוֹת, וְעַל אוֹתָם הָעֲבוֹדוֹת הַתַּחְתּוֹנוֹת שֶׁלָּהֶם. וּבְכָל מָקוֹם שֶׁגָּלוּ יִשְׂרָאֵל, הַקָּדוֹשׁ בָּרוּךְ הוּא מְבַקֵּשׁ עֲלֵיהֶם, וּמִתְרַעֵם וְנִפְרָע מֵאוֹתָם עַמִּים.</p>\n<p>בֹּא וּרְאֶה מַה כָּתוּב, כֹּה אָמַר ה' אֱלֹהִיִם מִצְרַיִם יָרַד עַמִּי בָרִאשנָה לָגוּר שָׁם וְאַשּׁוּר בְּאֶפֶס עֲשָׁקוֹ. תַּרְעֹמֶת שֶׁהִתְרַעֵם הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַשּׁוּר, וְאָמַר, רְאוּ מֶה עָשָׂה לִי אַשּׁוּר, שֶׁהֲרֵי בְּמִצְרַיִם שֶׁאֲנִי עָשִׂיתִי בָהֶם כָּל אוֹתָם הַדִּינִים, וְעַמִּי (הם) יָרְדוּ לְשָׁם לָדוּר בֵּינֵיהֶם, וְקִבְּלוּם הַמִּצְרִים בֵּינֵיהֶם, וְנָתְנוּ לָהֶם הַיֹּפִי שֶׁל הָאָרֶץ, אֶרֶץ גֹּשֶׁן. וְאַף עַל גַּב שֶׁהֵצִיקוּ לָהֶם בַּגָּלוּת, לֹא לָקְחוּ מֵהֶם אֶת הָאָרֶץ, שֶׁכָּתוּב (שמות ט) רַק בְּאֶרֶץ גֹּשֶׁן אֲשֶׁר שָׁם בְּנֵי יִשְׂרָאֵל וְגוֹ'. וּמֵיטַב אֶרֶץ מִצְרַיִם הָיְתָה, שֶׁכָּתוּב (בראשית מז) בְּמֵיטַב הָאָרֶץ בְּאֶרֶץ רַעְמְסֵס. וְעוֹד, שֶׁלֹּא הֶעֱבִירוּ מִשֶּׁלָּהֶם כְּלוּם, שֶׁכָּתוּב (שמות ט) וּמִמִּקְנֵה בְּנֵי יִשְׂרָאֵל וְגוֹ', וְעִם כָּל זֶה נִדּוֹנוּ בְּכַמָּה דִינִים.</p>\n<p>אֲבָל אַשּׁוּר בְּאֶפֶס עֲשָׁקוֹ, הִטִּיל אוֹתָם בְּאֶרֶץ שֶׁבְּסוֹף הָעוֹלָם, וְנָטַל אֶת אַרְצָם מֵהֶם. וּמָה הַמִּצְרִים שֶׁעָשׂוּ כָּל הַטּוֹבוֹת הַלָּלוּ לְיִשְׂרָאֵל נִדּוֹנוּ בְּכָל אוֹתָם דִּינִים - אַשּׁוּר וֶאֱדוֹם וּשְׁאָר הָעַמִּים שֶׁמְּצִיקִים לָהֶם, וְהוֹרְגִים אוֹתָם, וְנוֹטְלִים אֶת מָמוֹנָם, עַל אַחַת כַּמָּה וְכַמָּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְכַבֵּד אֶת שְׁמוֹ עֲלֵיהֶם, שֶׁכָּתוּב (יחזקאל לח) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְנוֹדַעְתִּי. שָׁם בְּמִצְרַיִם בְּמֶלֶךְ אֶחָד, וְכָאן בְּכָל מַלְכֵי הָעוֹלָם.</p>"]]});
